const CATALOG=[{"id": "aeup", "grade": "11", "subject": {"de": "AEuP", "en": "AEuP", "fa": "AEuP"}, "order": ["welt", "er", "rel", "modelle", "json"], "de": {"welt": {"title": "Datenarten", "goal": "", "definition": "Strukturierte Daten haben feste Felder. Unstrukturierte Daten haben kein festes Schema. Bestandsdaten ändern sich selten, Bewegungsdaten entstehen durch einen Vorgang.", "explanation": "Frage zuerst: festes Feld oder freier Inhalt? Danach: ändert es sich selten oder mit jedem Vorgang? Ein Kundenname ist Bestand. Jede neue Bestellung ist Bewegung und verweist auf den Kunden. Ein Foto bleibt unstrukturiert, auch wenn es in einem Ordner liegt. Die Pixel haben keine Spalten wie Name und Menge.", "example": "Die Anzahl auf einem Lieferschein ist Bewegung. Sie entsteht durch diesen einen Vorgang.", "remember": ["Bestand: Kundenstamm. Bewegung: Bestellmenge.", "Ein Ordner macht ein Foto nicht strukturiert.", "Erst sortieren, dann die Tabelle bauen."], "summary": ""}, "modelle": {"title": "Datenmodell", "goal": "", "definition": "Ein Datenmodell ist die Absprache, welche Dinge es gibt und wie sie zusammenhängen, bevor jemand eine Tabelle anlegt.", "explanation": "Nenne zuerst Dinge und Vorgänge. Skizziere danach die Beziehungen. Erst dann kommen Tabellen und Schlüssel. Wer sofort CREATE TABLE schreibt, merkt fehlende Felder erst im Betrieb. Lernfeld 8 stellt Daten systemübergreifend bereit. Der Plan muss zum Auftrag passen, nicht zur ersten Idee einer Spalte.", "example": "Für ein Ticketsystem zeichnest du Nutzer, Ticket und Techniker, bevor die erste Tabelle entsteht.", "remember": ["Modell ist der Plan. Die Tabelle ist die Umsetzung.", "Die erste Tabelle ist nicht automatisch die Wahrheit.", "Beziehungen gehören in den Plan, nicht nur Spalten."], "summary": ""}, "er": {"title": "ER-Modell", "full": true, "definition": "Eine Entität ist ein Rechteck, ein Attribut ein Oval, eine Beziehung eine Raute. Die Zahl steht neben der Entität, die sie zählt.", "goal": "Du zeichnest Entitäten, Attribute und Beziehungen in der Notation dieses Hefts, erkennst den Schlüssel an der Unterstreichung und liest 1:1, 1:n und n:m an der richtigen Seite.", "prior": "Aus der Welt der Daten weißt du, dass gespeicherte Dinge Eigenschaften haben. Ein Modell legt fest, welche Dinge es gibt, bevor jemand eine Tabelle anlegt.", "why": "Das ER-Modell wird parallel zur Datenanalyse benutzt. Sobald die Anforderungen Entitäten und Beziehungen nennen, kann ein vorläufiges Bild entstehen. Es ist die gemeinsame Skizze, bevor das relationale Modell daraus Tabellen und Fremdschlüssel macht.", "terms": [{"t": "Entität", "d": "Ein Ding, das gespeichert wird, zum Beispiel eine Abteilung. Gezeichnet als Rechteck. Entitäten entsprechen weitgehend Klassen, haben aber keine Funktionen und keine Methoden."}, {"t": "Attribut (Merkmal)", "d": "Eine Eigenschaft. Gezeichnet als Oval und mit einer Linie an der Entität oder an der Beziehung."}, {"t": "Schlüssel", "d": "Das Attribut, das jedes Objekt dieser Entität eindeutig macht. Im Diagramm ist es unterstrichen. Jede Entität hat genau einen Primärschlüssel. Ohne Unterstreichung erkennt man ihn nicht."}, {"t": "Beziehung", "d": "Die Verbindung zwischen Entitäten. Gezeichnet als Raute, mit einfachen Linien zu den Rechtecken."}, {"t": "Kardinalität", "d": "Wie viele Objekte der einen Entität zu genau einem Objekt der anderen gehören. Je Beziehung stehen genau zwei Angaben. Die Zahl steht neben der Entität, die gezählt wird."}], "steps": ["Schreibe jede Entität als Rechteck. Noch keine Felder und keine Linien.", "Hänge die Attribute als Ovale an. Ein Oval kann an einer Entität oder an einer Beziehung hängen.", "Unterstreiche in jeder Entität genau ein Schlüsselattribut.", "Setze die Beziehung als Raute zwischen die Entitäten und verbinde sie mit einfachen Linien.", "Schreibe an jede Seite eine Anzahl. Die Zahl neben einer Entität sagt, wie viele ihrer Objekte zu genau einem Objekt der anderen Entität gehören."], "example": "Das Heft zeichnet zuerst Schüler und Klasse als Rechtecke und verbindet sie mit der Raute „ist Mitschüler“. Die Fragen dazu lauten: In wie vielen Klassen ist ein Schüler Mitschüler? Wie viele Schüler hat eine Klasse? Die Zahlen selbst sind an diesem Beispiel nicht eingetragen.\n\nDie eingetragenen Zahlen stehen an drei anderen Beispielen. Die Zahl sitzt immer neben der Entität, die sie zählt.\n\nAuftrag und Rechnung: neben beiden steht 1. Zu jedem Auftrag gehört genau eine Rechnung, und jede Rechnung gehört zu genau einem Auftrag. Das ist 1:1.\n\nAbteilung und Mitarbeiter: neben Abteilung steht 1, neben Mitarbeiter steht n. Eine Abteilung hat mehrere Mitarbeiter. Jeder Mitarbeiter gehört zu genau einer Abteilung. Das ist 1:n.\n\nArtikel und Lieferant: neben Artikel steht n, neben Lieferant steht m. Ein Artikel kommt von mehreren Lieferanten, ein Lieferant liefert mehrere Artikel. Das ist n:m.\n\nDie Animation baut das Abteilungsbeispiel in derselben Reihenfolge auf. Darunter steht dasselbe Diagramm fertig, ohne dass du auf Abspielen warten musst.", "table": {"caption": "Kardinalität im Heft", "headers": ["Typ", "Was die Zahlen sagen", "Beispiel"], "rows": [["1:1", "An beiden Entitäten steht 1.", "Auftrag gehört zu Rechnung"], ["1:n", "Eine Seite 1, die andere n.", "Abteilung hat Mitarbeiter"], ["n:m", "Eine Seite n, die andere m.", "Artikel liefert Lieferant"]]}, "mistakes": ["Rechteck und Raute vertauschen. Das Ding ist das Rechteck, die Verbindung ist die Raute.", "Die Zahl an die andere Seite setzen. n neben Mitarbeiter zählt Mitarbeiter, nicht Abteilungen.", "Den Schlüssel nur im Kopf behalten und nicht unterstreichen.", "Der Entität Funktionen geben. Funktionen gehören im Heft zum Klassendiagramm, nicht zur Entität.", "Aus n:m eine einzelne Zahl machen. Es bleiben zwei Angaben.", "Eine handschriftliche Randnotiz, Attribute nur bei n:m an die Beziehung zu setzen, steht nicht im gedruckten Abschnitt. Ovale dürfen an Entitäten und an Beziehungen hängen."], "summary": "Ein ER-Modell in dieser Notation zeigt Dinge als Rechtecke, Eigenschaften als Ovale, Verbindungen als Rauten und die Anzahl als 1, n oder m direkt neben der gezählten Entität. Der Schlüssel ist das unterstrichene Attribut.", "sources": "AEuP11, S. 19–23", "anim": ["Zwei Entitäten als Rechtecke: Abteilung und Mitarbeiter.", "Attribute als Ovale: AbteilungsNr, Name, PersonalNr und Name.", "Die Schlüssel AbteilungsNr und PersonalNr sind unterstrichen.", "Die Beziehung „hat“ ist die Raute zwischen den Rechtecken.", "1 steht neben Abteilung, n neben Mitarbeiter."], "explanation": "Entitäten sind Rechtecke ohne Methoden. Attribute sind Ovale. Beziehungen sind Rauten. Der Schlüssel ist unterstrichen. Die Kardinalität steht neben der Entität, die gezählt wird.", "remember": ["Rechteck = Entität, Oval = Attribut, Raute = Beziehung.", "Schlüssel unterstreichen.", "Die Zahl zählt die Entität, neben der sie steht."]}, "rel": {"title": "Relationales Modell", "goal": "", "definition": "Das relationale Modell speichert Entitäten als Tabellen. Eine Beziehung eins-zu-viele wird zum Fremdschlüssel auf der Seite mit den vielen Zeilen.", "explanation": "Jede Entität wird eine Tabelle. Der Primärschlüssel bleibt. Die Ticket-Tabelle merkt sich die KundenID. Diese KundenID ist der Fremdschlüssel und zeigt auf den Kunden. Ein JOIN verbindet die Zeilen über diesen Schlüssel. Die KundenID nur in den Kopf zu schreiben und im Ticket zu vergessen, macht die Beziehung unsichtbar.", "example": "Kunde(KundenID, Name), Ticket(TicketID, KundenID, Datum). Die KundenID im Ticket zeigt auf genau einen Kunden.", "remember": ["Fremdschlüssel steht auf der Viele-Seite.", "1:n heißt ein Kunde, viele Tickets.", "JOIN ohne gemeinsamen Schlüssel verbindet nichts Sinnvolles."], "summary": ""}, "json": {"title": "JSON und API", "goal": "", "definition": "Eine API ist eine vereinbarte Tür zwischen zwei Systemen. JSON ist das heute übliche Textformat, in dem diese Tür Daten trägt.", "explanation": "JSON besteht aus Namen und Werten, zum Beispiel {\"ticket\": 17, \"status\": \"offen\"}. Es ist Text, kein ausführbares Programm und kein Bild. Ein REST-Aufruf holt oder ändert eine Ressource über eine Adresse. Das empfangende System muss dieselben Feldnamen erwarten. Ein Binärformat oder eine MP3-Datei ist hier nicht das Austauschformat.", "example": "Das Ticketsystem liefert {\"id\": 17, \"kunde\": 4}. Das zweite System legt damit keine neue Tabelle an, es liest die vereinbarten Felder.", "remember": ["JSON ist Text mit Namen und Werten.", "API ist die Tür, JSON oft der Inhalt.", "Feldnamen müssen auf beiden Seiten gleich gemeint sein."], "summary": ""}}, "fa": {"welt": {"title": "انواع داده", "goal": "", "definition": "داده ساخت‌یافته فیلد ثابت دارد. داده بدون ساختار طرح ثابت ندارد. داده پایه کم عوض می‌شود، داده حرکتی با یک رویداد ساخته می‌شود.", "explanation": "اول بپرس: فیلد ثابت یا محتوای آزاد؟ بعد: کم عوض می‌شود یا با هر رویداد؟ نام مشتری داده پایه است. هر سفارش تازه داده حرکتی است و به مشتری اشاره می‌کند. یک عکس بدون ساختار می‌ماند، حتی اگر در پوشه باشد. پیکسل‌ها ستون‌هایی مثل نام و مقدار ندارند.", "example": "تعداد روی برگه تحویل داده حرکتی است. با همان یک رویداد ساخته می‌شود.", "remember": ["پایه: پرونده مشتری. حرکتی: مقدار سفارش.", "پوشه یک عکس را ساخت‌یافته نمی‌کند.", "اول مرتب کن، بعد جدول را بساز."], "summary": ""}, "modelle": {"title": "مدل داده", "goal": "", "definition": "مدل داده توافق است که چه چیزهایی وجود دارند و چطور به هم مربوط‌اند، پیش از آنکه کسی جدول بسازد.", "explanation": "اول چیزها و رویدادها را نام ببر. بعد رابطه‌ها را طرح کن. تازه بعد جدول و کلید می‌آیند. اگر فوراً CREATE TABLE بنویسی، فیلدهای جاافتاده را فقط هنگام کار می‌بینی. حوزه یادگیری ۸ داده را بین سیستم‌ها فراهم می‌کند. طرح باید با سفارش بخواند، نه با اولین فکر یک ستون.", "example": "برای سامانه تیکت کاربر، تیکت و تکنسین را می‌کشی، پیش از آنکه اولین جدول باشد.", "remember": ["مدل طرح است. جدول اجراست.", "اولین جدول خودکار حقیقت نیست.", "رابطه‌ها در طرح‌اند، نه فقط ستون‌ها."], "summary": ""}, "er": {"title": "مدل ER", "full": true, "definition": "موجودیت یک `Rechteck` است، ویژگی یک `Oval`، و رابطه یک `Raute`. عدد کنار موجودیتی می‌نشیند که آن را می‌شمارد.", "goal": "موجودیت، ویژگی و رابطه را با نشانه‌گذاری همین جزوه می‌کشی، کلید را از خط زیرش می‌شناسی، و `1:1` و `1:n` و `n:m` را در سمت درست می‌خوانی.", "prior": "از دنیای داده می‌دانی که چیزهای ذخیره‌شده ویژگی دارند. مدل پیش از ساختن جدول مشخص می‌کند چه چیزهایی وجود دارند.", "why": "مدل `ER` هم‌زمان با تحلیل داده به کار می‌رود. همین که نیازها موجودیت و رابطه را نام ببرند، می‌شود یک طرح اولیه کشید. این طرح مشترک است، پیش از آنکه مدل رابطه‌ای از آن جدول و کلید خارجی بسازد.", "terms": [{"t": "موجودیت (`Entität`)", "d": "چیزی که ذخیره می‌شود، مثلاً یک بخش. به شکل مستطیل. موجودیت تا حد زیادی با کلاس یکی است، ولی تابع و متد ندارد."}, {"t": "ویژگی (`Attribut`)", "d": "یک خصوصیت. به شکل بیضی، با یک خط به موجودیت یا به رابطه."}, {"t": "کلید (`Schlüssel`)", "d": "ویژگی‌ای که هر شیء این موجودیت را یکتا می‌کند. در نمودار زیرش خط است. هر موجودیت دقیقاً یک کلید اصلی دارد. بدون خط زیر، کلید دیده نمی‌شود."}, {"t": "رابطه (`Beziehung`)", "d": "پیوند بین موجودیت‌ها. به شکل لوزی، با خط ساده تا مستطیل‌ها."}, {"t": "کاردینالیتی (`Kardinalität`)", "d": "چند شیء از یک موجودیت به دقیقاً یک شیء از موجودیت دیگر تعلق دارد. برای هر رابطه دقیقاً دو عدد است. عدد کنار موجودیتی است که شمرده می‌شود."}], "steps": ["هر موجودیت را مستطیل بنویس. هنوز فیلد و خط نه.", "ویژگی‌ها را بیضی وصل کن. بیضی می‌تواند به موجودیت یا به رابطه بچسبد.", "در هر موجودیت دقیقاً یک ویژگی کلید را زیرخط‌دار کن.", "رابطه را لوزی بین موجودیت‌ها بگذار و با خط ساده وصل کن.", "در هر سمت یک تعداد بنویس. عدد کنار یک موجودیت می‌گوید چند شیء از آن به دقیقاً یک شیء موجودیت دیگر تعلق دارد."], "example": "جزوه اول `Schüler` و `Klasse` را مستطیل می‌کشد و با لوزی `ist Mitschüler` وصل می‌کند. سؤال‌ها این‌اند: یک دانش‌آموز در چند کلاس هم‌شاگردی است؟ یک کلاس چند دانش‌آموز دارد؟ خود عددها روی این مثال نوشته نشده‌اند.\n\nعددهای نوشته‌شده روی سه مثال دیگرند. عدد همیشه کنار موجودیتی است که شمرده می‌شود.\n\n`Auftrag` و `Rechnung`: کنار هر دو `1` است. هر سفارش دقیقاً یک صورت‌حساب دارد و هر صورت‌حساب مال دقیقاً یک سفارش است. این `1:1` است.\n\n`Abteilung` و `Mitarbeiter`: کنار بخش `1` است و کنار کارمند `n`. یک بخش چند کارمند دارد. هر کارمند دقیقاً به یک بخش تعلق دارد. این `1:n` است.\n\n`Artikel` و `Lieferant`: کنار کالا `n` است و کنار تأمین‌کننده `m`. یک کالا از چند تأمین‌کننده می‌آید و یک تأمین‌کننده چند کالا می‌دهد. این `n:m` است.\n\nپویانمایی مثال بخش را با همین ترتیب می‌سازد. نمودار تمام‌شده زیر آن است و لازم نیست برای دکمه پخش منتظر بمانی.", "table": {"caption": "کاردینالیتی در جزوه", "headers": ["نوع", "عددها چه می‌گویند", "مثال"], "rows": [["`1:1`", "کنار هر دو موجودیت `1` است.", "`Auftrag` به `Rechnung` تعلق دارد"], ["`1:n`", "یک سمت `1`، سمت دیگر `n`.", "`Abteilung` کارمند دارد"], ["`n:m`", "یک سمت `n`، سمت دیگر `m`.", "`Artikel` را `Lieferant` می‌دهد"]]}, "mistakes": ["مستطیل و لوزی را جابه‌جا کردن. چیز، مستطیل است و پیوند، لوزی.", "عدد را سمت دیگر گذاشتن. `n` کنار `Mitarbeiter` کارمند را می‌شمارد، نه بخش را.", "کلید را فقط در ذهن نگه داشتن و زیرش خط نکشیدن.", "به موجودیت تابع دادن. در این جزوه تابع مال نمودار کلاس است، نه موجودیت.", "از `n:m` یک عدد تنها ساختن. همچنان دو عدد می‌ماند.", "یک یادداشت دست‌نویس در حاشیه که ویژگی را فقط برای n:m روی رابطه می‌گذارد، در متن چاپی نیست. بیضی می‌تواند به موجودیت و به رابطه بچسبد."], "summary": "مدل `ER` در این نشانه‌گذاری چیزها را مستطیل، خصوصیت‌ها را بیضی، پیوند را لوزی، و تعداد را `1` یا `n` یا `m` درست کنار موجودیت شمرده‌شده نشان می‌دهد. کلید همان ویژگی زیرخط‌دار است.", "sources": "AEuP11, S. 19–23", "anim": ["دو موجودیت به شکل مستطیل: `Abteilung` و `Mitarbeiter`.", "ویژگی‌ها به شکل بیضی: `AbteilungsNr`، `Name`، `PersonalNr` و `Name`.", "کلیدهای `AbteilungsNr` و `PersonalNr` زیرخط دارند.", "رابطه `hat` لوزی بین مستطیل‌هاست.", "`1` کنار `Abteilung` است و `n` کنار `Mitarbeiter`."], "explanation": "موجودیت مستطیل است و متد ندارد. ویژگی بیضی است. رابطه لوزی است. کلید زیرخط دارد. کاردینالیتی کنار موجودیتی است که شمرده می‌شود.", "remember": ["مستطیل = موجودیت، بیضی = ویژگی، لوزی = رابطه.", "کلید را زیرخط‌دار کن.", "عدد موجودیت کنار خودش را می‌شمارد."]}, "rel": {"title": "مدل رابطه‌ای", "goal": "", "definition": "مدل رابطه‌ای موجودیت‌ها را جدول ذخیره می‌کند. رابطه یک‌به‌چند کلید خارجی می‌شود، در سمتی که سطرهای زیاد دارد.", "explanation": "هر موجودیت یک جدول می‌شود. کلید اصلی می‌ماند. جدول تیکت شناسه مشتری را به خاطر می‌سپارد. این شناسه مشتری کلید خارجی است و به مشتری اشاره می‌کند. JOIN سطرها را با همین کلید وصل می‌کند. اگر شناسه مشتری فقط در عنوان باشد و در تیکت فراموش شود، رابطه ناپدید می‌شود.", "example": "Kunde(KundenID, Name)، Ticket(TicketID, KundenID, Datum). شناسه مشتری در تیکت به دقیقاً یک مشتری اشاره می‌کند.", "remember": ["کلید خارجی در سمت چندتایی است.", "1:n یعنی یک مشتری، چند تیکت.", "JOIN بدون کلید مشترک چیز مفیدی وصل نمی‌کند."], "summary": ""}, "json": {"title": "JSON و API", "goal": "", "definition": "API یک درِ توافق‌شده بین دو سیستم است. JSON قالب متنی رایج امروز است که این در داده را با آن حمل می‌کند.", "explanation": "JSON نام و مقدار است، مثلاً {\"ticket\": 17, \"status\": \"offen\"}. متن است، نه برنامه قابل اجرا و نه تصویر. یک فراخوانی REST یک منبع را از یک آدرس می‌گیرد یا عوض می‌کند. سیستم گیرنده باید همان نام فیلدها را انتظار داشته باشد. یک قالب دودویی یا فایل MP3 اینجا قالب تبادل نیست.", "example": "سامانه تیکت {\"id\": 17, \"kunde\": 4} می‌دهد. سیستم دوم با آن جدول نو نمی‌سازد. فیلدهای توافق‌شده را می‌خواند.", "remember": ["JSON متنی با نام و مقدار است.", "API در است، JSON اغلب محتوا.", "نام فیلدها باید در هر دو طرف یک معنی داشته باشند."], "summary": ""}}, "en": {"welt": {"title": "Kinds of data", "goal": "", "definition": "Structured data has fixed fields. Unstructured data has no fixed schema. Master data changes rarely, transaction data is created by an event.", "explanation": "Ask first: fixed field or free content? Then: does it change rarely or with every event? A customer name is master data. Each new order is transaction data and points to the customer. A photo stays unstructured even if it sits in a folder. The pixels have no columns such as name and quantity.", "example": "The quantity on a delivery note is transaction data. It is created by that one event.", "remember": ["Master: customer record. Transaction: order quantity.", "A folder does not make a photo structured.", "Sort first, then build the table."], "summary": ""}, "modelle": {"title": "Data model", "goal": "", "definition": "A data model is the agreement about which things exist and how they relate, before anyone creates a table.", "explanation": "Name things and events first. Sketch the relationships next. Only then come tables and keys. If you write CREATE TABLE immediately, you notice missing fields only in operation. Learning field 8 provides data across systems. The plan must match the order, not the first idea of a column.", "example": "For a ticket system you draw user, ticket and technician before the first table exists.", "remember": ["The model is the plan. The table is the implementation.", "The first table is not automatically the truth.", "Relationships belong in the plan, not only columns."], "summary": ""}, "er": {"title": "ER model", "full": true, "definition": "An entity is a rectangle, an attribute an oval, a relationship a diamond. The number sits beside the entity it counts.", "goal": "You draw entities, attributes and relationships in this handout’s notation, recognise the key by the underline, and read 1:1, 1:n and n:m on the correct side.", "prior": "From the world of data you know that stored things have properties. A model decides which things exist before anyone creates a table.", "why": "The ER model is used alongside the data analysis. As soon as the requirements name entities and relationships, a first sketch can be drawn. It is the shared picture before the relational model turns it into tables and foreign keys.", "terms": [{"t": "Entity", "d": "A thing that is stored, for example a department. Drawn as a rectangle. Entities largely match classes, but they have no functions and no methods."}, {"t": "Attribute", "d": "A property. Drawn as an oval and linked to the entity or to the relationship."}, {"t": "Key", "d": "The attribute that makes every object of that entity unique. In the diagram it is underlined. Each entity has exactly one primary key. Without the underline you cannot see it."}, {"t": "Relationship", "d": "The link between entities. Drawn as a diamond, with plain lines to the rectangles."}, {"t": "Cardinality", "d": "How many objects of one entity belong to exactly one object of the other. Each relationship has exactly two numbers. The number sits beside the entity it counts."}], "steps": ["Write each entity as a rectangle. No fields and no lines yet.", "Attach the attributes as ovals. An oval may hang on an entity or on a relationship.", "Underline exactly one key attribute in each entity.", "Place the relationship as a diamond between the entities and join them with plain lines.", "Write one number on each side. The number beside an entity says how many of its objects belong to exactly one object of the other entity."], "example": "The handout first draws Schüler and Klasse as rectangles and joins them with the diamond “ist Mitschüler”. The questions are: in how many classes is one student a classmate, and how many students does one class have? The numbers themselves are not written on that example.\n\nThe written numbers are on three other examples. The number always sits beside the entity it counts.\n\nAuftrag and Rechnung: 1 stands beside both. Each order has exactly one invoice, and each invoice belongs to exactly one order. That is 1:1.\n\nAbteilung and Mitarbeiter: 1 stands beside Abteilung, n beside Mitarbeiter. One department has several employees. Each employee belongs to exactly one department. That is 1:n.\n\nArtikel and Lieferant: n stands beside Artikel, m beside Lieferant. One article comes from several suppliers, and one supplier delivers several articles. That is n:m.\n\nThe animation builds the department example in that same order. The finished diagram is underneath, so you do not have to wait for Play.", "table": {"caption": "Cardinality in the handout", "headers": ["Type", "What the numbers say", "Example"], "rows": [["1:1", "1 stands beside both entities.", "An order belongs to an invoice"], ["1:n", "One side is 1, the other is n.", "A department has employees"], ["n:m", "One side is n, the other is m.", "An article is supplied by suppliers"]]}, "mistakes": ["Swapping rectangle and diamond. The thing is the rectangle, the link is the diamond.", "Putting the number on the other side. n beside Mitarbeiter counts employees, not departments.", "Keeping the key in your head and not underlining it.", "Giving the entity functions. In this handout, functions belong to the class diagram, not to the entity.", "Turning n:m into a single number. There are still two figures.", "A handwritten margin note that attributes belong on a relationship only for n:m is not in the printed section. Ovals may hang on entities and on relationships."], "summary": "An ER model in this notation shows things as rectangles, properties as ovals, links as diamonds, and the count as 1, n or m directly beside the entity being counted. The key is the underlined attribute.", "sources": "AEuP11, S. 19–23", "anim": ["Two entities as rectangles: Abteilung and Mitarbeiter.", "Attributes as ovals: AbteilungsNr, Name, PersonalNr and Name.", "The keys AbteilungsNr and PersonalNr are underlined.", "The relationship “hat” is the diamond between the rectangles.", "1 sits beside Abteilung, n beside Mitarbeiter."], "explanation": "Entities are rectangles without methods. Attributes are ovals. Relationships are diamonds. The key is underlined. The cardinality sits beside the entity it counts.", "remember": ["Rectangle = entity, oval = attribute, diamond = relationship.", "Underline the key.", "The number counts the entity it sits beside."]}, "rel": {"title": "Relational model", "goal": "", "definition": "The relational model stores entities as tables. A one-to-many relationship becomes a foreign key on the side with many rows.", "explanation": "Each entity becomes a table. The primary key stays. The ticket table remembers the customer ID. That customer ID is the foreign key and points to the customer. A JOIN connects the rows through this key. Writing the customer ID only in a heading and forgetting it in the ticket makes the relationship invisible.", "example": "Customer(CustomerID, name), Ticket(TicketID, CustomerID, date). The customer ID in the ticket points to exactly one customer.", "remember": ["The foreign key sits on the many side.", "1:n means one customer, many tickets.", "A JOIN without a shared key connects nothing useful."], "summary": ""}, "json": {"title": "JSON and API", "goal": "", "definition": "An API is an agreed door between two systems. JSON is the usual text format today in which this door carries data.", "explanation": "JSON is names and values, for example {\"ticket\": 17, \"status\": \"open\"}. It is text, not a runnable program and not a picture. A REST call fetches or changes a resource through an address. The receiving system must expect the same field names. A binary format or an MP3 file is not the exchange format here.", "example": "The ticket system returns {\"id\": 17, \"kunde\": 4}. The second system does not create a new table from that. It reads the agreed fields.", "remember": ["JSON is text with names and values.", "The API is the door, JSON is often the content.", "Field names must mean the same thing on both sides."], "summary": ""}}}, {"id": "bgwp", "grade": "11", "subject": {"de": "BGWP", "en": "BGWP", "fa": "BGWP"}, "order": ["itsm", "org", "eepk", "sla", "incident", "support"], "de": {"itsm": {"title": "IT-Servicemanagement", "goal": "", "definition": "IT-Servicemanagement organisiert, wie eine IT-Abteilung Aufträge und Störungen annimmt, bearbeitet und abschließt.", "explanation": "Der erste sinnvolle Schritt ist die vollständige Aufnahme: Wer meldet, was funktioniert nicht, seit wann, welches Gerät. Erst danach kommen Priorität und der vereinbarte Zeitraum. Ein Ticket sofort schließen oder den Hersteller anrufen, bevor die Daten stehen, vermischt Schritte. Lernfeld 6 heißt Serviceanfragen bearbeiten und liegt vor der gestreckten Abschlussprüfung Teil 1.", "example": "Eine Meldung „Drucker druckt nicht, seit 8 Uhr, Raum 12“ ist eine Aufnahme. „Ticket zu“ ohne diese Sätze ist keine.", "remember": ["Zuerst aufnehmen, dann priorisieren.", "Ohne Gerät und Zeitpunkt fehlt die Bearbeitung.", "Schließen ist der letzte Schritt, nicht der erste."], "summary": ""}, "org": {"title": "Aufbau und Ablauf", "goal": "", "definition": "Der Aufbau sagt, wer welche Stelle hat. Der Ablauf sagt, in welcher Reihenfolge die Arbeit läuft.", "explanation": "Eine Stelle im Aufbau ist zum Beispiel First-Level-Support. Der Ablauf einer Meldung ist: annehmen, einordnen, lösen oder weitergeben, zurückmelden, abschließen. Vermischt du beides, zeichnest du Personen in einen Ablauf oder eine Reihenfolge in ein Organigramm. Für die Serviceanfrage brauchst du den Ablauf, das Organigramm erklärt nur, wer den Schritt tun darf.", "example": "Das Organigramm zeigt den Supportleiter über dem First Level. Der Ablauf zeigt trotzdem zuerst die Aufnahme, nicht das Gehalt des Leiters.", "remember": ["Aufbau: wer. Ablauf: welche Reihenfolge.", "Ein Organigramm ist kein Ticketablauf.", "Weitergeben ist ein Schritt im Ablauf."], "summary": ""}, "eepk": {"title": "eEPK", "goal": "", "definition": "Eine ereignisgesteuerte Prozesskette zeigt einen Ablauf als Wechsel von Ereignis und Funktion.", "explanation": "Ein Ereignis ist ein Zustand, zum Beispiel „Meldung ist da“. Eine Funktion ist eine Tätigkeit, zum Beispiel „Daten aufnehmen“. Es beginnt und endet mit einem Ereignis, nicht mit einer Tätigkeit. Verzweigungen brauchen eine Regel: und, oder, exklusives oder. Operatoren und Funktionen direkt hintereinander ohne Ereignis dazwischen sind falsch gezeichnet.", "example": "Ereignis „Ticket angelegt“, Funktion „Priorität setzen“, Ereignis „Priorität steht“.", "remember": ["Ereignis und Funktion wechseln sich ab.", "Start und Ende sind Ereignisse.", "Eine Verzweigung braucht eine Regel."], "summary": ""}, "sla": {"title": "SLA", "goal": "", "definition": "Ein Service Level Agreement ist eine schriftliche Zusage über Reaktionszeit und Wiederherstellungszeit eines Dienstes.", "explanation": "Reaktionszeit ist, wann jemand die Meldung anfängt. Wiederherstellungszeit ist, wann der Dienst wieder nutzbar ist. Beides ist nicht dasselbe. Die Priorität bestimmt, welches Zeitfenster gilt. Ein SLA ist kein Schmuck und keine Steuererklärung. Wer es ignoriert, kann die Zusage verfehlen, auch wenn irgendwann repariert wird.", "example": "Priorität hoch: Reaktion in einer Stunde, Wiederherstellung in vier Stunden. Priorität niedrig: Reaktion am nächsten Arbeitstag.", "remember": ["Reaktion ist nicht Wiederherstellung.", "Die Zusage steht schriftlich.", "Priorität wählt das Zeitfenster."], "summary": ""}, "incident": {"title": "Incident und Problem", "goal": "", "definition": "Ein Incident ist eine aktuelle Störung eines Dienstes. Ein Problem ist die Ursache, die solche Störungen wiederkehren lässt.", "explanation": "Beim Incident zählt die schnelle Wiederherstellung. Die Ursache darf später folgen. Das Problem sucht diese Ursache, zum Beispiel ein defektes Netzteil, das jeden Montag denselben Ausfall erzeugt. Ein Antrag auf einen neuen Laptop ist kein Incident. Ein geplanter Wechsel ist ein Change, keine Störung.", "example": "Der Drucker steht jetzt. Das ist der Incident. Dass das Netzteil jede Woche ausfällt, ist das Problem.", "remember": ["Incident: jetzt kaputt, schnell zurück.", "Problem: die Ursache hinter den Wiederholungen.", "Change ist geplant, Incident nicht."], "summary": ""}, "support": {"title": "Support-Stufen", "goal": "", "definition": "Support-Stufen teilen die Bearbeitung nach Schwierigkeit. Was vorne lösbar ist, bleibt vorne.", "explanation": "First Level ist die erste Anlaufstelle: Passwort, klare Anleitung, bekannte Störung. Second Level übernimmt, wenn Fachwissen fehlt. Third Level ist oft der Hersteller oder eine Spezialgruppe. Eskalation heißt Weitergabe nach oben, nicht Beschimpfung. Deeskalation heißt, einen wütenden Menschen zu beruhigen, damit die Aufnahme überhaupt möglich ist. Nicht jede Meldung gehört sofort zum Hersteller.", "example": "Passwort zurücksetzen bleibt im First Level. Ein Firmware-Fehler am Switch geht nach oben.", "remember": ["Eskalation ist Weitergabe, keine Strafe.", "First Level löst das Bekannte.", "Deeskalation macht die Aufnahme möglich."], "summary": ""}}, "fa": {"itsm": {"title": "مدیریت خدمات IT", "goal": "", "definition": "مدیریت خدمات IT سامان می‌دهد که بخش IT سفارش و خرابی را چطور می‌پذیرد، انجام می‌دهد و می‌بندد.", "explanation": "اولین قدم مفید ثبت کامل است: چه کسی خبر می‌دهد، چه چیزی کار نمی‌کند، از کی، کدام دستگاه. تازه بعد اولویت و زمان توافق‌شده می‌آیند. بستن فوری تیکت یا زنگ زدن به سازنده پیش از نوشتن واقعیت‌ها مرحله‌ها را قاطی می‌کند. حوزه یادگیری ۶ یعنی رسیدگی به درخواست خدمات و پیش از بخش ۱ آزمون پایانی گسترده است.", "example": "گزارش «چاپگر از ساعت ۸ چاپ نمی‌کند، اتاق ۱۲» یک ثبت است. «تیکت بسته شد» بدون این جمله‌ها ثبت نیست.", "remember": ["اول ثبت کن، بعد اولویت بده.", "بدون دستگاه و زمان، رسیدگی ناقص است.", "بستن آخرین قدم است، نه اولین."], "summary": ""}, "org": {"title": "ساختار و جریان", "goal": "", "definition": "ساختار می‌گوید چه کسی کدام پست را دارد. جریان می‌گوید کار با چه ترتیبی پیش می‌رود.", "explanation": "یک پست در ساختار مثلاً پشتیبانی سطح اول است. جریان یک گزارش این است: بپذیر، دسته‌بندی کن، حل کن یا بسپار، خبر بده، ببند. اگر این دو را قاطی کنی، آدم‌ها را داخل جریان می‌کشی یا ترتیب را داخل نمودار سازمان. برای درخواست خدمات به جریان نیاز داری. نمودار فقط می‌گوید چه کسی حق آن قدم را دارد.", "example": "نمودار سازمان مدیر پشتیبانی را بالای سطح اول نشان می‌دهد. جریان با این حال با ثبت شروع می‌شود، نه با حقوق مدیر.", "remember": ["ساختار: چه کسی. جریان: چه ترتیبی.", "نمودار سازمان جریان تیکت نیست.", "سپردن یک قدم در جریان است."], "summary": ""}, "eepk": {"title": "eEPK", "goal": "", "definition": "یک زنجیره فرایند رویدادمحور جریان را به صورت جابه‌جایی رویداد و کارکرد نشان می‌دهد.", "explanation": "رویداد یک وضعیت است، مثلاً «گزارش رسیده». کارکرد یک کار است، مثلاً «داده را ثبت کن». با رویداد شروع و تمام می‌شود، نه با یک کار. شاخه‌ها یک قاعده می‌خواهند: و، یا، یاِ انحصاری. عملگر و کارکرد پشت سر هم بدون رویداد وسط، غلط کشیده شده‌اند.", "example": "رویداد «تیکت ساخته شد»، کارکرد «اولویت را بگذار»، رویداد «اولویت ثبت شد».", "remember": ["رویداد و کارکرد نوبتی می‌آیند.", "شروع و پایان رویدادند.", "شاخه یک قاعده می‌خواهد."], "summary": ""}, "sla": {"title": "SLA", "goal": "", "definition": "توافق سطح خدمت یک قول کتبی درباره زمان پاسخ و زمان بازیابی یک خدمت است.", "explanation": "زمان پاسخ یعنی کی کسی روی گزارش کار را شروع می‌کند. زمان بازیابی یعنی کی خدمت دوباره قابل استفاده است. این دو یکی نیستند. اولویت تعیین می‌کند کدام پنجره زمانی معتبر است. SLA تزئین نیست و اظهارنامه مالیات هم نیست. اگر نادیده‌اش بگیری، ممکن است قول را از دست بدهی، حتی اگر بالاخره تعمیر شود.", "example": "اولویت بالا: پاسخ ظرف یک ساعت، بازیابی ظرف چهار ساعت. اولویت پایین: پاسخ در روز کاری بعد.", "remember": ["پاسخ همان بازیابی نیست.", "قول کتبی است.", "اولویت پنجره زمانی را انتخاب می‌کند."], "summary": ""}, "incident": {"title": "Incident و Problem", "goal": "", "definition": "Incident اختلال فعلی یک خدمت است. Problem علتی است که این اختلال‌ها را برمی‌گرداند.", "explanation": "در Incident بازیابی سریع مهم است. علت می‌تواند بعد بیاید. Problem همان علت را می‌جوید، مثلاً یک منبع تغذیه خراب که هر دوشنبه همان قطعی را می‌سازد. درخواست یک لپ‌تاپ نو Incident نیست. یک تغییر برنامه‌ریزی‌شده Change است، نه اختلال.", "example": "چاپگر الان خوابیده. این Incident است. اینکه منبع تغذیه هر هفته خراب می‌شود Problem است.", "remember": ["Incident: الان خراب، سریع برگردان.", "Problem: علت پشت تکرارها.", "Change برنامه‌ریزی شده است، Incident نه."], "summary": ""}, "support": {"title": "سطح‌های پشتیبانی", "goal": "", "definition": "سطح‌های پشتیبانی کار را بر اساس سختی تقسیم می‌کنند. آنچه جلو حل می‌شود همان‌جا می‌ماند.", "explanation": "سطح اول اولین تماس است: گذرواژه، راهنمای روشن، خرابی شناخته‌شده. سطح دوم وقتی دانش تخصصی کم است کار را می‌گیرد. سطح سوم اغلب سازنده یا یک گروه متخصص است. تشدید یعنی سپردن به بالا، نه داد زدن. کاهش تنش یعنی آرام کردن آدم عصبانی تا ثبت اصلاً ممکن شود. هر گزارشی فوراً مال سازنده نیست.", "example": "بازنشانی گذرواژه در سطح اول می‌ماند. خطای میان‌افزار سوئیچ به بالا می‌رود.", "remember": ["تشدید سپردن است، نه مجازات.", "سطح اول چیز شناخته‌شده را حل می‌کند.", "کاهش تنش ثبت را ممکن می‌کند."], "summary": ""}}, "en": {"itsm": {"title": "IT service management", "goal": "", "definition": "IT service management organises how an IT department accepts, handles and closes orders and faults.", "explanation": "The first useful step is a complete record: who reports, what does not work, since when, which device. Only then come priority and the agreed time. Closing a ticket at once or calling the vendor before the facts are written mixes the steps. Learning field 6 is called handling service requests and comes before part 1 of the extended final exam.", "example": "A report “printer does not print, since 8 a.m., room 12” is a capture. “Ticket closed” without those sentences is not.", "remember": ["Capture first, then prioritise.", "Without device and time, handling is incomplete.", "Closing is the last step, not the first."], "summary": ""}, "org": {"title": "Structure and process", "goal": "", "definition": "The structure says who holds which post. The process says in which order the work runs.", "explanation": "A post in the structure is, for example, first-level support. The process of a report is: accept, classify, solve or pass on, report back, close. If you mix the two, you draw people into a process or a sequence into an organisation chart. For the service request you need the process. The chart only explains who may do the step.", "example": "The organisation chart shows the support manager above first level. The process still starts with the record, not with the manager’s salary.", "remember": ["Structure: who. Process: which order.", "An organisation chart is not a ticket process.", "Passing on is a step in the process."], "summary": ""}, "eepk": {"title": "eEPC", "goal": "", "definition": "An event-driven process chain shows a process as an alternation of event and function.", "explanation": "An event is a state, for example “report is here”. A function is an activity, for example “record the data”. It starts and ends with an event, not with an activity. Branches need a rule: and, or, exclusive or. Operators and functions directly in a row without an event between them are drawn wrong.", "example": "Event “ticket created”, function “set priority”, event “priority is set”.", "remember": ["Event and function alternate.", "Start and end are events.", "A branch needs a rule."], "summary": ""}, "sla": {"title": "SLA", "goal": "", "definition": "A service level agreement is a written promise about the response time and the recovery time of a service.", "explanation": "Response time is when someone starts on the report. Recovery time is when the service can be used again. The two are not the same. Priority decides which time window applies. An SLA is not decoration and not a tax return. If you ignore it, you can miss the promise even if the repair happens eventually.", "example": "High priority: response within one hour, recovery within four hours. Low priority: response on the next working day.", "remember": ["Response is not recovery.", "The promise is in writing.", "Priority chooses the time window."], "summary": ""}, "incident": {"title": "Incident and problem", "goal": "", "definition": "An incident is a current disruption of a service. A problem is the cause that makes such disruptions return.", "explanation": "For an incident, fast recovery counts. The cause may follow later. The problem looks for that cause, for example a faulty power supply that creates the same outage every Monday. A request for a new laptop is not an incident. A planned change is a change, not a disruption.", "example": "The printer is down now. That is the incident. That the power supply fails every week is the problem.", "remember": ["Incident: broken now, restore quickly.", "Problem: the cause behind the repeats.", "A change is planned, an incident is not."], "summary": ""}, "support": {"title": "Support levels", "goal": "", "definition": "Support levels split the work by difficulty. What can be solved at the front stays at the front.", "explanation": "First level is the first contact: password, a clear instruction, a known fault. Second level takes over when specialist knowledge is missing. Third level is often the vendor or a specialist group. Escalation means passing upward, not shouting. De-escalation means calming an angry person so the record is possible at all. Not every report belongs to the vendor immediately.", "example": "Resetting a password stays in first level. A firmware fault on the switch goes upward.", "remember": ["Escalation is a hand-off, not a punishment.", "First level solves what is known.", "De-escalation makes the record possible."], "summary": ""}}}, {"id": "englisch", "grade": "11", "subject": {"de": "Englisch", "en": "English", "fa": "انگلیسی"}, "order": ["noten", "machine", "vocab", "themen"], "de": {"noten": {"title": "Wie die Note entsteht", "goal": "", "definition": "Die Englischnote setzt sich aus drei gleich großen Teilen zusammen. Das freiwillige KMK-Zertifikat auf B1 oder B2 ersetzt diese Teile nicht.", "explanation": "Jeder Teil wiegt gleich viel. Es reicht nicht, nur eine Leistung zu üben und die anderen auszulassen. Welche drei Leistungen zählen, legt die Lehrkraft fest. Das steht nicht als geratene Liste hier. Das KMK-Fremdsprachenzertifikat ist ein zusätzliches Angebot. Wer nicht teilnimmt, verliert deshalb nicht die Zeugnisnote.", "example": "Zwei starke Teile retten einen leeren dritten Teil nicht, weil alle drei gleich zählen.", "remember": ["Drei Teile, gleiches Gewicht.", "Die Lehrkraft nennt die Teile.", "KMK B1/B2 ist freiwillig."], "summary": ""}, "machine": {"title": "Maschinencode, Assembler, Hochsprache", "goal": "", "definition": "Maschinencode führt der Prozessor direkt aus. Assembler ist eine kurze, lesbare Schreibweise dafür. Eine Hochsprache beschreibt die Aufgabe näher an der menschlichen Sprache.", "explanation": "Der Prozessor versteht nur Maschinencode. Assembler steht fast eins zu eins dafür und hängt vom Prozessortyp ab. Hochsprachen wie Python oder C verstecken Register und Sprünge. Ein Übersetzer macht daraus etwas, das ausgeführt werden kann. In Englisch brauchst du die Wörter, um einen Text über Programme zu verstehen. Du musst dafür keinen Assembler schreiben.", "example": "MOV AX, 1 ist Assembler. print(1) ist Hochsprache. Die Bytes, die der Prozessor lädt, sind Maschinencode.", "remember": ["Maschinencode läuft direkt.", "Assembler ist an den Prozessor gebunden.", "Hochsprache braucht eine Übersetzung."], "summary": ""}, "vocab": {"title": "Assemble, compile, executable", "goal": "", "definition": "To assemble macht aus Assembler-Text Maschinencode. To compile übersetzt eine Hochsprache. Executable ist die Datei, die gestartet werden kann. Ein mnemonic ist nur eine Merkhilfe.", "explanation": "Die Werkzeuge werden oft vertauscht. Der Assembler gehört zum Assembler-Text. Der Compiler gehört zur Hochsprache. Ein Interpreter führt eine Hochsprache schrittweise aus und muss keine startbare Datei hinterlassen. Die Merkhilfe, etwa „A wie Assembler, C wie C“, ersetzt die Bedeutung nicht. Sie hilft nur, die beiden Verben nicht zu mischen.", "example": "program.exe ist executable. Die Zeile MOV im Editor ist es nicht. Sie ist Quelltext.", "remember": ["Assemble gehört zu Assembler.", "Compile gehört zur Hochsprache.", "Eine Merkhilfe ist kein Ersatz für die Bedeutung."], "summary": ""}, "themen": {"title": "Hören, Lesen, IT-Nachrichten", "goal": "", "definition": "Geübt werden Hörverstehen, Leseverstehen und kurze Nachrichten aus der IT. Im Material stand als Termin Donnerstag, der 8. Oktober 2026.", "explanation": "Beim Hören beantwortest du die Frage zum Inhalt, nicht zum ersten unbekannten Wort. Beim Lesen suchst du die Stelle, die die Frage trägt. Bei einer Nachricht nennst du wer, was und welche Folge. Den Termin aus dem alten Material hältst du nicht für die aktuelle Ansage. Ob er noch gilt, sagt nur die Lehrkraft.", "example": "Ein Artikel sagt: ein Hersteller stoppt ein Update wegen eines Fehlers. Du nennst Hersteller, Stopp und Grund. Nicht jedes Adjektiv.", "remember": ["Erst die Frage, dann den Text.", "Unbekannte Wörter aus dem Satz erschließen.", "Einen alten Termin nicht mit der Ansage verwechseln."], "summary": ""}}, "fa": {"noten": {"title": "نمره چطور ساخته می‌شود", "goal": "", "definition": "نمره انگلیسی از سه بخش برابر ساخته می‌شود. گواهی داوطلبانه KMK در سطح B1 یا B2 جای این بخش‌ها را نمی‌گیرد.", "explanation": "هر بخش وزن برابر دارد. کافی نیست فقط یک عملکرد را تمرین کنی و بقیه را رها کنی. معلم تعیین می‌کند کدام سه عملکرد حساب می‌شوند. اینجا حدس زده نشده‌اند. گواهی زبان KMK یک پیشنهاد اضافه است. اگر شرکت نکنی، به این دلیل نمره کارنامه را از دست نمی‌دهی.", "example": "دو بخش قوی بخش سوم خالی را نجات نمی‌دهند، چون هر سه برابر حساب می‌شوند.", "remember": ["سه بخش، وزن برابر.", "معلم بخش‌ها را نام می‌برد.", "KMK در B1/B2 داوطلبانه است."], "summary": ""}, "machine": {"title": "کد ماشین، اسمبلی، زبان سطح بالا", "goal": "", "definition": "پردازنده کد ماشین را مستقیم اجرا می‌کند. اسمبلی یک نوشتن کوتاه و خوانا برای همان است. زبان سطح بالا کار را نزدیک‌تر به زبان انسان توصیف می‌کند.", "explanation": "پردازنده فقط کد ماشین را می‌فهمد. اسمبلی تقریباً یک‌به‌یک همان است و به نوع پردازنده وابسته است. زبان‌های سطح بالا مثل پایتون یا C ثبات و پرش را پنهان می‌کنند. یک مترجم از آن چیزی می‌سازد که اجرا شود. در انگلیسی این واژه‌ها را لازم داری تا متنی درباره برنامه را بفهمی. لازم نیست برای آن اسمبلی بنویسی.", "example": "MOV AX, 1 اسمبلی است. print(1) زبان سطح بالا است. بایت‌هایی که پردازنده بار می‌کند کد ماشین‌اند.", "remember": ["کد ماشین مستقیم اجرا می‌شود.", "اسمبلی به پردازنده وابسته است.", "زبان سطح بالا ترجمه لازم دارد."], "summary": ""}, "vocab": {"title": "اسمبل، کامپایل، اجرایی", "goal": "", "definition": "To assemble متن اسمبلی را به کد ماشین تبدیل می‌کند. To compile یک زبان سطح بالا را ترجمه می‌کند. Executable فایلی است که می‌توان اجرا کرد. mnemonic فقط یک کمک حافظه است.", "explanation": "ابزارها اغلب قاطی می‌شوند. اسمبلر مال متن اسمبلی است. کامپایلر مال زبان سطح بالا است. مفسر زبان سطح بالا را گام‌به‌گام اجرا می‌کند و لازم نیست فایلی برای اجرا باقی بگذارد. کمک حافظه، مثلاً «A برای اسمبلی، C برای C»، جای معنی را نمی‌گیرد. فقط کمک می‌کند دو فعل را قاطی نکنی.", "example": "program.exe اجرایی است. خط MOV در ویرایشگر نیست. آن متن منبع است.", "remember": ["Assemble مال اسمبلی است.", "Compile مال زبان سطح بالا است.", "کمک حافظه جای معنی نیست."], "summary": ""}, "themen": {"title": "شنیدن، خواندن، خبر IT", "goal": "", "definition": "شنیدن، خواندن و خبر کوتاه IT تمرین می‌شود. در مواد، پنجشنبه ۸ اکتبر ۲۰۲۶ به‌عنوان یک تاریخ آمده بود.", "explanation": "در شنیدن به محتوا جواب می‌دهی، نه به اولین واژه ناشناس. در خواندن جایی را پیدا می‌کنی که سؤال را نگه داشته. برای یک خبر می‌گویی چه کسی، چه چیزی و چه نتیجه‌ای. تاریخ مواد قدیمی را اعلان فعلی حساب نکن. فقط معلم می‌گوید هنوز معتبر است یا نه.", "example": "یک مقاله می‌گوید یک سازنده به‌خاطر یک خطا به‌روزرسانی را متوقف می‌کند. سازنده، توقف و دلیل را نام می‌بری. نه هر صفت را.", "remember": ["اول سؤال، بعد متن.", "واژه ناشناس را از جمله دربیاور.", "یک تاریخ قدیمی را با اعلان قاطی نکن."], "summary": ""}}, "en": {"noten": {"title": "How the grade is built", "goal": "", "definition": "The English grade is made of three equal parts. The voluntary KMK certificate at B1 or B2 does not replace those parts.", "explanation": "Each part has the same weight. It is not enough to practise only one performance and skip the others. The teacher decides which three performances count. They are not guessed here. The KMK foreign-language certificate is an extra offer. If you do not take it, you do not lose the school grade for that reason.", "example": "Two strong parts do not rescue an empty third part, because all three count the same.", "remember": ["Three parts, equal weight.", "The teacher names the parts.", "KMK B1/B2 is voluntary."], "summary": ""}, "machine": {"title": "Machine code, assembly, high-level language", "goal": "", "definition": "The processor runs machine code directly. Assembly is a short, readable way to write it. A high-level language describes the task closer to human language.", "explanation": "The processor understands only machine code. Assembly stands almost one-to-one for it and depends on the processor type. High-level languages such as Python or C hide registers and jumps. A translator turns that into something that can run. In English you need the words to understand a text about programs. You do not have to write assembly for that.", "example": "MOV AX, 1 is assembly. print(1) is a high-level language. The bytes the processor loads are machine code.", "remember": ["Machine code runs directly.", "Assembly is tied to the processor.", "A high-level language needs translation."], "summary": ""}, "vocab": {"title": "Assemble, compile, executable", "goal": "", "definition": "To assemble turns assembly text into machine code. To compile translates a high-level language. An executable is the file that can be started. A mnemonic is only a memory aid.", "explanation": "The tools are often mixed up. The assembler belongs to assembly text. The compiler belongs to a high-level language. An interpreter runs a high-level language step by step and does not have to leave a file you can start. A memory aid, such as “A for assembly, C for C”, does not replace the meaning. It only helps you not to mix up the two verbs.", "example": "program.exe is an executable. The line MOV in the editor is not. It is source text.", "remember": ["Assemble belongs to assembly.", "Compile belongs to a high-level language.", "A memory aid is not a substitute for the meaning."], "summary": ""}, "themen": {"title": "Listening, reading, IT news", "goal": "", "definition": "You practise listening, reading and short IT news. The material named Thursday 8 October 2026 as a date.", "explanation": "In listening you answer the question about the content, not about the first unknown word. In reading you find the place that carries the question. For a news item you say who, what and what follows. Do not treat the date from the old material as the current announcement. Only the teacher can say whether it still applies.", "example": "An article says a maker stops an update because of a fault. You name the maker, the stop and the reason. Not every adjective.", "remember": ["The question first, then the text.", "Work out unknown words from the sentence.", "Do not confuse an old date with the announcement."], "summary": ""}}}, {"id": "fachpraxis", "grade": "11", "subject": {"de": "Fachpraxis", "en": "Lab practice", "fa": "کار عملی"}, "order": ["szenario", "switch", "router", "dhcp", "test"], "de": {"szenario": {"title": "Szenario", "goal": "", "definition": "Das Szenario ist der Auftrag: welche Abteilungen es gibt, welche Netze sie brauchen und woran du Erfolg erkennst.", "explanation": "Zeichne zuerst Standorte, VLANs und Adressbereiche. Danach kommen Switch, Router und DHCP. Eine lose Zielzeile ohne diesen Plan wiederholt nur die Überschrift und gehört deshalb in dieses Szenario, nicht auf eine eigene Seite. Am Ende muss ein Rechner aus einem Netz einen Rechner im anderen Netz erreichen. Wenn das nicht geprüft ist, ist die Konfiguration nur eine Vermutung.", "example": "Verkauf liegt in VLAN 10, Verwaltung in VLAN 20. Ein PC im Verkauf soll den Server der Verwaltung erreichen, aber nicht deren Drucker ohne Absicht.", "remember": ["Erst skizzieren, dann Befehle.", "Jedes Netz hat eine Aufgabe und einen Adressbereich.", "Ohne Prüfung bleibt das Ergebnis offen."], "summary": ""}, "switch": {"title": "Switch und VLAN", "goal": "", "definition": "Ein Switch leitet einen Rahmen an den Port der Ziel-MAC-Adresse. Ein Access-Port trägt genau ein VLAN, ein Trunk-Port trägt mehrere VLANs mit Markierung.", "explanation": "Ohne VLAN liegen alle Ports in einer Broadcast-Domäne. Mit VLAN trennst du Abteilungen auf demselben Gerät. Zum PC hin nimmt der Access-Port die Markierung ab, weil ein normaler PC sie nicht erwartet. Zum nächsten Switch oder zum Router bleibt sie auf dem Trunk, sonst vermischen sich die Netze wieder.", "example": "Die Ports 1 bis 8 sind Access in VLAN 10. Der Uplink ist Trunk und lässt VLAN 10 und VLAN 20 durch.", "remember": ["Access: ein Endgerät, ein VLAN.", "Trunk: mehrere VLANs, mit Markierung.", "Ein PC-Port ist kein Trunk."], "summary": ""}, "router": {"title": "Router und Gateway", "goal": "", "definition": "Ein Router verbindet IP-Netze. Das Standard-Gateway ist die Router-Adresse im eigenen Netz des PCs.", "explanation": "Der PC vergleicht das Ziel mit der eigenen Maske. Liegt es außerhalb, schickt er das Paket an das Gateway. Der Router braucht in jedem angeschlossenen VLAN eine Adresse aus diesem Netz. Fehlt die Route zum Ziel, verwirft er das Paket, auch wenn das Kabel steckt. Direkt angeschlossene Netze kennt er selbst. Entferntere Netze brauchen eine weitere Route.", "example": "VLAN 10 nutzt 192.168.10.1 als Gateway, VLAN 20 nutzt 192.168.20.1. Beide Adressen liegen auf dem Router.", "remember": ["Das Gateway muss im eigenen Netz liegen.", "Pro Netz eine Router-Adresse.", "Ein Kabel ersetzt keine Route."], "summary": ""}, "dhcp": {"title": "DHCP je VLAN", "goal": "", "definition": "DHCP vergibt Adresse, Maske, Gateway und DNS. Adressen für Router, Switch und Server schließt du aus, damit sie nicht doppelt vergeben werden.", "explanation": "Jedes VLAN ist ein eigenes Netz und braucht einen eigenen Pool. Der Pool nennt das Netz, die Maske und das Gateway genau dieses VLANs. Die ausgeschlossenen Adressen legst du fest, bevor der Pool verteilt. Sonst kann ein PC die Adresse des Routers bekommen. Das ist kein Cisco-Geheimnis: erst fest vergebene Adressen schützen, dann den Rest automatisch verteilen.", "example": "Für VLAN 10 sperrst du 192.168.10.1 bis 192.168.10.10. Der Pool nutzt 192.168.10.0/24 und das Gateway 192.168.10.1. Für VLAN 20 gibt es einen zweiten Pool, nicht denselben.", "remember": ["Ein Pool pro Netz.", "Feste Adressen zuerst ausschließen.", "Gateway und DNS gehören in den Pool."], "summary": ""}, "test": {"title": "Prüfung in drei Schritten", "goal": "", "definition": "Du prüfst von nah nach fern: eigenes Gateway, Gateway des anderen Netzes, danach ein Host im anderen Netz.", "explanation": "Schritt 1 zeigt, ob Adresse, Maske und der Weg zum eigenen Router stimmen. Schritt 2 zeigt, ob der Router zwischen den Netzen weiterleitet. Schritt 3 zeigt, ob das Ziel selbst antwortet. Fällt nur Schritt 3 aus, suchst du am Ziel, nicht an der eigenen Karte. Fällt schon Schritt 1 aus, bringt eine Route weiter hinten nichts. Schreib das Ergebnis auf, bevor du etwas änderst.", "example": "192.168.10.50 erreicht 192.168.10.1, aber nicht 192.168.20.1. Der Fehler liegt am Routing, nicht an der Netzwerkkarte.", "remember": ["Immer nah vor fern.", "Ein Timeout am Ende nennt nicht die Stelle.", "Ergebnis notieren, dann ändern."], "summary": ""}}, "fa": {"szenario": {"title": "سناریو", "goal": "", "definition": "سناریو سفارش است: کدام بخش‌ها هستند، به کدام شبکه‌ها نیاز دارند و از کجا می‌فهمی کار کرده است.", "explanation": "اول مکان‌ها، VLANها و بازه‌های آدرس را بکش. بعد سوئیچ، مسیریاب و DHCP می‌آیند. یک هدف شل بدون طرح فقط عنوان را تکرار می‌کند و برای همین داخل همین سناریو است، نه در صفحه جدا. در پایان یک رایانه در یک شبکه باید به رایانه‌ای در شبکه دیگر برسد. اگر این آزموده نشده، پیکربندی فقط حدس است.", "example": "فروش VLAN 10 است، مدیریت VLAN 20. رایانه فروش باید به سرور مدیریت برسد، نه تصادفی به چاپگر آن‌ها.", "remember": ["اول طرح، بعد فرمان.", "هر شبکه یک کار و یک بازه آدرس دارد.", "بدون آزمون نتیجه باز می‌ماند."], "summary": ""}, "switch": {"title": "سوئیچ و VLAN", "goal": "", "definition": "سوئیچ قاب را به درگاه نشانی MAC مقصد می‌فرستد. درگاه Access دقیقاً یک VLAN دارد، درگاه Trunk چند VLAN را با برچسب می‌برد.", "explanation": "بدون VLAN همه درگاه‌ها در یک دامنه پخش‌اند. با VLAN بخش‌ها را روی همان دستگاه جدا می‌کنی. به سمت رایانه، درگاه Access برچسب را برمی‌دارد، چون رایانه معمولی آن را انتظار ندارد. به سمت سوئیچ بعدی یا مسیریاب برچسب روی Trunk می‌ماند، وگرنه شبکه‌ها دوباره قاطی می‌شوند.", "example": "درگاه‌های ۱ تا ۸ در VLAN 10 از نوع Access هستند. لینک بالادست Trunk است و VLAN 10 و VLAN 20 را رد می‌کند.", "remember": ["Access: یک دستگاه پایانی، یک VLAN.", "Trunk: چند VLAN، با برچسب.", "درگاه رایانه Trunk نیست."], "summary": ""}, "router": {"title": "مسیریاب و دروازه", "goal": "", "definition": "مسیریاب شبکه‌های IP را به هم وصل می‌کند. دروازه پیش‌فرض نشانی مسیریاب در شبکه خود رایانه است.", "explanation": "رایانه مقصد را با نقاب خودش مقایسه می‌کند. اگر بیرون باشد، بسته را به دروازه می‌فرستد. مسیریاب در هر VLAN متصل یک نشانی از همان شبکه لازم دارد. اگر مسیر به مقصد نباشد، بسته را دور می‌ریزد، حتی اگر کابل وصل باشد. شبکه‌های مستقیم را خودش می‌شناسد. شبکه‌های دورتر یک مسیر دیگر لازم دارند.", "example": "VLAN 10 از 192.168.10.1 به‌عنوان دروازه استفاده می‌کند، VLAN 20 از 192.168.20.1. هر دو نشانی روی مسیریاب‌اند.", "remember": ["دروازه باید در شبکه خودت باشد.", "برای هر شبکه یک نشانی مسیریاب.", "کابل جای مسیر را نمی‌گیرد."], "summary": ""}, "dhcp": {"title": "DHCP برای هر VLAN", "goal": "", "definition": "DHCP نشانی، نقاب، دروازه و DNS می‌دهد. نشانی مسیریاب، سوئیچ و سرورها را مستثنی می‌کنی تا دوباره واگذار نشوند.", "explanation": "هر VLAN شبکه خودش است و یک مخزن خودش لازم دارد. مخزن شبکه، نقاب و دروازه همان VLAN را نام می‌برد. نشانی‌های مستثنی را پیش از پخش مخزن تعیین می‌کنی. وگرنه یک رایانه می‌تواند نشانی مسیریاب را بگیرد. این راز سیسکو نیست: اول نشانی‌های ثابت را حفظ کن، بعد بقیه را خودکار بده.", "example": "برای VLAN 10 نشانی 192.168.10.1 تا 192.168.10.10 را می‌بندی. مخزن از 192.168.10.0/24 و دروازه 192.168.10.1 استفاده می‌کند. VLAN 20 یک مخزن دوم می‌گیرد، نه همان را.", "remember": ["یک مخزن برای هر شبکه.", "اول نشانی‌های ثابت را مستثنی کن.", "دروازه و DNS داخل مخزن‌اند."], "summary": ""}, "test": {"title": "آزمون در سه گام", "goal": "", "definition": "از نزدیک به دور می‌آزمایی: دروازه خودت، دروازه شبکه دیگر، بعد یک میزبان در شبکه دیگر.", "explanation": "گام ۱ نشان می‌دهد نشانی، نقاب و راه تا مسیریاب خودت درست است. گام ۲ نشان می‌دهد مسیریاب بین شبکه‌ها جلو می‌برد. گام ۳ نشان می‌دهد خود مقصد جواب می‌دهد. اگر فقط گام ۳ خراب شود، مقصد را نگاه می‌کنی، نه کارت خودت را. اگر گام ۱ همان اول خراب شود، یک مسیر دورتر کمکی نمی‌کند. نتیجه را بنویس پیش از آنکه چیزی را عوض کنی.", "example": "192.168.10.50 به 192.168.10.1 می‌رسد، ولی به 192.168.20.1 نه. خطا در مسیریابی است، نه در کارت شبکه.", "remember": ["همیشه نزدیک پیش از دور.", "یک وقفه در پایان محل را نام نمی‌برد.", "نتیجه را یادداشت کن، بعد تغییر بده."], "summary": ""}}, "en": {"szenario": {"title": "Scenario", "goal": "", "definition": "The scenario is the brief: which departments exist, which networks they need, and how you know it works.", "explanation": "Draw sites, VLANs and address ranges first. Switch, router and DHCP come after that. A loose aim with no plan only repeats the heading, so it belongs in this scenario, not on its own page. In the end a computer in one network must reach a computer in the other. If that was not tested, the configuration is only a guess.", "example": "Sales is VLAN 10, administration is VLAN 20. A PC in sales should reach the administration server, not their printer by accident.", "remember": ["Sketch first, then commands.", "Each network has a job and an address range.", "Without a test the result stays open."], "summary": ""}, "switch": {"title": "Switch and VLAN", "goal": "", "definition": "A switch forwards a frame to the port of the destination MAC address. An access port carries exactly one VLAN, a trunk port carries several VLANs with a tag.", "explanation": "Without VLANs every port shares one broadcast domain. With VLANs you separate departments on the same device. Toward the PC the access port removes the tag, because a normal PC does not expect it. Toward the next switch or the router the tag stays on the trunk, otherwise the networks mix again.", "example": "Ports 1 to 8 are access in VLAN 10. The uplink is a trunk and allows VLAN 10 and VLAN 20.", "remember": ["Access: one end device, one VLAN.", "Trunk: several VLANs, tagged.", "A PC port is not a trunk."], "summary": ""}, "router": {"title": "Router and gateway", "goal": "", "definition": "A router connects IP networks. The default gateway is the router address in the PC’s own network.", "explanation": "The PC compares the destination with its own mask. If it is outside, the PC sends the packet to the gateway. The router needs an address from each connected VLAN. If the route to the destination is missing, it drops the packet even when the cable is plugged in. It knows directly connected networks by itself. More distant networks need another route.", "example": "VLAN 10 uses 192.168.10.1 as its gateway, VLAN 20 uses 192.168.20.1. Both addresses sit on the router.", "remember": ["The gateway must be in your own network.", "One router address per network.", "A cable does not replace a route."], "summary": ""}, "dhcp": {"title": "DHCP per VLAN", "goal": "", "definition": "DHCP assigns address, mask, gateway and DNS. You exclude addresses for the router, switch and servers so they are not handed out twice.", "explanation": "Each VLAN is its own network and needs its own pool. The pool names the network, the mask and the gateway of that VLAN only. You set the excluded addresses before the pool starts handing addresses out. Otherwise a PC can receive the router’s address. This is not a Cisco secret: protect fixed addresses first, then hand out the rest automatically.", "example": "For VLAN 10 you exclude 192.168.10.1 through 192.168.10.10. The pool uses 192.168.10.0/24 and the gateway 192.168.10.1. VLAN 20 gets a second pool, not the same one.", "remember": ["One pool per network.", "Exclude fixed addresses first.", "Gateway and DNS belong in the pool."], "summary": ""}, "test": {"title": "Three-step test", "goal": "", "definition": "You test from near to far: your own gateway, the other network’s gateway, then a host in the other network.", "explanation": "Step 1 shows whether address, mask and the path to your own router are right. Step 2 shows whether the router forwards between the networks. Step 3 shows whether the destination itself answers. If only step 3 fails, you look at the destination, not at your own adapter. If step 1 already fails, a route further along will not help. Write the result down before you change anything.", "example": "192.168.10.50 reaches 192.168.10.1, but not 192.168.20.1. The fault is routing, not the network adapter.", "remember": ["Always near before far.", "A timeout at the end does not name the spot.", "Note the result, then change something."], "summary": ""}}}, {"id": "k10-aeup", "grade": "10", "subject": {"de": "AEuP Programmieren", "en": "AEuP programming", "fa": "برنامه‌نویسی AEuP"}, "order": ["sprache", "uebersetzung", "variablen", "datentypen", "fehler", "verzweigung", "schleifen", "listen"], "de": {"sprache": {"title": "Warum es Hochsprachen gibt", "goal": "", "definition": "Nahe an der Maschine schreibst du, was der Prozessor tut. Eine Hochsprache beschreibt, was das Programm tun soll. Python ist so eine Sprache.", "explanation": "Maschinencode und Assembler bleiben an den Prozessor gebunden. Hochsprachen wie Python legen die Aufgabe in lesbare Anweisungen. Im Unterricht arbeitest du mit Python, dem Editor VS Code und der PowerShell als Konsole unter Windows. Python übersetzt den Text zuerst in Bytecode und führt den dann aus. Du startest die Datei, du schreibst nicht die Bytes von Hand.", "example": "print(\"Lager\") beschreibt die Ausgabe. Den dazu passenden Maschinencode erzeugt das Laufzeitsystem.", "remember": ["Python ist eine Hochsprache.", "VS Code schreibt, PowerShell startet.", "Bytecode ist der Zwischenschritt, nicht dein Arbeitsblatt."], "summary": ""}, "uebersetzung": {"title": "Übersetzen und Ausführen", "goal": "", "definition": "Ein Compiler übersetzt das ganze Programm vor dem Lauf. Ein Interpreter führt es anweisung für Anweisung aus.", "explanation": "Der Compiler findet manche Fehler, bevor etwas startet, und liefert eine startbare Datei oder Objektcode. Der Interpreter startet sofort und meldet den Fehler an der Stelle, die gerade läuft. Python liegt dazwischen: Der Quelltext wird in Bytecode übersetzt und dieser Bytecode wird ausgeführt. Für die Klasse reicht: Du lieferst eine .py-Datei ab, kein von Hand gebautes Maschinenprogramm. Die Art der Übersetzung war Teil der Arbeit am 12.11.", "example": "Ein Tippfehler in print wird beim Start gemeldet. Du musst nicht zuerst eine exe-Datei bauen.", "remember": ["Compiler: vorher übersetzen.", "Interpreter: beim Lauf ausführen.", "Python nutzt Bytecode als Zwischenschritt."], "summary": ""}, "variablen": {"title": "Name, Typ, Wert", "goal": "", "definition": "Eine Variable hat einen Namen, einen Typ und einen Wert. Der Name ist die Beschriftung, der Wert ist der Inhalt.", "explanation": "Python unterscheidet Groß- und Kleinschreibung: anzahl und Anzahl sind zwei Namen. Die PowerShell ist bei Befehlen oft großzügig, Python nicht. Der Typ sagt, welche Operationen erlaubt sind. In Python wird der Typ beim Lauf an den Wert gebunden, nicht starr an den Namen. Trotzdem darfst du Text und Zahl nicht stillschweigend addieren. Gute Namen beschreiben den Inhalt: menge statt x.", "example": "menge = 12 legt den Namen menge, den Typ Ganzzahl und den Wert 12 an. menge = \"12\" ist Text, keine Zahl.", "remember": ["Name, Typ und Wert gehören zusammen.", "Python unterscheidet Groß und Klein.", "Text in Anführungszeichen ist keine Zahl."], "summary": ""}, "datentypen": {"title": "int, float, str, bool", "goal": "", "definition": "int ist eine ganze Zahl, float eine Kommazahl, str ein Text, bool ein Wahrheitswert wahr oder falsch.", "explanation": "Python ist dynamisch typisiert: Der Typ zeigt sich am Wert zur Laufzeit. Es ist trotzdem streng: \"3\" + 1 ist ein Fehler, keine 4. Eine schwache Typisierung würde heimlich umwandeln, wie JavaScript es bei manchen Operatoren tut. Du wandelst ausdrücklich um, etwa mit int(\"3\"). Rechnen mit Geld in float ist ungenau. Für die Klasse reicht: Kommazahl und Ganzzahl sind nicht austauschbar, nur weil beide Zahlen aussehen.", "example": "bestand = 5 ist int. preis = 1.5 ist float. name = \"Schraube\" ist str. lieferbar = True ist bool.", "remember": ["Vier Grundtypen: ganz, Komma, Text, wahr/falsch.", "Streng heißt: keine stille Mischung.", "Umwandeln schreibst du hin."], "summary": ""}, "fehler": {"title": "Drei Arten von Fehlern", "goal": "", "definition": "Ein Syntaxfehler ist ungültige Schreibweise. Ein Laufzeitfehler bricht während der Ausführung ab. Ein Logikfehler läuft durch und liefert das falsche Ergebnis.", "explanation": "Syntax: eine vergessene Klammer oder ein falsches Einrücken. Das Programm startet nicht. Laufzeit: Teilen durch null oder ein Name, den es nicht gibt. Das Programm startet und stürzt an der Stelle ab. Logik: du rechnest den Rabatt mit dem falschen Faktor, es kommt eine Zahl, nur die falsche. Tests finden Logikfehler nur, wenn du das erwartete Ergebnis kennst. Diese drei Fehlerarten gehörten zur Arbeit am 12.11.", "example": "gesamt = netto + steuer ist richtig gedacht. gesamt = netto - steuer läuft auch, ist aber logisch falsch, wenn die Steuer hinzukommen soll.", "remember": ["Syntax: startet nicht.", "Laufzeit: stürzt ab.", "Logik: falsches Ergebnis ohne Absturz."], "summary": ""}, "verzweigung": {"title": "if und elif", "goal": "", "definition": "Eine Verzweigung führt einen Block nur aus, wenn eine Bedingung wahr ist. elif prüft die nächste Bedingung, else den Rest.", "explanation": "In Python entscheidet die Einrückung, welcher Block zur Bedingung gehört. if, elif und else gehören zusammen und werden von oben nach unten geprüft. Die erste wahre Bedingung gewinnt, der Rest wird übersprungen. Ein Vergleich nutzt ==, nicht ein einzelnes =. Das = weist zu. Im Aktivitätsdiagramm ist die Raute die Entscheidung, die Pfeile sind ja und nein. Die Raute rechnet nicht, sie wählt nur den Weg. Verzweigungen und diese Darstellung gehörten zur Arbeit am 12.11.", "example": "Wenn der Bestand unter 5 liegt, wird nachbestellt, sonst nicht. Die Raute trägt „Bestand < 5“, die Zweige „ja“ und „nein“.", "remember": ["Einrückung zeigt den Block.", "== vergleicht, = weist zu.", "Die Raute ist die Entscheidung."], "summary": ""}, "schleifen": {"title": "for und while", "goal": "", "definition": "Eine Schleife wiederholt einen Block. for geht eine bekannte Folge durch. while wiederholt, solange eine Bedingung wahr ist.", "explanation": "for eignet sich für Listen und für eine feste Anzahl. while eignet sich, wenn du vorher nicht weißt, wie oft, aber wann Schluss ist. Die Bedingung muss sich im Block ändern, sonst endet while nie. Die Einrückung zeigt wieder den Körper. Schleifen und zusammengesetzte Typen waren der Stoff zum 10.12. Eine Schleife ist keine Verzweigung: if läuft höchstens einmal, die Schleife läuft wieder.", "example": "for artikel in lager: gibt jeden Artikel einmal aus. while menge > 0: muss menge im Block verringern, sonst bleibt die Schleife stehen.", "remember": ["for: bekannte Folge.", "while: bis die Bedingung fällt.", "Die Bedingung muss sich ändern."], "summary": ""}, "listen": {"title": "Listen", "goal": "", "definition": "Eine Liste speichert mehrere Werte in einer festen Reihenfolge. Der erste Index ist 0. Du kannst Werte anhängen oder ersetzen.", "explanation": "lager = [\"Mutter\", \"Schraube\"] hat zwei Einträge. lager[0] ist Mutter, lager[1] ist Schraube. lager[2] gibt es nicht und erzeugt einen Laufzeitfehler. append fügt hinten an. Eine Liste ist veränderbar, ein einzelner int nicht. Die Länge holst du mit len(lager), du zählst nicht von 1, wenn du den Index meinst. Listen gehörten zusammen mit den Schleifen zum Stoff am 10.12.", "example": "Drei Artikel: Index 0, 1 und 2. Der dritte Artikel ist Index 2, nicht Index 3.", "remember": ["Der Index beginnt bei 0.", "len liefert die Anzahl, nicht den letzten Index.", "Ein fehlender Index ist ein Laufzeitfehler."], "summary": ""}}, "fa": {"sprache": {"title": "چرا زبان سطح بالا وجود دارد", "goal": "", "definition": "نزدیک ماشین می‌نویسی پردازنده چه می‌کند. زبان سطح بالا توصیف می‌کند برنامه چه باید بکند. پایتون چنین زبانی است.", "explanation": "کد ماشین و اسمبلی به پردازنده وابسته‌اند. زبان سطح بالا مثل پایتون کار را در دستور خوانا می‌گذارد. در کلاس با پایتون، ویرایشگر VS Code و PowerShell به‌عنوان کنسول ویندوز کار می‌کنی. پایتون اول متن را به بایت‌کد تبدیل می‌کند و بعد آن را اجرا می‌کند. فایل را اجرا می‌کنی، بایت را دستی نمی‌نویسی.", "example": "print(\"Lager\") خروجی را توصیف می‌کند. سامانه اجرا کد ماشین متناظر را می‌سازد.", "remember": ["پایتون زبان سطح بالا است.", "VS Code می‌نویسد، PowerShell اجرا می‌کند.", "بایت‌کد گام میانی است، نه برگه کار تو."], "summary": ""}, "uebersetzung": {"title": "ترجمه و اجرا", "goal": "", "definition": "کامپایلر همه برنامه را پیش از اجرا ترجمه می‌کند. مفسر آن را دستور به دستور اجرا می‌کند.", "explanation": "کامپایلر بعضی خطاها را پیش از شروع پیدا می‌کند و فایلی قابل اجرا یا کد شیء می‌دهد. مفسر فوراً شروع می‌کند و خطا را در دستوری که در حال اجراست گزارش می‌کند. پایتون وسط است: متن منبع به بایت‌کد ترجمه می‌شود و آن بایت‌کد اجرا می‌شود. برای کلاس کافی است یک فایل py تحویل بدهی، نه یک برنامه ماشین دستی. نوع ترجمه جزو کار ۱۲ نوامبر بود.", "example": "یک غلط در print هنگام شروع گزارش می‌شود. لازم نیست اول یک فایل exe بسازی.", "remember": ["کامپایلر: از قبل ترجمه کن.", "مفسر: هنگام اجرا انجام بده.", "پایتون بایت‌کد را گام میانی می‌کند."], "summary": ""}, "variablen": {"title": "نام، نوع، مقدار", "goal": "", "definition": "یک متغیر نام، نوع و مقدار دارد. نام برچسب است، مقدار محتوا است.", "explanation": "پایتون حرف بزرگ و کوچک را جدا می‌کند: anzahl و Anzahl دو نام‌اند. PowerShell در فرمان اغلب شل است، پایتون نه. نوع می‌گوید کدام عمل مجاز است. در پایتون نوع هنگام اجرا به مقدار بسته می‌شود، نه سفت به نام. با این حال نمی‌توانی متن و عدد را بی‌صدا جمع کنی. نام خوب محتوا را می‌گوید: menge به‌جای x.", "example": "menge = 12 نام menge، نوع عدد صحیح و مقدار ۱۲ را می‌سازد. menge = \"12\" متن است، نه عدد.", "remember": ["نام، نوع و مقدار با هم‌اند.", "پایتون بزرگ و کوچک را جدا می‌کند.", "متن داخل گیومه عدد نیست."], "summary": ""}, "datentypen": {"title": "int، float، str، bool", "goal": "", "definition": "int عدد صحیح است، float عدد اعشاری، str متن، bool مقدار درست یا نادرست.", "explanation": "پایتون پویا نوع‌گذاری شده: نوع روی مقدار هنگام اجرا دیده می‌شود. با این حال سخت است: \"3\" + 1 خطا است، نه ۴. نوع‌گذاری ضعیف بی‌صدا تبدیل می‌کند، مثل جاوااسکریپت با بعضی عملگرها. تو صریح تبدیل می‌کنی، مثلاً با int(\"3\"). حساب پول با float نادقیق است. برای کلاس کافی است که اعشار و صحیح عوض‌شدنی نیستند فقط چون هر دو شبیه عددند.", "example": "bestand = 5 از نوع int است. preis = 1.5 از نوع float. name = \"Schraube\" از نوع str. lieferbar = True از نوع bool.", "remember": ["چهار نوع پایه: صحیح، اعشار، متن، درست/نادرست.", "سخت یعنی بدون قاطی شدن بی‌صدا.", "تبدیل را می‌نویسی."], "summary": ""}, "fehler": {"title": "سه نوع خطا", "goal": "", "definition": "خطای نحو نوشتن نامعتبر است. خطای زمان اجرا هنگام اجرا قطع می‌کند. خطای منطق تا آخر می‌رود و نتیجه غلط می‌دهد.", "explanation": "نحو: یک پرانتز جاافتاده یا تورفتگی غلط. برنامه شروع نمی‌شود. زمان اجرا: تقسیم بر صفر یا نامی که وجود ندارد. برنامه شروع می‌شود و همان‌جا می‌شکند. منطق: تخفیف را با ضریب غلط حساب می‌کنی، یک عدد می‌آید، فقط عدد غلط. آزمون خطای منطق را فقط وقتی پیدا می‌کند که نتیجه مورد انتظار را بدانی. این سه نوع خطا جزو کار ۱۲ نوامبر بودند.", "example": "gesamt = netto + steuer فکر درست است. gesamt = netto - steuer هم اجرا می‌شود، ولی اگر مالیات باید اضافه شود منطقاً غلط است.", "remember": ["نحو: شروع نمی‌شود.", "زمان اجرا: می‌شکند.", "منطق: نتیجه غلط بدون شکست."], "summary": ""}, "verzweigung": {"title": "if و elif", "goal": "", "definition": "یک شاخه یک بلوک را فقط وقتی اجرا می‌کند که شرط درست باشد. elif شرط بعدی را می‌سنجد، else بقیه را.", "explanation": "در پایتون تورفتگی تعیین می‌کند کدام بلوک مال شرط است. if و elif و else با هم‌اند و از بالا به پایین سنجیده می‌شوند. اولین شرط درست برنده است، بقیه رد می‌شود. مقایسه از == استفاده می‌کند، نه یک = تنها. = تنها مقدار می‌دهد. در نمودار فعالیت لوزی تصمیم است، پیکان‌ها بله و خیرند. لوزی حساب نمی‌کند، فقط راه را انتخاب می‌کند. شاخه و این رسم جزو کار ۱۲ نوامبر بودند.", "example": "اگر موجودی زیر ۵ باشد سفارش مجدد می‌شود، وگرنه نه. لوزی می‌گوید «موجودی < ۵»، شاخه‌ها «بله» و «خیر».", "remember": ["تورفتگی بلوک را نشان می‌دهد.", "== مقایسه می‌کند، = مقدار می‌دهد.", "لوزی تصمیم است."], "summary": ""}, "schleifen": {"title": "for و while", "goal": "", "definition": "حلقه یک بلوک را تکرار می‌کند. for یک دنباله معلوم را می‌پیماید. while تا وقتی شرط درست است تکرار می‌کند.", "explanation": "for برای فهرست و تعداد ثابت مناسب است. while وقتی مناسب است که از قبل ندانی چند بار، ولی بدانی کی تمام شود. شرط باید داخل بلوک عوض شود، وگرنه while هرگز تمام نمی‌شود. تورفتگی دوباره بدنه را نشان می‌دهد. حلقه و نوع مرکب مطلب ۱۰ دسامبر بودند. حلقه شاخه نیست: if حداکثر یک بار اجرا می‌شود، حلقه دوباره اجرا می‌شود.", "example": "for artikel in lager: هر قلم را یک بار چاپ می‌کند. while menge > 0: باید menge را داخل بلوک کم کند، وگرنه حلقه می‌ماند.", "remember": ["for: دنباله معلوم.", "while: تا شرط بیفتد.", "شرط باید عوض شود."], "summary": ""}, "listen": {"title": "فهرست", "goal": "", "definition": "یک فهرست چند مقدار را به ترتیب ثابت ذخیره می‌کند. اولین نمایه ۰ است. می‌توانی مقدار اضافه یا عوض کنی.", "explanation": "lager = [\"Mutter\", \"Schraube\"] دو مورد دارد. lager[0] مهره است، lager[1] پیچ. lager[2] وجود ندارد و خطای زمان اجرا می‌دهد. append به آخر اضافه می‌کند. فهرست تغییرپذیر است، یک int تنها نه. طول را با len(lager) می‌گیری. وقتی نمایه را می‌گویی از ۱ نمی‌شماری. فهرست همراه حلقه جزو مطلب ۱۰ دسامبر بود.", "example": "سه قلم: نمایه ۰، ۱ و ۲. قلم سوم نمایه ۲ است، نه نمایه ۳.", "remember": ["نمایه از ۰ شروع می‌شود.", "len تعداد را می‌دهد، نه آخرین نمایه.", "نمایه نبود یک خطای زمان اجرا است."], "summary": ""}}, "en": {"sprache": {"title": "Why high-level languages exist", "goal": "", "definition": "Close to the machine you write what the processor does. A high-level language describes what the program should do. Python is such a language.", "explanation": "Machine code and assembly stay tied to the processor. High-level languages such as Python put the task into readable instructions. In class you work with Python, the VS Code editor and PowerShell as the console on Windows. Python first turns the text into bytecode and then runs that. You start the file; you do not write the bytes by hand.", "example": "print(\"Lager\") describes the output. The runtime system creates the matching machine code.", "remember": ["Python is a high-level language.", "VS Code writes, PowerShell starts.", "Bytecode is the in-between step, not your worksheet."], "summary": ""}, "uebersetzung": {"title": "Translating and running", "goal": "", "definition": "A compiler translates the whole program before it runs. An interpreter runs it instruction by instruction.", "explanation": "The compiler finds some errors before anything starts and produces a file you can start or object code. The interpreter starts at once and reports the error at the instruction that is running. Python sits in between: the source is translated into bytecode and that bytecode is run. For class it is enough that you hand in a .py file, not a machine program built by hand. The kind of translation was part of the work on 12 November.", "example": "A typo in print is reported at start. You do not have to build an exe file first.", "remember": ["Compiler: translate beforehand.", "Interpreter: run during execution.", "Python uses bytecode as an in-between step."], "summary": ""}, "variablen": {"title": "Name, type, value", "goal": "", "definition": "A variable has a name, a type and a value. The name is the label, the value is the content.", "explanation": "Python distinguishes upper and lower case: anzahl and Anzahl are two names. PowerShell is often loose about commands, Python is not. The type says which operations are allowed. In Python the type is bound to the value at runtime, not rigidly to the name. Even so you may not quietly add text and a number. Good names describe the content: menge instead of x.", "example": "menge = 12 creates the name menge, the type integer and the value 12. menge = \"12\" is text, not a number.", "remember": ["Name, type and value belong together.", "Python distinguishes upper and lower case.", "Text in quotes is not a number."], "summary": ""}, "datentypen": {"title": "int, float, str, bool", "goal": "", "definition": "int is a whole number, float a decimal number, str text, bool a truth value true or false.", "explanation": "Python is dynamically typed: the type shows on the value at runtime. It is still strict: \"3\" + 1 is an error, not 4. Weak typing would convert quietly, as JavaScript does with some operators. You convert explicitly, for example with int(\"3\"). Calculating money with float is imprecise. For class it is enough that a decimal and an integer are not interchangeable just because both look like numbers.", "example": "bestand = 5 is int. preis = 1.5 is float. name = \"Schraube\" is str. lieferbar = True is bool.", "remember": ["Four basic types: whole, decimal, text, true/false.", "Strict means no quiet mixing.", "You write the conversion down."], "summary": ""}, "fehler": {"title": "Three kinds of errors", "goal": "", "definition": "A syntax error is invalid writing. A runtime error stops during execution. A logic error runs through and returns the wrong result.", "explanation": "Syntax: a forgotten bracket or wrong indentation. The program does not start. Runtime: dividing by zero or a name that does not exist. The program starts and crashes at that point. Logic: you calculate the discount with the wrong factor, a number comes out, just the wrong one. Tests find logic errors only if you know the expected result. These three kinds of errors belonged to the work on 12 November.", "example": "gesamt = netto + steuer is the right idea. gesamt = netto - steuer also runs, but it is logically wrong if the tax should be added.", "remember": ["Syntax: does not start.", "Runtime: crashes.", "Logic: wrong result without a crash."], "summary": ""}, "verzweigung": {"title": "if and elif", "goal": "", "definition": "A branch runs a block only if a condition is true. elif checks the next condition, else the rest.", "explanation": "In Python indentation decides which block belongs to the condition. if, elif and else belong together and are checked from top to bottom. The first true condition wins, the rest is skipped. A comparison uses ==, not a single =. The single = assigns. In an activity diagram the diamond is the decision, the arrows are yes and no. The diamond does not calculate, it only chooses the path. Branches and this drawing belonged to the work on 12 November.", "example": "If stock is under 5, a reorder is made, otherwise not. The diamond says “stock < 5”, the branches say “yes” and “no”.", "remember": ["Indentation shows the block.", "== compares, = assigns.", "The diamond is the decision."], "summary": ""}, "schleifen": {"title": "for and while", "goal": "", "definition": "A loop repeats a block. for walks through a known sequence. while repeats as long as a condition is true.", "explanation": "for fits lists and a fixed count. while fits when you do not know how often beforehand, but you know when to stop. The condition must change inside the block, otherwise while never ends. Indentation again shows the body. Loops and compound types were the material for 10 December. A loop is not a branch: if runs at most once, the loop runs again.", "example": "for artikel in lager: prints each item once. while menge > 0: must decrease menge inside the block, otherwise the loop stays running.", "remember": ["for: a known sequence.", "while: until the condition fails.", "The condition must change."], "summary": ""}, "listen": {"title": "Lists", "goal": "", "definition": "A list stores several values in a fixed order. The first index is 0. You can append or replace values.", "explanation": "lager = [\"Mutter\", \"Schraube\"] has two entries. lager[0] is Mutter, lager[1] is Schraube. lager[2] does not exist and raises a runtime error. append adds at the end. A list is changeable, a single int is not. You get the length with len(lager); you do not count from 1 when you mean the index. Lists belonged with the loops to the material on 10 December.", "example": "Three items: index 0, 1 and 2. The third item is index 2, not index 3.", "remember": ["The index starts at 0.", "len gives the count, not the last index.", "A missing index is a runtime error."], "summary": ""}}}, {"id": "k10-bgwp", "grade": "10", "subject": {"de": "Betriebs- und Gesamtwirtschaft", "en": "Business and economics", "fa": "اقتصاد بنگاه و کل"}, "order": ["kreislauf", "marktformen", "gruendung", "rechtsformen", "vollmacht"], "de": {"kreislauf": {"title": "Erweiterter Wirtschaftskreislauf", "goal": "", "definition": "Der erweiterte Kreislauf zeigt, wie Haushalte, Unternehmen, Staat, Banken und das Ausland Leistungen und Geld tauschen.", "explanation": "Haushalte stellen Arbeit bereit und kaufen Güter. Unternehmen zahlen Lohn und verkaufen die Güter. Der Staat nimmt Steuern und gibt Leistungen und Aufträge aus. Banken nehmen Ersparnisse und geben Kredite. Das Ausland kauft Exporte und liefert Importe. Ein Pfeil für Ware hat meist einen Gegenpfeil für Geld. Der einfache Kreislauf nur aus Haushalt und Unternehmen lässt Staat, Kredit und Ausland weg.", "example": "Du sparst Lohn auf der Bank. Die Bank gibt daraus einen Kredit an eine Firma. Das ist der Weg über die Banken, nicht ein direkter Tausch mit dem Arbeitgeber.", "remember": ["Fünf Pole: Haushalt, Unternehmen, Staat, Banken, Ausland.", "Ware und Geld laufen gegeneinander.", "Der einfache Kreislauf ist unvollständig."], "summary": ""}, "marktformen": {"title": "Marktformen", "goal": "", "definition": "Die Marktform beschreibt, wie viele Anbieter einer gleichen Leistung gegenüberstehen.", "explanation": "Polypol: viele Anbieter, etwa viele Bäckereien. Oligopol: wenige Anbieter. Im Unterricht waren das wenige große Suchmaschinen und, als lokales Bild, drei PC-Läden in Würzburg. Monopol: ein Anbieter. Auf der Nachfrageseite gibt es dieselben Ideen, etwa einen einzigen großen Abnehmer. Die Beispiele zeigen die Anzahl, nicht die Qualität der Ware. Ein Monopol ist nicht automatisch illegal, es ist zuerst eine Marktform.", "example": "Drei Läden für PCs in einer Stadt sind ein Oligopol. Viele Bäcker sind ein Polypol. Ein einziger Netzbetreiber ohne Alternative wäre ein Monopol.", "remember": ["Viele, wenige oder einer.", "Die Beispiele aus dem Unterricht merken.", "Nachfrageseite kann genauso konzentriert sein."], "summary": ""}, "gruendung": {"title": "Eine Firma gründen", "goal": "", "definition": "Eine Gründung ist die geordnete Folge von Idee, Rechtsform, Plan, Anmeldung und Start. Die Skriptseiten dazu waren Scans und sind hier nicht abgetippt.", "explanation": "Zuerst prüfst du, ob jemand die Leistung braucht. Dann wählst du die Rechtsform, weil sie Haftung und Anmeldung bestimmt. Ein einfacher Plan nennt Angebot, Kunden, Kosten und den Start. Danach kommen Gewerbeanmeldung, bei Kapitalgesellschaften das Register, das Finanzamt, ein Konto und die nötigen Verträge. Versicherungen und Verträge gehören zum Start, nicht als Nachtrag im zweiten Jahr. Das ist der übliche Weg, keine erfundene Lösung eines Arbeitsblatts.", "example": "Wer einen PC-Service anmeldet, braucht nicht zuerst ein Logo, sondern Angebot, Rechtsform und die Anmeldung beim Amt.", "remember": ["Idee und Bedarf zuerst.", "Rechtsform vor der Anmeldung klären.", "Das Skript ist nicht wörtlich übernommen."], "summary": ""}, "rechtsformen": {"title": "Rechtsformen", "goal": "", "definition": "Die Rechtsform legt fest, wer haftet, wer entscheidet und wie die Firma angemeldet wird.", "explanation": "Beim Einzelunternehmen haftet der Inhaber mit dem Geschäfts- und dem Privatvermögen. Eine GbR ist ein Zusammenschluss von mindestens zwei Personen. Eine OHG ist die handelsrechtliche Form mit unbeschränkter Haftung der Gesellschafter. Bei der KG haftet mindestens ein Komplementär unbeschränkt, die Kommanditisten nur mit ihrer Einlage. Die GmbH ist eine Kapitalgesellschaft. Für ihre Schulden haftet das Gesellschaftsvermögen, das Stammkapital beträgt mindestens 25.000 Euro. Die UG ist eine kleine Variante mit geringerem Startkapital und einer Pflicht, Gewinn zurückzulegen. Die AG ist für größere Gesellschaften mit Aktien und Aufsichtsrat. Die Seiten zu den Rechtsformen waren überwiegend Scans. Das hier ist der Überblick, keine Abschrift.", "example": "Zwei Auszubildende reparieren nebenbei ohne Gesellschaftsvertrag PCs und teilen den Gewinn. Das ist eher eine GbR als eine GmbH. Die Haftung bleibt bei den Personen.", "remember": ["Personengesellschaft: Menschen haften.", "GmbH: das Gesellschaftsvermögen haftet.", "Mindeststammkapital der GmbH: 25.000 Euro."], "summary": ""}, "vollmacht": {"title": "Prokura und Handlungsvollmacht", "goal": "", "definition": "Beide ermächtigen, für ein Handelsgeschäft zu handeln. Die Prokura ist weit und wird ins Handelsregister eingetragen. Die Handlungsvollmacht ist enger und wird nicht eingetragen.", "explanation": "Die Prokura muss ausdrücklich erteilt werden. Nach außen umfasst sie die gewöhnlichen und viele außergewöhnlichen Geschäfte. Veräußern und belasten von Grundstücken gehören nur dazu, wenn das extra erlaubt wurde. Prokura erteilen darf der Prokurist nicht. Eine interne Einschränkung bindet außenstehende Partner nicht, wenn sie davon nichts wissen. Die Handlungsvollmacht nach dem HGB deckt die gewöhnlichen Geschäfte des Betriebs. Grundstücke, das Aufnehmen von Kredit, Prozesse und Wechsel brauchen eine besondere Ermächtigung. Sie kann Generalvollmacht, Artvollmacht oder Einzelvollmacht sein.", "example": "Die Büroleitung mit Handlungsvollmacht bestellt Ware für den laufenden Verkauf. Den Verkauf des Firmengrundstücks darf sie damit nicht unterschreiben.", "remember": ["Prokura: weit, Register, ausdrücklich.", "Handlungsvollmacht: gewöhnliche Geschäfte.", "Grundstücke brauchen eine extra Erlaubnis."], "summary": ""}}, "fa": {"kreislauf": {"title": "چرخه اقتصادی گسترده", "goal": "", "definition": "چرخه گسترده نشان می‌دهد خانوار، بنگاه، دولت، بانک و خارج چطور کالا و پول را عوض می‌کنند.", "explanation": "خانوار کار می‌دهد و کالا می‌خرد. بنگاه دستمزد می‌پردازد و کالا می‌فروشد. دولت مالیات می‌گیرد و برای خدمت و سفارش خرج می‌کند. بانک پس‌انداز می‌گیرد و وام می‌دهد. خارج صادرات را می‌خرد و واردات می‌دهد. یک پیکان کالا معمولاً یک پیکان برگشت پول دارد. چرخه ساده فقط با خانوار و بنگاه، دولت و اعتبار و خارج را کنار می‌گذارد.", "example": "دستمزد را در بانک پس‌انداز می‌کنی. بانک از آن به یک شرکت وام می‌دهد. این راه از بانک است، نه معامله مستقیم با کارفرما.", "remember": ["پنج قطب: خانوار، بنگاه، دولت، بانک، خارج.", "کالا و پول خلاف هم می‌روند.", "چرخه ساده ناقص است."], "summary": ""}, "marktformen": {"title": "شکل‌های بازار", "goal": "", "definition": "شکل بازار توصیف می‌کند چند عرضه‌کننده برای یک خدمت یکسان روبه‌رو هستند.", "explanation": "پولیپول: عرضه‌کننده زیاد، مثل نانوایی‌های زیاد. الیگوپول: عرضه‌کننده کم. در کلاس این چند موتور جستجوی بزرگ بود و، به‌عنوان تصویر محلی، سه فروشگاه رایانه در وورتسبورگ. انحصار: یک عرضه‌کننده. همین فکر در سمت تقاضا هم هست، مثل یک خریدار بزرگ تنها. مثال‌ها تعداد را نشان می‌دهند، نه کیفیت کالا. انحصار خودکار غیرقانونی نیست. اول یک شکل بازار است.", "example": "سه فروشگاه رایانه در یک شهر الیگوپول است. نانوایی‌های زیاد پولیپول است. یک اپراتور شبکه بدون جایگزین انحصار می‌بود.", "remember": ["زیاد، کم یا یکی.", "مثال‌های کلاس را به خاطر بسپار.", "سمت تقاضا هم می‌تواند همین‌قدر متمرکز باشد."], "summary": ""}, "gruendung": {"title": "تأسیس یک شرکت", "goal": "", "definition": "تأسیس ترتیب منظم ایده، شکل حقوقی، طرح، ثبت و شروع است. صفحه‌های جزوه اسکن بودند و اینجا رونویسی نشده‌اند.", "explanation": "اول بررسی می‌کنی آیا کسی به خدمت نیاز دارد. بعد شکل حقوقی را انتخاب می‌کنی، چون مسئولیت و ثبت را تعیین می‌کند. یک طرح ساده پیشنهاد، مشتری، هزینه و شروع را نام می‌برد. بعد ثبت کسب، برای شرکت سرمایه ثبت تجاری، اداره مالیات، حساب و قرارداد لازم می‌آیند. بیمه و قرارداد مال شروع‌اند، نه یادداشت سال دوم. این راه معمول است، نه جواب ساختگی یک برگه.", "example": "کسی که خدمات رایانه ثبت می‌کند اول لوگو لازم ندارد، بلکه پیشنهاد، شکل حقوقی و ثبت در اداره.", "remember": ["اول ایده و نیاز.", "شکل حقوقی را پیش از ثبت روشن کن.", "جزوه کلمه‌به‌کلمه برداشته نشده."], "summary": ""}, "rechtsformen": {"title": "شکل‌های حقوقی", "goal": "", "definition": "شکل حقوقی تعیین می‌کند چه کسی مسئول است، چه کسی تصمیم می‌گیرد و شرکت چطور ثبت می‌شود.", "explanation": "در تک‌مالکی مالک با دارایی کسب و دارایی خصوصی مسئول است. GbR شراکت حداقل دو نفر است. OHG شکل تجاری با مسئولیت نامحدود شرکا است. در KG حداقل یک شریک ضامن مسئولیت نامحدود دارد، شرکای با مسئولیت محدود فقط تا آورده خود. GmbH شرکت سرمایه است. دارایی شرکت بدهی‌اش را پوشش می‌دهد و سرمایه حداقل ۲۵۰۰۰ یورو است. UG گونه کوچک با سرمایه شروع کمتر و وظیفه کنار گذاشتن سود است. AG برای شرکت بزرگ‌تر با سهم و هیئت نظارت است. صفحه‌های شکل حقوقی بیشتر اسکن بودند. این مرور است، نه رونوشت.", "example": "دو کارآموز کنار کار بدون اساسنامه رایانه تعمیر می‌کنند و سود را تقسیم می‌کنند. این بیشتر GbR است تا GmbH. مسئولیت پیش اشخاص می‌ماند.", "remember": ["شرکت اشخاص: آدم‌ها مسئول‌اند.", "GmbH: دارایی شرکت مسئول است.", "حداقل سرمایه GmbH: ۲۵۰۰۰ یورو."], "summary": ""}, "vollmacht": {"title": "پروکورا و اختیار تجاری", "goal": "", "definition": "هر دو اجازه می‌دهند کسی برای یک کسب تجاری عمل کند. پروکورا گسترده است و در ثبت تجاری نوشته می‌شود. اختیار تجاری باریک‌تر است و ثبت نمی‌شود.", "explanation": "پروکورا باید صریح داده شود. به بیرون معامله عادی و بسیاری معامله غیرعادی را می‌پوشاند. فروش و وثیقه زمین فقط وقتی داخل آن است که جدا اجازه شده باشد. دارنده پروکورا نمی‌تواند پروکورا بدهد. یک محدودیت داخلی شریک بیرونی را مقید نمی‌کند اگر از آن خبر نداشته باشد. اختیار تجاری طبق قانون تجارت معامله عادی بنگاه را می‌پوشاند. زمین، گرفتن اعتبار، دعوا و برات اجازه خاص لازم دارند. می‌تواند کلی، نوعی یا برای یک معامله باشد.", "example": "مسئول دفتر با اختیار تجاری کالا برای فروش جاری سفارش می‌دهد. فروش زمین شرکت را با همان اختیار نمی‌تواند امضا کند.", "remember": ["پروکورا: گسترده، ثبت، صریح.", "اختیار تجاری: معامله عادی.", "زمین اجازه اضافه لازم دارد."], "summary": ""}}, "en": {"kreislauf": {"title": "Extended economic cycle", "goal": "", "definition": "The extended cycle shows how households, firms, the state, banks and foreign countries exchange goods and money.", "explanation": "Households supply labour and buy goods. Firms pay wages and sell the goods. The state takes taxes and spends on services and orders. Banks take savings and give credit. Foreign countries buy exports and deliver imports. An arrow for goods usually has a return arrow for money. The simple cycle of only household and firm leaves out the state, credit and abroad.", "example": "You save wages at the bank. The bank gives a loan from that to a firm. That is the path through the banks, not a direct trade with the employer.", "remember": ["Five poles: household, firm, state, banks, abroad.", "Goods and money run against each other.", "The simple cycle is incomplete."], "summary": ""}, "marktformen": {"title": "Market forms", "goal": "", "definition": "The market form describes how many suppliers face each other for the same service.", "explanation": "Polypoly: many suppliers, such as many bakeries. Oligopoly: few suppliers. In class that was a few large search engines and, as a local picture, three PC shops in Würzburg. Monopoly: one supplier. The same ideas exist on the demand side, such as a single large buyer. The examples show the count, not the quality of the goods. A monopoly is not automatically illegal; it is first a market form.", "example": "Three shops for PCs in one city are an oligopoly. Many bakers are a polypoly. A single network operator with no alternative would be a monopoly.", "remember": ["Many, few or one.", "Remember the examples from class.", "The demand side can be just as concentrated."], "summary": ""}, "gruendung": {"title": "Founding a firm", "goal": "", "definition": "A founding is the ordered sequence of idea, legal form, plan, registration and start. The script pages for this were scans and are not typed out here.", "explanation": "First you check whether anyone needs the service. Then you choose the legal form, because it decides liability and registration. A simple plan names the offer, the customers, the costs and the start. Then come the trade registration, the register for corporations, the tax office, an account and the necessary contracts. Insurance and contracts belong to the start, not as an afterthought in the second year. This is the usual path, not an invented answer to a worksheet.", "example": "Someone registering a PC service does not need a logo first, but an offer, a legal form and the registration at the office.", "remember": ["Idea and need first.", "Settle the legal form before registration.", "The script is not copied word for word."], "summary": ""}, "rechtsformen": {"title": "Legal forms", "goal": "", "definition": "The legal form sets who is liable, who decides and how the firm is registered.", "explanation": "In a sole proprietorship the owner is liable with business and private assets. A GbR is a partnership of at least two people. An OHG is the commercial form with unlimited liability of the partners. In a KG at least one general partner has unlimited liability, the limited partners only with their contribution. A GmbH is a corporation. Its corporate assets cover its debts, and the share capital is at least 25,000 euros. The UG is a small variant with lower starting capital and a duty to retain profit. The AG is for larger companies with shares and a supervisory board. The pages on legal forms were mostly scans. This is the overview, not a transcript.", "example": "Two trainees repair PCs on the side without articles of association and share the profit. That is more a GbR than a GmbH. Liability stays with the people.", "remember": ["Partnership: people are liable.", "GmbH: the company’s assets are liable.", "Minimum share capital of a GmbH: 25,000 euros."], "summary": ""}, "vollmacht": {"title": "Prokura and commercial authority", "goal": "", "definition": "Both authorise someone to act for a commercial business. Prokura is broad and is entered in the commercial register. Commercial authority is narrower and is not entered.", "explanation": "Prokura must be granted expressly. Outwardly it covers ordinary and many extraordinary transactions. Selling and encumbering land is included only if that was allowed extra. The holder of Prokura may not grant Prokura. An internal limit does not bind outside partners if they do not know about it. Commercial authority under the Commercial Code covers the ordinary business of the firm. Land, taking up credit, conducting lawsuits and bills of exchange need a special authorisation. It can be a general, a type-limited or a single-transaction authority.", "example": "The office lead with commercial authority orders goods for ongoing sales. They may not sign the sale of the company land with that authority.", "remember": ["Prokura: broad, register, express.", "Commercial authority: ordinary business.", "Land needs an extra permission."], "summary": ""}}}, {"id": "k10-englisch", "grade": "10", "subject": {"de": "Englisch", "en": "English", "fa": "انگلیسی"}, "order": ["ausbildung", "abteilungen", "modal", "mails", "nato", "telefon"], "de": {"ausbildung": {"title": "Wörter der Ausbildung", "goal": "", "definition": "Diese Wörter beschreiben das duale System auf Englisch: Betrieb, Schule, Vertrag und die Personen.", "explanation": "Apprenticeship ist die Ausbildung, apprentice oder trainee die lernende Person, trainer die ausbildende Person. Vocational school ist die Berufsschule, company der Betrieb, training contract der Ausbildungsvertrag. Department ist die Abteilung, workshop die Werkstatt, shift die Schicht. Die Wörter gehören in Sätze, nicht in eine liste ohne Bedeutung. Ein Satz nennt Person, Ort und Tätigkeit.", "example": "“The trainee works a morning shift in the workshop and goes to vocational school on Tuesday.”", "remember": ["Person, Ort und Vertrag auseinanderhalten.", "Vocational school ist die Berufsschule.", "Ein Satz ist besser als eine blanke Liste."], "summary": ""}, "abteilungen": {"title": "Abteilungen", "goal": "", "definition": "Englische Abteilungsnamen sagen, wohin eine Mail oder ein Anruf gehört.", "explanation": "Goods-in ist der Wareneingang, warehouse das Lager, shipping der Versand. Purchasing ist der Einkauf, domestic sales der Inlandverkauf, export der Export, order processing die Auftragsbearbeitung. Production ist die Fertigung, production planning die Fertigungsplanung. Accounting ist die Buchhaltung, controlling das Controlling, administration and finance Verwaltung und Finanzen. Human resources ist die Personalabteilung, marketing das Marketing, legal die Rechtsabteilung, research and development Forschung und Entwicklung. Du musst nicht alle in einem Satz nennen. Du musst wissen, welche Stelle den Vorgang hat.", "example": "Eine beschädigte Lieferung geht an goods-in, nicht an marketing. Eine Bewerbung geht an human resources.", "remember": ["Zuerst der Vorgang, dann die Abteilung.", "Goods-in ist nicht dasselbe wie shipping.", "Legal ist die Rechtsabteilung."], "summary": ""}, "modal": {"title": "Modalverben", "goal": "", "definition": "Ein Modalverb sagt, ob etwas möglich, erlaubt, nötig oder ein Rat ist. Es steht vor dem Verb in der Grundform.", "explanation": "Can ist Können oder eine lockere Erlaubnis. May ist eine förmliche Erlaubnis oder eine Möglichkeit. Must ist ein Muss aus Sicht des Sprechers. Have to ist ein Muss von außen, etwa eine Vorschrift. Should ist ein Rat, nicht ein Zwang. Will ist Zukunft oder Bereitschaft. Die Verneinung ändert die Bedeutung: must not ist verboten, do not have to ist nicht nötig. Hinter dem Modalverb steht das Vollverb ohne to, außer bei have to.", "example": "“You must wear safety shoes in the workshop.” Das ist ein Verbot, sie wegzulassen. “You don’t have to stay after 16:00.” Das ist keine Pflicht, kein Verbot.", "remember": ["Must not heißt verboten.", "Don’t have to heißt nicht nötig.", "Should ist ein Rat."], "summary": ""}, "mails": {"title": "E-Mails", "goal": "", "definition": "Eine förmliche Mail nennt Anrede, Anliegen und Gruß. Eine lockere Mail ist kürzer und nur für Menschen, die du duzt.", "explanation": "Förmlich: Dear Ms Keller, I am writing to ask …, Kind regards, und der volle Name. Das Subject sagt den Vorgang, nicht “Hello” oder “Question”. Ein Anliegen pro Mail. Lockere Mail an eine bekannte Person: Hi Sam, kurzer Satz, Thanks oder Best. Du mischst nicht Dear Sir mit Cheers. Die Arbeitsblätter zu Hardware waren überwiegend Bilder. Die sicheren Gerätewörter dazu sind monitor, keyboard, printer, motherboard, memory, port and cable. Sie ersetzen keine abgetippte Vokabelliste, die nicht lesbar war.", "example": "Subject: Damaged delivery 14 March. Dear Mr Braun, the monitor arrived with a broken screen. Could you send a replacement? Kind regards, Lea Hoffmann.", "remember": ["Subject nennt den Vorgang.", "Dear und Kind regards bleiben förmlich.", "Ein Anliegen, nicht fünf."], "summary": ""}, "nato": {"title": "Buchstabieren", "goal": "", "definition": "Das NATO-Alphabet macht Buchstaben am Telefon eindeutig. Jeder Buchstabe hat ein festes Wort.", "explanation": "A Alfa, B Bravo, C Charlie, D Delta, E Echo, F Foxtrot, G Golf, H Hotel, I India, J Juliett, K Kilo, L Lima, M Mike, N November, O Oscar, P Papa, Q Quebec, R Romeo, S Sierra, T Tango, U Uniform, V Victor, W Whiskey, X X-ray, Y Yankee, Z Zulu. Alfa wird ohne ph geschrieben, Juliett mit zwei t. Du buchstabierst Namen, Nummern und Kennungen, nicht ganze Sätze. Zahlen sprichst du einzeln.", "example": "Der Name Keller ist Kilo, Echo, Lima, Lima, Echo, Romeo.", "remember": ["Festes Wort je Buchstabe.", "Juliett mit zwei t, Alfa ohne ph.", "Nur Kennungen, nicht ganze Sätze."], "summary": ""}, "telefon": {"title": "Telefonieren", "goal": "", "definition": "Am Telefon nennst du Firma und Namen, leitest weiter oder nimmst eine Nachricht auf und verschiebst Termine klar.", "explanation": "Annehmen: “Good morning, Keller IT, Lea Hoffmann speaking. How can I help you?” Weiterleiten: “I’ll put you through to order processing.” Wenn niemand da ist: “I’m afraid she is not available. May I take a message?” Termin ändern: “Could we move the meeting to Thursday at 10?” und der Grund in einem Satz. Du legst nicht auf, ohne den neuen Zeitpunkt zu wiederholen. Im Klassenplan standen Arbeiten am 5.12. und am 6.03. Ob die Termine noch gelten, sagt die Lehrkraft.", "example": "Ein Anrufer will die Buchhaltung. Du sagst den Satz zum Weiterleiten und den Namen der Abteilung, nicht nur “wait”.", "remember": ["Firma und eigener Name zuerst.", "Nicht da: Nachricht anbieten.", "Neuen Termin wiederholen."], "summary": ""}}, "fa": {"ausbildung": {"title": "واژه‌های کارآموزی", "goal": "", "definition": "این واژه‌ها نظام دوگانه را به انگلیسی توصیف می‌کنند: شرکت، مدرسه، قرارداد و اشخاص.", "explanation": "Apprenticeship آموزش است، apprentice یا trainee شخص در حال یادگیری، trainer شخص آموزش‌دهنده. Vocational school هنرستان شغلی است، company شرکت، training contract قرارداد آموزش. Department بخش است، workshop کارگاه، shift شیفت. واژه‌ها در جمله‌اند، نه در فهرستی بدون معنی. یک جمله شخص، جا و کار را نام می‌برد.", "example": "“The trainee works a morning shift in the workshop and goes to vocational school on Tuesday.”", "remember": ["شخص، جا و قرارداد را جدا نگه دار.", "Vocational school هنرستان شغلی است.", "یک جمله بهتر از فهرست خالی است."], "summary": ""}, "abteilungen": {"title": "بخش‌ها", "goal": "", "definition": "نام انگلیسی بخش‌ها می‌گوید ایمیل یا تماس کجا می‌رود.", "explanation": "Goods-in ورود کالا است، warehouse انبار، shipping ارسال. Purchasing خرید است، domestic sales فروش داخلی، export صادرات، order processing رسیدگی به سفارش. Production تولید است، production planning برنامه‌ریزی تولید. Accounting حسابداری است، controlling کنترل اعداد، administration and finance اداره و مالی. Human resources نیروی انسانی است، marketing بازاریابی، legal حقوقی، research and development تحقیق و توسعه. لازم نیست همه را در یک جمله نام ببری. باید بدانی کدام واحد کار را دارد.", "example": "یک تحویل آسیب‌دیده به goods-in می‌رود، نه به marketing. یک درخواست کار به human resources می‌رود.", "remember": ["اول کار، بعد بخش.", "Goods-in همان shipping نیست.", "Legal بخش حقوقی است."], "summary": ""}, "modal": {"title": "فعل‌های وجهی", "goal": "", "definition": "فعل وجهی می‌گوید چیزی ممکن، مجاز، لازم یا توصیه است. پیش از فعل در شکل پایه می‌آید.", "explanation": "Can توانایی یا اجازه غیررسمی است. May اجازه رسمی یا امکان است. Must بایستن از دید گوینده است. Have to بایستن از بیرون است، مثل یک مقررات. Should توصیه است، نه اجبار. Will آینده یا آمادگی است. نفی معنی را عوض می‌کند: must not ممنوع است، do not have to لازم نیست. بعد از فعل وجهی فعل اصلی بدون to می‌آید، جز have to.", "example": "“You must wear safety shoes in the workshop.” این ممنوعیت درآوردن آن‌هاست. “You don’t have to stay after 16:00.” این وظیفه نیست، ممنوعیت نیست.", "remember": ["Must not یعنی ممنوع.", "Don’t have to یعنی لازم نیست.", "Should توصیه است."], "summary": ""}, "mails": {"title": "ایمیل", "goal": "", "definition": "ایمیل رسمی خطاب، درخواست و پایان دارد. ایمیل خودمانی کوتاه‌تر است و فقط برای کسی که خوب می‌شناسی.", "explanation": "رسمی: Dear Ms Keller، I am writing to ask …، Kind regards، و نام کامل. موضوع کار را می‌گوید، نه Hello یا Question. یک درخواست در هر ایمیل. ایمیل خودمانی به آشنا: Hi Sam، یک جمله کوتاه، Thanks یا Best. Dear Sir را با Cheers قاطی نمی‌کنی. برگه‌های سخت‌افزار بیشتر تصویر بودند. واژه‌های مطمئن دستگاه: monitor، keyboard، printer، motherboard، memory، port و cable. جای فهرست واژه‌ای که خوانا نبود را نمی‌گیرند.", "example": "Subject: Damaged delivery 14 March. Dear Mr Braun, the monitor arrived with a broken screen. Could you send a replacement? Kind regards, Lea Hoffmann.", "remember": ["موضوع کار را نام می‌برد.", "Dear و Kind regards رسمی می‌مانند.", "یک درخواست، نه پنج."], "summary": ""}, "nato": {"title": "هجی", "goal": "", "definition": "الفبای ناتو حرف را در تلفن روشن می‌کند. هر حرف یک واژه ثابت دارد.", "explanation": "A Alfa، B Bravo، C Charlie، D Delta، E Echo، F Foxtrot، G Golf، H Hotel، I India، J Juliett، K Kilo، L Lima، M Mike، N November، O Oscar، P Papa، Q Quebec، R Romeo، S Sierra، T Tango، U Uniform، V Victor، W Whiskey، X X-ray، Y Yankee، Z Zulu. Alfa بدون ph نوشته می‌شود، Juliett با دو t. نام، شماره و شناسه را هجی می‌کنی، نه جمله کامل. رقم را تک‌تک می‌گویی.", "example": "نام Keller می‌شود Kilo, Echo, Lima, Lima, Echo, Romeo.", "remember": ["یک واژه ثابت برای هر حرف.", "Juliett با دو t، Alfa بدون ph.", "فقط شناسه، نه جمله کامل."], "summary": ""}, "telefon": {"title": "تلفن", "goal": "", "definition": "در تلفن شرکت و نام را می‌گویی، وصل می‌کنی یا پیام می‌گیری و قرار را روشن جابه‌جا می‌کنی.", "explanation": "جواب: “Good morning, Keller IT, Lea Hoffmann speaking. How can I help you?” هدایت: “I’ll put you through to order processing.” اگر کسی نیست: “I’m afraid she is not available. May I take a message?” عوض کردن زمان: “Could we move the meeting to Thursday at 10?” و دلیل در یک جمله. بدون تکرار زمان جدید قطع نمی‌کنی. در برنامه کلاس کارهایی در ۵ دسامبر و ۶ مارس آمده بود. فقط معلم می‌گوید آن تاریخ‌ها هنوز معتبرند یا نه.", "example": "تماس‌گیرنده حسابداری را می‌خواهد. جمله وصل کردن و نام بخش را می‌گویی، نه فقط wait.", "remember": ["اول شرکت و نام خودت.", "نیست: پیشنهاد گرفتن پیام.", "زمان جدید را تکرار کن."], "summary": ""}}, "en": {"ausbildung": {"title": "Apprenticeship words", "goal": "", "definition": "These words describe the dual system in English: company, school, contract and the people.", "explanation": "Apprenticeship is the training, apprentice or trainee the person learning, trainer the person training. Vocational school is the Berufsschule, company the firm, training contract the training agreement. Department is the Abteilung, workshop the Werkstatt, shift the Schicht. The words belong in sentences, not in a list without meaning. A sentence names person, place and task.", "example": "“The trainee works a morning shift in the workshop and goes to vocational school on Tuesday.”", "remember": ["Keep person, place and contract apart.", "Vocational school is the Berufsschule.", "A sentence is better than a bare list."], "summary": ""}, "abteilungen": {"title": "Departments", "goal": "", "definition": "English department names say where a mail or a call belongs.", "explanation": "Goods-in is receiving, warehouse is the store, shipping is dispatch. Purchasing is buying, domestic sales is sales inside the country, export is export, order processing handles orders. Production is manufacturing, production planning plans it. Accounting is the books, controlling checks figures, administration and finance is admin and money. Human resources is personnel, marketing is marketing, legal is the legal department, research and development is R&D. You do not have to name them all in one sentence. You must know which office owns the process.", "example": "A damaged delivery goes to goods-in, not to marketing. An application goes to human resources.", "remember": ["First the process, then the department.", "Goods-in is not the same as shipping.", "Legal is the legal department."], "summary": ""}, "modal": {"title": "Modal verbs", "goal": "", "definition": "A modal verb says whether something is possible, allowed, necessary or advice. It stands before the verb in the base form.", "explanation": "Can is ability or a casual permission. May is a formal permission or a possibility. Must is a necessity from the speaker’s view. Have to is a necessity from outside, such as a rule. Should is advice, not force. Will is future or willingness. Negation changes the meaning: must not is forbidden, do not have to is not necessary. After the modal the main verb has no to, except with have to.", "example": "“You must wear safety shoes in the workshop.” That is a ban on leaving them off. “You don’t have to stay after 16:00.” That is no duty, not a ban.", "remember": ["Must not means forbidden.", "Don’t have to means not necessary.", "Should is advice."], "summary": ""}, "mails": {"title": "Emails", "goal": "", "definition": "A formal mail has a greeting, a request and a close. A casual mail is shorter and only for people you know well.", "explanation": "Formal: Dear Ms Keller, I am writing to ask …, Kind regards, and the full name. The subject states the matter, not “Hello” or “Question”. One request per mail. A casual mail to someone you know: Hi Sam, a short sentence, Thanks or Best. You do not mix Dear Sir with Cheers. The hardware worksheets were mostly pictures. The safe device words for them are monitor, keyboard, printer, motherboard, memory, port and cable. They do not replace a typed vocabulary list that was not readable.", "example": "Subject: Damaged delivery 14 March. Dear Mr Braun, the monitor arrived with a broken screen. Could you send a replacement? Kind regards, Lea Hoffmann.", "remember": ["The subject names the matter.", "Dear and Kind regards stay formal.", "One request, not five."], "summary": ""}, "nato": {"title": "Spelling", "goal": "", "definition": "The NATO alphabet makes letters clear on the phone. Each letter has a fixed word.", "explanation": "A Alfa, B Bravo, C Charlie, D Delta, E Echo, F Foxtrot, G Golf, H Hotel, I India, J Juliett, K Kilo, L Lima, M Mike, N November, O Oscar, P Papa, Q Quebec, R Romeo, S Sierra, T Tango, U Uniform, V Victor, W Whiskey, X X-ray, Y Yankee, Z Zulu. Alfa is written without ph, Juliett with two t’s. You spell names, numbers and identifiers, not whole sentences. You say digits one by one.", "example": "The name Keller is Kilo, Echo, Lima, Lima, Echo, Romeo.", "remember": ["A fixed word per letter.", "Juliett with two t’s, Alfa without ph.", "Only identifiers, not whole sentences."], "summary": ""}, "telefon": {"title": "Telephoning", "goal": "", "definition": "On the phone you give the company and your name, put someone through or take a message, and move appointments clearly.", "explanation": "Answering: “Good morning, Keller IT, Lea Hoffmann speaking. How can I help you?” Redirecting: “I’ll put you through to order processing.” If nobody is there: “I’m afraid she is not available. May I take a message?” Changing a time: “Could we move the meeting to Thursday at 10?” and the reason in one sentence. You do not hang up without repeating the new time. The class plan named tests on 5 December and 6 March. Only the teacher can say whether those dates still apply.", "example": "A caller wants accounting. You say the sentence for putting them through and the department name, not only “wait”.", "remember": ["Company and your own name first.", "Not there: offer to take a message.", "Repeat the new time."], "summary": ""}}}, {"id": "k10-fuit", "grade": "10", "subject": {"de": "FU-IT", "en": "IT fundamentals", "fa": "مبانی IT"}, "order": ["geraete", "netzarten", "osi", "kopplung", "verkabelung"], "de": {"geraete": {"title": "Geräte und Server", "goal": "", "definition": "Ein Switch verbindet Geräte im lokalen Netz. Ein Access Point hängt WLAN-Geräte an dieses Netz. Ein Router verbindet verschiedene IP-Netze.", "explanation": "Server sind Rechner mit einer festen Aufgabe. Ein Verzeichnisdienst hält Konten und Rechte. DHCP verteilt Adressen. DNS übersetzt Namen in Adressen. Ein SQL-Server speichert abgefragte Daten. Ein Mailserver nimmt und stellt Post zu. Ein Webserver liefert Seiten. Diese Rollen können auf getrennten Maschinen liegen oder zusammen, sie bleiben aber verschiedene Aufgaben.", "example": "Der Access Point im Klassenraum gibt WLAN. Der Router am Standort verbindet dieses LAN mit einem anderen Netz. Der DHCP-Server verteilt die Adressen, der Access Point tut das nicht von allein.", "remember": ["Switch: ein Netz. Router: mehrere Netze.", "Access Point ist der Übergang ins WLAN.", "Jede Serverrolle hat genau eine Aufgabe."], "summary": ""}, "netzarten": {"title": "Reichweite der Netze", "goal": "", "definition": "Der Name eines Netzes sagt, welchen Raum es überspannt: Körper, Person, Raum, Gelände, Stadt, weit oder weltweit.", "explanation": "BAN liegt am Körper, etwa bei Sensoren. PAN gehört zu einer Person, etwa Headset und Telefon. LAN ist lokal, ein Raum oder ein Gebäude. CAN verbindet das Gelände mehrerer Gebäude. MAN umfasst eine Stadt. WAN reicht über weite Strecken. GAN ist weltweit. Die Grenzen sind Größen, keine harten Meterzahlen.", "example": "Das Schulgebäude ist ein LAN. Mehrere Häuser auf dem Schulgelände bilden ein CAN. Die Verbindung zur nächsten Stadt ist kein LAN mehr.", "remember": ["PAN ist persönlich, LAN ist örtlich.", "CAN ist das Gelände, MAN die Stadt.", "WAN und GAN gehen über die Stadt hinaus."], "summary": ""}, "osi": {"title": "OSI als Landkarte", "goal": "", "definition": "Das OSI-Modell teilt die Kommunikation in sieben Schichten, damit jede Schicht nur ihre eigene Aufgabe hat.", "explanation": "Von oben nach unten: Anwendung, Darstellung, Sitzung, Transport, Vermittlung, Sicherung, Bitübertragung. Die Anwendung spricht mit dem Programm. Die Darstellung kümmert sich um die Form der Daten. Die Sitzung hält den Dialog. Der Transport bringt die Daten zum richtigen Dienst auf dem Zielrechner. Die Vermittlung wählt den Weg über IP-Netze. Die Sicherung bringt den Rahmen zum nächsten Gerät. Die Bitübertragung schickt Signale über das Medium. Eine Merkhilfe ersetzt die Namen nicht.", "example": "Eine IP-Adresse gehört zur Vermittlung. Die MAC-Adresse gehört zur Sicherung. Das Kabel gehört zur Bitübertragung.", "remember": ["Sieben Schichten, jede mit einer Aufgabe.", "IP sucht den Weg, MAC den nächsten Hop.", "Das Modell ist eine Landkarte, kein Gerät."], "summary": ""}, "kopplung": {"title": "Repeater, Hub, Bridge, Switch", "goal": "", "definition": "Ein Repeater frischt das Signal auf. Ein Hub ist ein Repeater mit mehreren Ports. Eine Bridge trennt anhand der MAC-Adresse. Ein Switch ist eine Bridge mit vielen Ports.", "explanation": "Hub und Repeater verstehen keine Adressen. Jedes Signal geht an alle angeschlossenen Segmente. Das teilt die Last nicht. Bridge und Switch lernen, hinter welchem Port eine MAC-Adresse liegt, und schicken den Rahmen nur dorthin. Unbekanntes oder ein Broadcast geht weiter an alle. Der Router kommt erst dazu, wenn ein anderes IP-Netz erreicht werden soll. Er ist keine schnellere Bridge.", "example": "Ein Hub im Klassenraum schickt jeden Rahmen an jeden Port. Ein Switch schickt den Rahmen an den Port des Ziels.", "remember": ["Hub: alle hören mit.", "Switch: nur der Zielport, außer bei Broadcast.", "Router ist die Grenze zum anderen IP-Netz."], "summary": ""}, "verkabelung": {"title": "Kupfer, Glas und Struktur", "goal": "", "definition": "Kupferkabel tragen elektrische Signale auf der Etage. Glasfasern tragen Licht über längere Strecken. Die Verkabelung eines Geländes ist in drei Ebenen gegliedert.", "explanation": "Primär verkabelt das Gelände, also Gebäude mit Gebäude. Sekundär verkabelt das Gebäude, also Etage mit Etage. Tertiär ist die Ebene auf der Etage, vom Verteiler zur Dose. So ist die Struktur nach EN 50173 gemeint. In den Unterlagen waren die Spalten unübersichtlich, deshalb steht hier die übliche Ordnung und nicht eine abgetippte Tabelle. Monomode führt einen Lichtweg und wurde im Unterricht mit etwa 30 km genannt. Multimode führt mehrere Lichtwege und wurde mit etwa 1,5 km genannt. Die echte Reichweite hängt von Faser, Wellenlänge und Gerät ab.", "example": "Vom Etagenverteiler zur Dose im Raum liegt Tertiär, oft Kupfer. Zwischen zwei Gebäuden auf dem Gelände liegt Primär, oft Glas.", "remember": ["Primär Gelände, sekundär Gebäude, tertiär Etage.", "Monomode weiter, Multimode kürzer.", "Die Kilometer aus dem Unterricht sind Richtwerte."], "summary": ""}}, "fa": {"geraete": {"title": "دستگاه و سرور", "goal": "", "definition": "سوئیچ دستگاه‌ها را در شبکه محلی وصل می‌کند. نقطه دسترسی دستگاه‌های WLAN را به همان شبکه می‌آورد. مسیریاب شبکه‌های IP متفاوت را وصل می‌کند.", "explanation": "سرور رایانه‌ای با یک کار ثابت است. خدمت فهرست حساب و حق را نگه می‌دارد. DHCP نشانی می‌دهد. DNS نام را به نشانی تبدیل می‌کند. سرور SQL داده قابل پرسش را ذخیره می‌کند. سرور نامه پست را می‌گیرد و می‌رساند. سرور وب صفحه می‌دهد. این نقش‌ها می‌توانند روی دستگاه جدا یا با هم باشند، ولی کارشان فرق می‌کند.", "example": "نقطه دسترسی در کلاس WLAN می‌دهد. مسیریاب محل این LAN را به شبکه دیگری وصل می‌کند. سرور DHCP نشانی را پخش می‌کند. نقطه دسترسی خودش این کار را نمی‌کند.", "remember": ["سوئیچ: یک شبکه. مسیریاب: چند شبکه.", "نقطه دسترسی گذر به WLAN است.", "هر نقش سرور دقیقاً یک کار دارد."], "summary": ""}, "netzarten": {"title": "برد شبکه", "goal": "", "definition": "نام شبکه می‌گوید کدام فضا را می‌پوشاند: بدن، شخص، اتاق، محوطه، شهر، فاصله دور یا جهان.", "explanation": "BAN روی بدن است، مثلاً با حسگر. PAN مال یک شخص است، مثل هدست و تلفن. LAN محلی است، یک اتاق یا ساختمان. CAN محوطه چند ساختمان را وصل می‌کند. MAN یک شهر را می‌پوشاند. WAN فاصله دور را می‌رسد. GAN جهانی است. مرزها اندازه هستند، نه متر قطعی.", "example": "ساختمان مدرسه یک LAN است. چند ساختمان در محوطه مدرسه یک CAN می‌سازند. پیوند به شهر بعدی دیگر LAN نیست.", "remember": ["PAN شخصی است، LAN محلی.", "CAN محوطه است، MAN شهر.", "WAN و GAN از شهر فراتر می‌روند."], "summary": ""}, "osi": {"title": "OSI به‌عنوان نقشه", "goal": "", "definition": "مدل OSI ارتباط را به هفت لایه تقسیم می‌کند تا هر لایه فقط کار خودش را داشته باشد.", "explanation": "از بالا به پایین: کاربرد، نمایش، نشست، انتقال، شبکه، پیوند داده، فیزیکی. کاربرد با برنامه حرف می‌زند. نمایش به شکل داده می‌رسد. نشست گفتگو را نگه می‌دارد. انتقال داده را به خدمت درست روی رایانه مقصد می‌رساند. لایه شبکه راه را میان شبکه‌های IP انتخاب می‌کند. پیوند داده قاب را به دستگاه بعدی می‌برد. لایه فیزیکی سیگنال را روی رسانه می‌فرستد. کمک حافظه جای نام‌ها را نمی‌گیرد.", "example": "نشانی IP مال لایه شبکه است. نشانی MAC مال پیوند داده است. کابل مال لایه فیزیکی است.", "remember": ["هفت لایه، هرکدام یک کار.", "IP راه را پیدا می‌کند، MAC پرش بعدی را.", "مدل نقشه است، نه دستگاه."], "summary": ""}, "kopplung": {"title": "تکرارگر، هاب، پل، سوئیچ", "goal": "", "definition": "تکرارگر سیگنال را تازه می‌کند. هاب تکرارگری با چند درگاه است. پل ترافیک را با نشانی MAC جدا می‌کند. سوئیچ پلی با درگاه‌های زیاد است.", "explanation": "هاب و تکرارگر نشانی نمی‌فهمند. هر سیگنال به همه بخش‌های وصل می‌رود. این بار را تقسیم نمی‌کند. پل و سوئیچ یاد می‌گیرند نشانی MAC پشت کدام درگاه است و قاب را فقط آنجا می‌فرستند. قاب ناشناس یا پخش هنوز به همه می‌رود. مسیریاب وقتی اضافه می‌شود که شبکه IP دیگری باید برسد. او پل سریع‌تر نیست.", "example": "یک هاب در کلاس هر قاب را به هر درگاه می‌فرستد. یک سوئیچ قاب را به درگاه مقصد می‌فرستد.", "remember": ["هاب: همه می‌شنوند.", "سوئیچ: فقط درگاه مقصد، جز برای پخش.", "مسیریاب مرز شبکه IP دیگر است."], "summary": ""}, "verkabelung": {"title": "مس، فیبر و ساختار", "goal": "", "definition": "کابل مس سیگنال الکتریکی را در طبقه می‌برد. فیبر نور را در فاصله بلندتر می‌برد. کابل‌کشی یک محوطه به سه سطح تقسیم می‌شود.", "explanation": "کابل اولیه محوطه را می‌پوشاند، ساختمان به ساختمان. کابل ثانویه ساختمان را می‌پوشاند، طبقه به طبقه. سطح سوم روی طبقه است، از توزیع‌کننده تا پریز. این ساختاری است که EN 50173 منظور دارد. در فایل کلاس ستون‌ها درهم بودند، پس اینجا ترتیب معمول است نه یک جدول رونویسی‌شده. تک‌حالته یک راه نور دارد و در کلاس حدود ۳۰ کیلومتر گفته شد. چندحالته چند راه نور دارد و حدود ۱٫۵ کیلومتر گفته شد. برد واقعی به فیبر، طول موج و دستگاه بستگی دارد.", "example": "از توزیع‌کننده طبقه تا پریز اتاق سطح سوم است، اغلب مس. بین دو ساختمان در محوطه سطح اول است، اغلب فیبر.", "remember": ["اول محوطه، دوم ساختمان، سوم طبقه.", "تک‌حالته دورتر، چندحالته کوتاه‌تر.", "کیلومترهای کلاس حدودی‌اند."], "summary": ""}}, "en": {"geraete": {"title": "Devices and servers", "goal": "", "definition": "A switch connects devices in the local network. An access point attaches WLAN devices to that network. A router connects different IP networks.", "explanation": "Servers are computers with a fixed job. A directory service holds accounts and rights. DHCP hands out addresses. DNS turns names into addresses. An SQL server stores data that is queried. A mail server receives and delivers mail. A web server serves pages. These roles can sit on separate machines or together, but they stay different jobs.", "example": "The access point in the classroom provides WLAN. The router at the site connects this LAN to another network. The DHCP server hands out the addresses; the access point does not do that by itself.", "remember": ["Switch: one network. Router: several networks.", "The access point is the step into WLAN.", "Each server role has exactly one job."], "summary": ""}, "netzarten": {"title": "How far a network reaches", "goal": "", "definition": "The name of a network says which space it covers: a body, a person, a room, a campus, a city, a long distance or the world.", "explanation": "A BAN sits on the body, for example with sensors. A PAN belongs to one person, such as a headset and a phone. A LAN is local, a room or a building. A CAN joins a campus of several buildings. A MAN covers a city. A WAN reaches over long distances. A GAN is worldwide. The borders are sizes, not hard distances in metres.", "example": "The school building is a LAN. Several houses on the school grounds form a CAN. The link to the next city is no longer a LAN.", "remember": ["PAN is personal, LAN is local.", "CAN is the campus, MAN the city.", "WAN and GAN go beyond the city."], "summary": ""}, "osi": {"title": "OSI as a map", "goal": "", "definition": "The OSI model splits communication into seven layers so that each layer has only its own job.", "explanation": "From top to bottom: application, presentation, session, transport, network, data link, physical. The application talks to the program. Presentation deals with the form of the data. Session keeps the dialogue. Transport delivers the data to the right service on the destination computer. The network layer chooses the path across IP networks. Data link carries the frame to the next device. The physical layer sends signals over the medium. A memory aid does not replace the names.", "example": "An IP address belongs to the network layer. The MAC address belongs to data link. The cable belongs to the physical layer.", "remember": ["Seven layers, each with one job.", "IP finds the path, MAC the next hop.", "The model is a map, not a device."], "summary": ""}, "kopplung": {"title": "Repeater, hub, bridge, switch", "goal": "", "definition": "A repeater refreshes the signal. A hub is a repeater with several ports. A bridge separates traffic by MAC address. A switch is a bridge with many ports.", "explanation": "Hubs and repeaters do not understand addresses. Every signal goes to all connected segments. That does not share the load. Bridges and switches learn which port a MAC address is behind and send the frame only there. Unknown frames or a broadcast still go to all. The router is added only when another IP network must be reached. It is not a faster bridge.", "example": "A hub in the classroom sends every frame to every port. A switch sends the frame to the destination’s port.", "remember": ["Hub: everyone hears it.", "Switch: only the destination port, except for a broadcast.", "The router is the border to the other IP network."], "summary": ""}, "verkabelung": {"title": "Copper, fibre and structure", "goal": "", "definition": "Copper cable carries electrical signals on the floor. Fibre carries light over longer distances. The cabling of a site is split into three levels.", "explanation": "Primary cabling covers the site, building to building. Secondary cabling covers the building, floor to floor. Tertiary is the floor level, from the distributor to the outlet. That is the structure meant by EN 50173. In the class files the columns were muddled, so this is the usual order and not a typed-out table. Single-mode carries one light path and was named in class at about 30 km. Multimode carries several light paths and was named at about 1.5 km. The real reach depends on the fibre, the wavelength and the device.", "example": "From the floor distributor to the outlet in the room is tertiary, often copper. Between two buildings on the site is primary, often fibre.", "remember": ["Primary site, secondary building, tertiary floor.", "Single-mode farther, multimode shorter.", "The kilometres from class are guides."], "summary": ""}}}, {"id": "k10-ittechnik", "grade": "10", "subject": {"de": "IT-Technik", "en": "IT hardware", "fa": "فناوری IT"}, "order": ["entwicklung", "eva", "mainboard", "chipsatz", "schnittstellen"], "de": {"entwicklung": {"title": "Vom Relais zum Mikroprozessor", "goal": "", "definition": "Rechner wurden kleiner und dichter: von elektromechanischen Teilen über Röhren und Transistoren zu integrierten Schaltungen und zum Mikroprozessor.", "explanation": "Jede Stufe packt mehr Schalter auf weniger Raum und braucht weniger Energie. Der Mikroprozessor legt die Rechenwerke auf einen Chip. Daraus werden PCs in verschiedenen Gehäusen. Das Arbeitsblatt zur Geschichte war nicht als Text lesbar. Diese Folge ist der übliche Überblick, keine Abschrift einer Zeittafel und keine Jahreszahlen aus der Klasse.", "example": "Ein Tischrechner von früher füllt einen Raum. Dieselbe Idee steckt heute in einem Chip auf dem Mainboard.", "remember": ["Dichter, kleiner, weniger Energie.", "Der Mikroprozessor ist die Recheneinheit auf einem Chip.", "Keine erfundenen Jahreszahlen."], "summary": ""}, "eva": {"title": "EVA und Bauformen", "goal": "", "definition": "Ein Rechner nimmt Daten auf, verarbeitet sie und gibt ein Ergebnis aus. Der Speicher hält Daten zwischen diesen Schritten. Die Bauform ist nur das Gehäuse.", "explanation": "Eingabe ist Tastatur, Maus, Sensor oder Netz. Verarbeitung ist der Prozessor. Ausgabe ist Monitor, Drucker oder ein Signal. Ohne Speicher müsste jede Eingabe sofort wieder verschwinden. Tower, Desktop, Laptop, All-in-One und ein Server im Rack sind Bauformen. Sie ändern nicht das EVA-Prinzip. Ein Laptop ist kein anderer Rechner, nur anders verpackt.", "example": "Der Scanner ist Eingabe, die Bearbeitung des Scans ist Verarbeitung, die Datei auf dem Bildschirm ist Ausgabe, die Festplatte ist Speicher.", "remember": ["Eingabe, Verarbeitung, Ausgabe.", "Speicher hält das Zwischenergebnis.", "Die Bauform ändert das Prinzip nicht."], "summary": ""}, "mainboard": {"title": "Mainboard", "goal": "", "definition": "Das Mainboard verbindet Prozessor, Speicher, Steckplätze, Strom und Anschlüsse. Es rechnet nicht selbst.", "explanation": "Alle Teile brauchen einen gemeinsamen Träger und gemeinsame Leitungen. Der Sockel nimmt den Prozessor auf. Die Steckplätze nehmen Speicher und Karten auf. Anschlüsse führen nach außen, etwa USB. Das Netzteil liefert Strom auf das Board, das Board ersetzt das Netzteil nicht. Wenn eine Leitung auf dem Board defekt ist, hilft ein schnellerer Prozessor nicht.", "example": "Grafikkarte, SSD und USB-Buchse sitzen am oder auf dem Mainboard. Ohne Board hätten sie keine gemeinsame Verbindung.", "remember": ["Das Board verbindet, es rechnet nicht.", "Sockel, Slots und Buchsen gehören dazu.", "Strom kommt vom Netzteil."], "summary": ""}, "chipsatz": {"title": "Chipsatz", "goal": "", "definition": "Der Chipsatz steuert, wie der Prozessor mit Speicher, Karten und Anschlüssen spricht.", "explanation": "Früher teilte man das oft in Northbridge und Southbridge. Der eine lag näher am Speicher und an der Grafik, der andere an langsameren Anschlüssen. Heute steckt viel davon im Prozessor selbst. Der verbleibende Chipsatz auf dem Board bindet den Rest an, etwa weitere PCIe-Lanes und USB. Du musst den Chipsatz nicht sehen, um zu verstehen: ohne diese Vermittlung erreichen Daten den Prozessor nicht geordnet.", "example": "Eine USB-Buchse am Gehäuse führt über das Board zum Chipsatz und von dort zum Prozessor. Sie steckt nicht direkt im Rechenwerk.", "remember": ["Er vermittelt, er ersetzt den Prozessor nicht.", "Alt: Northbridge und Southbridge.", "Heute liegt viel davon in der CPU."], "summary": ""}, "schnittstellen": {"title": "PCIe und USB", "goal": "", "definition": "PCIe verbindet schnelle Karten punktgenau mit Lanes. USB verbindet Geräte am Rand des Rechners. Die Form der Buchse sagt nicht automatisch die Geschwindigkeit.", "explanation": "PCIe ist eine serielle Punkt-zu-Punkt-Verbindung. Eine Karte bekommt eine oder mehrere Lanes, etwa x1, x4 oder x16. Eine Grafikkarte braucht viele Lanes, eine einfache Schnittstellenkarte weniger. Das alte parallele PCI ist nicht dasselbe. USB ist für Tastatur, Speicherstick, Drucker und viele andere Geräte gedacht. Versionen unterscheiden sich in der Geschwindigkeit. USB versorgt kleine Geräte, es ersetzt nicht das Netzteil des ganzen PCs. Weiterer Stoff nach diesem Thema war auf den Seiten nicht lesbar und wird hier nicht erfunden.", "example": "Eine Grafikkarte sitzt in PCIe x16. Ein USB-Stick steckt außen in USB. Beides sind Anschlüsse, aber nicht dieselbe Busart.", "remember": ["PCIe: Lanes, innen, für Karten.", "USB: Geräte am Rand.", "Buchsenform ist nicht die Geschwindigkeit."], "summary": ""}}, "fa": {"entwicklung": {"title": "از رله تا ریزپردازنده", "goal": "", "definition": "رایانه کوچک‌تر و فشرده‌تر شد: از قطعه الکترومکانیکی، از لامپ و ترانزیستور تا مدار مجتمع و ریزپردازنده.", "explanation": "هر مرحله کلید بیشتری را در فضای کمتر جا می‌دهد و انرژی کمتری می‌خواهد. ریزپردازنده واحدهای حساب را روی یک تراشه می‌گذارد. از آن رایانه در جعبه‌های مختلف می‌آید. برگه تاریخ به‌صورت متن خوانا نبود. این ترتیب مرور معمول است، نه رونوشت یک جدول زمانی و نه سال‌های کلاس.", "example": "یک رایانه قدیمی یک اتاق را پر می‌کند. همان ایده امروز در یک تراشه روی برد اصلی است.", "remember": ["فشرده‌تر، کوچک‌تر، انرژی کمتر.", "ریزپردازنده واحد حساب روی یک تراشه است.", "سال ساختگی نیست."], "summary": ""}, "eva": {"title": "ورودی، پردازش، خروجی و شکل", "goal": "", "definition": "رایانه داده را می‌گیرد، پردازش می‌کند و نتیجه را بیرون می‌دهد. حافظه داده را بین این گام‌ها نگه می‌دارد. شکل فقط جعبه است.", "explanation": "ورودی صفحه‌کلید، موش، حسگر یا شبکه است. پردازش پردازنده است. خروجی نمایشگر، چاپگر یا یک سیگنال است. بدون حافظه هر ورودی باید فوراً ناپدید شود. برج، رومیزی، لپ‌تاپ، همه‌دریک و سرور در رک شکل جعبه‌اند. اصل را عوض نمی‌کنند. لپ‌تاپ رایانه دیگری نیست، فقط جور دیگری بسته‌بندی شده.", "example": "اسکنر ورودی است، ویرایش اسکن پردازش است، فایل روی صفحه خروجی است، دیسک حافظه است.", "remember": ["ورودی، پردازش، خروجی.", "حافظه نتیجه میانی را نگه می‌دارد.", "شکل جعبه اصل را عوض نمی‌کند."], "summary": ""}, "mainboard": {"title": "برد اصلی", "goal": "", "definition": "برد اصلی پردازنده، حافظه، شکاف، برق و درگاه را وصل می‌کند. خودش حساب نمی‌کند.", "explanation": "همه قطعه‌ها یک حامل مشترک و خط مشترک لازم دارند. سوکت پردازنده را می‌گیرد. شکاف‌ها حافظه و کارت را می‌گیرند. درگاه‌ها به بیرون می‌روند، مثل USB. منبع تغذیه برق را به برد می‌دهد. برد جای منبع تغذیه نیست. اگر یک خط روی برد خراب باشد، پردازنده سریع‌تر کمک نمی‌کند.", "example": "کارت گرافیک، SSD و سوکت USB روی برد یا کنار آن نشسته‌اند. بدون برد پیوند مشترک ندارند.", "remember": ["برد وصل می‌کند، حساب نمی‌کند.", "سوکت، شکاف و درگاه جزو آن‌اند.", "برق از منبع تغذیه می‌آید."], "summary": ""}, "chipsatz": {"title": "چیپ‌ست", "goal": "", "definition": "چیپ‌ست کنترل می‌کند پردازنده چطور با حافظه، کارت و درگاه حرف می‌زند.", "explanation": "قبلاً این اغلب به پل شمالی و پل جنوبی تقسیم می‌شد. یکی نزدیک حافظه و گرافیک بود، دیگری نزدیک درگاه کندتر. امروز بخش زیادی از آن داخل خود پردازنده است. چیپ‌ست باقی روی برد بقیه را وصل می‌کند، مثل خط‌های بیشتر PCIe و USB. لازم نیست چیپ‌ست را ببینی تا بفهمی: بدون این میانجی داده منظم به پردازنده نمی‌رسد.", "example": "یک سوکت USB روی جعبه از راه برد به چیپ‌ست و از آنجا به پردازنده می‌رود. مستقیم به واحد حساب وصل نیست.", "remember": ["میانجی است، جای پردازنده نیست.", "قدیم: پل شمالی و جنوبی.", "امروز بخش زیادی داخل CPU است."], "summary": ""}, "schnittstellen": {"title": "PCIe و USB", "goal": "", "definition": "PCIe کارت سریع را نقطه‌به‌نقطه با خط وصل می‌کند. USB دستگاه را در لبه رایانه وصل می‌کند. شکل سوکت خودکار سرعت را نمی‌گوید.", "explanation": "PCIe یک پیوند سریال نقطه‌به‌نقطه است. یک کارت یک یا چند خط می‌گیرد، مثل x1، x4 یا x16. کارت گرافیک خط زیاد لازم دارد، یک کارت ساده کمتر. PCI موازی قدیمی همان چیز نیست. USB برای صفحه‌کلید، حافظه فلش، چاپگر و دستگاه‌های زیاد دیگر است. نسخه‌ها در سرعت فرق دارند. USB دستگاه کوچک را تغذیه می‌کند. جای منبع تغذیه کل رایانه نیست. مطلب بعدی این موضوع روی صفحه‌ها خوانا نبود و اینجا ساخته نشده است.", "example": "کارت گرافیک در PCIe x16 می‌نشیند. یک USB در USB بیرون فرو می‌رود. هر دو اتصال‌اند، ولی یک نوع گذرگاه نیستند.", "remember": ["PCIe: خط، داخل، برای کارت.", "USB: دستگاه در لبه.", "شکل سوکت سرعت نیست."], "summary": ""}}, "en": {"entwicklung": {"title": "From relays to the microprocessor", "goal": "", "definition": "Computers became smaller and denser: from electromechanical parts through tubes and transistors to integrated circuits and the microprocessor.", "explanation": "Each stage packs more switches into less space and needs less energy. The microprocessor puts the computing units on one chip. From that come PCs in different cases. The history worksheet was not readable as text. This sequence is the usual overview, not a copy of a timeline and not dates from class.", "example": "An early computer fills a room. The same idea sits today in a chip on the motherboard.", "remember": ["Denser, smaller, less energy.", "The microprocessor is the computing unit on one chip.", "No invented dates."], "summary": ""}, "eva": {"title": "Input, processing, output and form factors", "goal": "", "definition": "A computer takes data in, processes it and puts a result out. Storage holds data between these steps. The form factor is only the case.", "explanation": "Input is a keyboard, mouse, sensor or the network. Processing is the processor. Output is a monitor, a printer or a signal. Without storage every input would have to disappear at once. Tower, desktop, laptop, all-in-one and a server in a rack are form factors. They do not change the IPO principle. A laptop is not a different computer, only packed differently.", "example": "The scanner is input, editing the scan is processing, the file on the screen is output, the disk is storage.", "remember": ["Input, processing, output.", "Storage holds the in-between result.", "The form factor does not change the principle."], "summary": ""}, "mainboard": {"title": "Motherboard", "goal": "", "definition": "The motherboard connects the processor, memory, slots, power and ports. It does not compute by itself.", "explanation": "All parts need a shared carrier and shared lines. The socket takes the processor. The slots take memory and cards. Ports lead outward, such as USB. The power supply feeds power onto the board; the board does not replace the power supply. If a trace on the board is broken, a faster processor does not help.", "example": "Graphics card, SSD and USB socket sit on or at the motherboard. Without the board they would have no shared connection.", "remember": ["The board connects, it does not compute.", "Socket, slots and ports belong to it.", "Power comes from the power supply."], "summary": ""}, "chipsatz": {"title": "Chipset", "goal": "", "definition": "The chipset controls how the processor talks to memory, cards and ports.", "explanation": "In the past this was often split into a northbridge and a southbridge. One sat closer to memory and graphics, the other to slower ports. Today much of that sits in the processor itself. The remaining chipset on the board attaches the rest, such as further PCIe lanes and USB. You do not have to see the chipset to understand: without this mediation, data does not reach the processor in an orderly way.", "example": "A USB socket on the case leads over the board to the chipset and from there to the processor. It is not plugged straight into the computing unit.", "remember": ["It mediates, it does not replace the processor.", "Old: northbridge and southbridge.", "Today much of it sits in the CPU."], "summary": ""}, "schnittstellen": {"title": "PCIe and USB", "goal": "", "definition": "PCIe connects fast cards point to point with lanes. USB connects devices at the edge of the computer. The shape of the socket does not automatically tell the speed.", "explanation": "PCIe is a serial point-to-point link. A card gets one or more lanes, such as x1, x4 or x16. A graphics card needs many lanes, a simple interface card fewer. Old parallel PCI is not the same thing. USB is meant for keyboards, flash drives, printers and many other devices. Versions differ in speed. USB powers small devices; it does not replace the power supply of the whole PC. Further material after this topic was not readable on the pages and is not invented here.", "example": "A graphics card sits in PCIe x16. A USB stick plugs into USB on the outside. Both are connections, but not the same kind of bus.", "remember": ["PCIe: lanes, inside, for cards.", "USB: devices at the edge.", "Socket shape is not the speed."], "summary": ""}}}, {"id": "k10-projekt", "grade": "10", "subject": {"de": "Projektmanagement", "en": "Project management", "fa": "مدیریت پروژه"}, "order": ["merkmale", "erfolg", "phasen"], "de": {"merkmale": {"title": "Was ein Projekt ist", "goal": "", "definition": "Ein Projekt ist einmalig, hat ein klares Ergebnis, Meilensteine, begrenzte Mittel und ist von der laufenden Arbeit getrennt.", "explanation": "Einmalig heißt: es ist kein Dauerauftrag wie der tägliche Backup-Lauf. Das Ergebnis ist benannt, nicht „irgendwas mit Netz“. Meilensteine sind Prüfpunkte auf dem Weg, nicht das Endergebnis selbst. Zeit, Geld und Leute sind begrenzt. Das Projekt hat eigene Zuständige und ist organisatorisch vom Tagesgeschäft getrennt. Fehlt eines davon, ist es eine Aufgabe, aber noch kein Projekt.", "example": "„WLAN in Gebäude B bis zum 30. April, eigenes Team, Abnahme als Meilenstein“ ist ein Projekt. „Jeden Montag Druckerpapier holen“ ist keins.", "remember": ["Einmalig und klar begrenzt.", "Meilenstein ist ein Prüfpunkt.", "Tagesgeschäft ist kein Projekt."], "summary": ""}, "erfolg": {"title": "Gelingen und Scheitern", "goal": "", "definition": "Projekte scheitern an schweigsamer Abstimmung, offenen Kosten und Zeiten, fehlender Dokumentation, am Kunden vorbei und an der falschen Besetzung.", "explanation": "Erfolg ist dieselbe Liste in der anderen Richtung. Ihr sprecht den Stand aus, nicht nur in der Pause. Kosten und Termine werden nachgehalten, nicht erst am Ende. Dokumentation hält Entscheidungen fest, damit niemand raten muss. Der Kunde bestätigt, ob das Ergebnis noch das vereinbarte ist. Die Leute passen zur Aufgabe. Ein einzelner Held ersetzt das nicht. Wenn nur die Technik stimmt und der Kunde etwas anderes erwartet, ist das Projekt trotzdem daneben.", "example": "Das Team baut VLAN 30, der Kunde wollte nur neue Access Points im bestehenden Netz. Ohne Abstimmung ist die Technik umsonst.", "remember": ["Reden, nachhalten, aufschreiben.", "Der Kunde bestätigt das Ziel.", "Die Besetzung muss zur Aufgabe passen."], "summary": ""}, "phasen": {"title": "Phasen", "goal": "", "definition": "Das Projekt läuft in Vorbereitung, Planung und Steuerung. Zur Steuerung gehören Kontrolle und Dokumentation.", "explanation": "Vorbereitung klärt Ziel, Auftrag und Rahmen. Planung zerlegt das Ziel in Arbeitspakete, Termine, Kosten und Zuständige. Steuerung setzt den Plan um und vergleicht Ist und Soll. Dokumentation schreibt Abweichung und Entscheidung auf. Kontrolle ohne Schreiben vergisst, warum etwas geändert wurde. Du springst nicht mit dem Lötkolben in die Steuerung, solange das Ziel unklar ist.", "example": "Vorbereitung: „Access Points in Gebäude B, Abnahme am 30. April.“ Planung: Liste der Räume und der Termine. Steuerung: jede Woche Soll gegen Ist.", "remember": ["Erst Ziel, dann Plan, dann Steuerung.", "Ist und Soll vergleichen.", "Abweichungen aufschreiben."], "summary": ""}}, "fa": {"merkmale": {"title": "پروژه چیست", "goal": "", "definition": "پروژه یکتا است، نتیجه روشن، نقطه عطف، وسیله محدود دارد و از کار جاری جدا است.", "explanation": "یکتا یعنی کار همیشگی مثل پشتیبان روزانه نیست. نتیجه نام دارد، نه «چیزی با شبکه». نقطه عطف ایست بازرسی در راه است، نه خود نتیجه پایان. زمان، پول و آدم محدودند. پروژه مسئول خودش را دارد و از کار روزانه جدا سازماندهی شده. اگر یکی نباشد، یک کار است، ولی هنوز پروژه نیست.", "example": "«WLAN در ساختمان B تا ۳۰ آوریل، تیم خودش، تحویل به‌عنوان نقطه عطف» پروژه است. «هر دوشنبه کاغذ چاپگر بیاور» نیست.", "remember": ["یکتا و روشن محدود.", "نقطه عطف ایست بازرسی است.", "کار روزانه پروژه نیست."], "summary": ""}, "erfolg": {"title": "موفقیت و شکست", "goal": "", "definition": "پروژه با هماهنگی ساکت، هزینه و زمان باز، سند نبودن، رد شدن از مشتری و نفر اشتباه شکست می‌خورد.", "explanation": "موفقیت همان فهرست در جهت دیگر است. وضعیت را بلند می‌گویید، نه فقط در زنگ تفریح. هزینه و تاریخ پیگیری می‌شود، نه فقط در آخر. سند تصمیم را ثبت می‌کند تا کسی حدس نزند. مشتری تأیید می‌کند نتیجه هنوز همان توافق است. آدم‌ها به کار می‌خورند. یک قهرمان تنها جای این را نمی‌گیرد. اگر فقط فن درست باشد و مشتری چیز دیگری خواسته باشد، پروژه باز کنار است.", "example": "تیم VLAN 30 می‌سازد، مشتری فقط نقطه دسترسی تازه در شبکه موجود می‌خواست. بدون توافق فن هدر است.", "remember": ["حرف بزن، پیگیری کن، بنویس.", "مشتری هدف را تأیید می‌کند.", "ترکیب نفرات باید به کار بخورد."], "summary": ""}, "phasen": {"title": "مراحل", "goal": "", "definition": "پروژه از آماده‌سازی، برنامه‌ریزی و هدایت می‌گذرد. هدایت شامل کنترل و سند است.", "explanation": "آماده‌سازی هدف، سفارش و چارچوب را روشن می‌کند. برنامه‌ریزی هدف را به بسته کار، تاریخ، هزینه و مسئول تقسیم می‌کند. هدایت طرح را اجرا می‌کند و واقعی را با برنامه مقایسه می‌کند. سند انحراف و تصمیم را می‌نویسد. کنترل بدون نوشتن فراموش می‌کند چرا چیزی عوض شد. با هویه به هدایت نمی‌پری تا وقتی هدف ناروشن است.", "example": "آماده‌سازی: «نقطه دسترسی در ساختمان B، تحویل ۳۰ آوریل.» برنامه‌ریزی: فهرست اتاق و تاریخ. هدایت: هر هفته برنامه در برابر واقعی.", "remember": ["اول هدف، بعد طرح، بعد هدایت.", "واقعی و برنامه را مقایسه کن.", "انحراف را بنویس."], "summary": ""}}, "en": {"merkmale": {"title": "What a project is", "goal": "", "definition": "A project is unique, has a clear result, milestones, limited means and is separate from ongoing work.", "explanation": "Unique means it is not a standing job like the daily backup run. The result is named, not “something with the network”. Milestones are checkpoints on the way, not the end result itself. Time, money and people are limited. The project has its own people in charge and is organisationally separate from daily business. If one of these is missing, it is a task, but not yet a project.", "example": "“WLAN in building B by 30 April, its own team, acceptance as a milestone” is a project. “Fetch printer paper every Monday” is not.", "remember": ["Unique and clearly limited.", "A milestone is a checkpoint.", "Daily business is not a project."], "summary": ""}, "erfolg": {"title": "Success and failure", "goal": "", "definition": "Projects fail through silent coordination, open costs and times, missing documentation, missing the customer and the wrong staffing.", "explanation": "Success is the same list in the other direction. You say the status out loud, not only in the break. Costs and dates are tracked, not only at the end. Documentation records decisions so nobody has to guess. The customer confirms whether the result is still the one you agreed. The people fit the task. A single hero does not replace that. If only the technology is right and the customer expected something else, the project is still off.", "example": "The team builds VLAN 30, the customer only wanted new access points in the existing network. Without agreement the technology is wasted.", "remember": ["Talk, track, write it down.", "The customer confirms the goal.", "The staffing must fit the task."], "summary": ""}, "phasen": {"title": "Phases", "goal": "", "definition": "The project runs through preparation, planning and control. Control includes checking and documentation.", "explanation": "Preparation clarifies the goal, the order and the frame. Planning splits the goal into work packages, dates, costs and owners. Control carries out the plan and compares actual and planned. Documentation writes down the deviation and the decision. Checking without writing forgets why something was changed. You do not jump into control with a soldering iron while the goal is still unclear.", "example": "Preparation: “access points in building B, acceptance on 30 April.” Planning: the list of rooms and dates. Control: planned against actual every week.", "remember": ["Goal first, then plan, then control.", "Compare actual and planned.", "Write deviations down."], "summary": ""}}}, {"id": "k10-pug", "grade": "10", "subject": {"de": "Politik und Gesellschaft", "en": "Politics and society", "fa": "سیاست و جامعه"}, "order": ["motive", "vertrag", "dual", "jugend"], "de": {"motive": {"title": "Warum ausgebildet wird", "goal": "", "definition": "Ausbildung sichert dem Betrieb Fachkräfte und der lernenden Person einen anerkannten Beruf. Arbeit ist dabei mehr als Beschäftigung.", "explanation": "Der Betrieb braucht Leute, die die Tätigkeit nach einem geregelten Plan können. Die lernende Person braucht einen Abschluss, der außerhalb dieses einen Betriebs gilt. Arbeit bringt Einkommen, Können und Teilnahme am Betrieb. Sie ist kein Gefallen und kein unbezahltes Mitlaufen. Die Motive aus dem Unterricht stehen hier als diese drei Seiten. Die Arbeitsblätter waren Scans und werden nicht als wörtliche Lösungen ausgegeben.", "example": "Ein Betrieb bildet Fachinformatiker aus, weil er später Systemintegration braucht. Der Abschluss gilt auch in einem anderen Betrieb.", "remember": ["Betrieb braucht Können.", "Der Abschluss gilt über den einen Betrieb hinaus.", "Arbeit ist Einkommen und Teilnahme, nicht nur Anwesenheit."], "summary": ""}, "vertrag": {"title": "Ausbildungsvertrag", "goal": "", "definition": "Der Ausbildungsvertrag ist schriftlich und nennt die Bedingungen der Ausbildung, bevor sie beginnt.", "explanation": "Das Berufsbildungsgesetz verlangt mindestens: Art, Gliederung und Ziel der Ausbildung, Beginn und Dauer, Maßnahmen außerhalb der Ausbildungsstätte, die tägliche Ausbildungszeit, die Probezeit, Höhe und Zahlung der Vergütung, den Urlaub und die Voraussetzungen einer Kündigung. Hinweise auf geltende Tarifverträge gehören dazu. Die Probezeit dauert mindestens einen und höchstens vier Monate. Ausbildende und lernende Person unterschreiben. Bei Minderjährigen unterschreibt auch die gesetzliche Vertretung. Der Vertrag wird der zuständigen Kammer gemeldet. Das ist die gesetzliche Mindestliste, keine Abschrift eines gescannten Formulars.", "example": "Ein mündlicher Satz „du fängst Montag an“ ersetzt den schriftlichen Vertrag nicht. Vergütung und Urlaub müssen auf dem Papier stehen.", "remember": ["Schriftlich und vor Beginn.", "Probezeit: ein bis vier Monate.", "Die Kammer bekommt den Vertrag."], "summary": ""}, "dual": {"title": "Duales System", "goal": "", "definition": "Die Ausbildung läuft an zwei Orten: im Betrieb und in der Berufsschule. Beide sind Pflicht, keiner ersetzt den anderen.", "explanation": "Der Betrieb vermittelt die Praxis nach der Ausbildungsordnung. Die Berufsschule vermittelt die Theorie nach dem Lehrplan des Landes. Der Ausbildungsvertrag besteht mit dem Betrieb, nicht mit der Schule. Trotzdem darfst du die Schule nicht auslassen, weil im Betrieb gerade viel zu tun ist. Freistellung für den Unterricht ist Teil der Ausbildung. Betrieb und Schule sollen denselben Beruf meinen, nicht zwei verschiedene.", "example": "Montags lernst du im Betrieb VLANs. Dienstags erklärst du in der Schule, warum ein Router Netze trennt. Beides gehört zur selben Ausbildung.", "remember": ["Betrieb: Praxis. Schule: Theorie.", "Der Vertrag ist mit dem Betrieb.", "Schule ausfallen zu lassen ist keine Überstunde."], "summary": ""}, "jugend": {"title": "Jugendarbeitsschutz", "goal": "", "definition": "Das Jugendarbeitsschutzgesetz begrenzt Zeit und Belastung von Beschäftigten unter 18 Jahren. Ausnahmen stehen im Gesetz, nicht in einem Merksatz.", "explanation": "Jugendliche im Sinn dieses Schutzes sind 15 Jahre und noch nicht 18. Grundsätzlich gelten höchstens 8 Stunden am Tag und 40 Stunden in der Woche. Zwischen 20 Uhr und 6 Uhr dürfen sie in der Regel nicht arbeiten. Bei mehr als 4,5 bis 6 Stunden gibt es mindestens 30 Minuten Pause, bei mehr als 6 Stunden mindestens 60 Minuten. Nach der Arbeit müssen mindestens 12 Stunden Ruhe liegen. Unterricht an der Berufsschule wird auf die Arbeitszeit angerechnet. Der Betrieb darf die Grenze nicht mit dem Satz „heute ist viel los“ aufheben.", "example": "Eine Schicht von 9 bis 18 Uhr ohne 60 Minuten Pause ist zu lang. Neun Stunden Arbeit plus Schule am selben Tag rechnest du zusammen, nicht getrennt.", "remember": ["8 Stunden am Tag, 40 in der Woche, als Grundsatz.", "Nachtarbeit ist grundsätzlich tabu.", "Schule zählt als Arbeitszeit."], "summary": ""}}, "fa": {"motive": {"title": "چرا آموزش داده می‌شود", "goal": "", "definition": "آموزش برای بنگاه نیروی متخصص و برای شخص در حال یادگیری یک شغل شناخته‌شده تأمین می‌کند. کار بیش از مشغول بودن است.", "explanation": "بنگاه آدم‌هایی لازم دارد که کار را طبق یک طرح منظم بتوانند. شخص در حال یادگیری مدرکی لازم دارد که بیرون از همین یک بنگاه معتبر باشد. کار درآمد، مهارت و سهم در بنگاه می‌آورد. لطف نیست و دنباله‌روی بی‌مزد هم نیست. انگیزه‌های کلاس اینجا همین سه سمت‌اند. برگه‌ها اسکن بودند و به‌صورت جواب کلمه‌به‌کلمه داده نشده‌اند.", "example": "یک بنگاه متخصص IT تربیت می‌کند چون بعداً یکپارچه‌سازی سامانه لازم دارد. مدرک در بنگاه دیگر هم معتبر است.", "remember": ["بنگاه مهارت لازم دارد.", "مدرک فراتر از یک بنگاه معتبر است.", "کار درآمد و مشارکت است، نه فقط حضور."], "summary": ""}, "vertrag": {"title": "قرارداد آموزش", "goal": "", "definition": "قرارداد آموزش نوشتاری است و شرایط آموزش را پیش از شروع نام می‌برد.", "explanation": "قانون آموزش شغلی حداقل این‌ها را می‌خواهد: نوع، ساختار و هدف آموزش، شروع و مدت، اقدام بیرون از محل آموزش، زمان روزانه آموزش، دوره آزمایشی، مقدار و پرداخت دستمزد آموزش، مرخصی و شرط فسخ. اشاره به پیمان جمعی معتبر جزو آن است. دوره آزمایشی حداقل یک و حداکثر چهار ماه است. آموزش‌دهنده و شخص در حال یادگیری امضا می‌کنند. اگر زیر سن قانونی باشد، نماینده قانونی هم امضا می‌کند. قرارداد به اتاق مسئول گزارش می‌شود. این فهرست حداقل قانونی است، نه رونوشت یک فرم اسکن‌شده.", "example": "یک جمله شفاهی «دوشنبه شروع می‌کنی» جای قرارداد نوشتاری را نمی‌گیرد. دستمزد آموزش و مرخصی باید روی کاغذ باشند.", "remember": ["نوشتاری و پیش از شروع.", "دوره آزمایشی: یک تا چهار ماه.", "اتاق قرارداد را می‌گیرد."], "summary": ""}, "dual": {"title": "نظام دوگانه", "goal": "", "definition": "آموزش در دو جا می‌رود: در بنگاه و در هنرستان شغلی. هر دو واجب‌اند، هیچ‌کدام جای دیگری نیست.", "explanation": "بنگاه عمل را طبق آیین آموزش می‌دهد. هنرستان شغلی نظریه را طبق برنامه ایالت می‌دهد. قرارداد آموزش با بنگاه است، نه با مدرسه. با این حال نمی‌توانی مدرسه را حذف کنی چون بنگاه شلوغ است. مرخصی برای کلاس جزو آموزش است. بنگاه و مدرسه باید یک شغل را منظور کنند، نه دو شغل متفاوت.", "example": "دوشنبه VLAN را در بنگاه یاد می‌گیری. سه‌شنبه در مدرسه توضیح می‌دهی چرا مسیریاب شبکه را جدا می‌کند. هر دو مال همان آموزش‌اند.", "remember": ["بنگاه: عمل. مدرسه: نظریه.", "قرارداد با بنگاه است.", "حذف مدرسه اضافه‌کار نیست."], "summary": ""}, "jugend": {"title": "حمایت از کار جوانان", "goal": "", "definition": "قانون حمایت از کار جوانان زمان و فشار کارکنان زیر ۱۸ سال را محدود می‌کند. استثنا در قانون است، نه در یک جمله حفظی.", "explanation": "جوان در معنی این حمایت ۱۵ ساله است و هنوز ۱۸ نشده. قاعده حداکثر ۸ ساعت در روز و ۴۰ ساعت در هفته است. بین ساعت ۲۰ و ۶ معمولاً نباید کار کنند. برای بیش از ۴٫۵ تا ۶ ساعت حداقل ۳۰ دقیقه استراحت، برای بیش از ۶ ساعت حداقل ۶۰ دقیقه. بعد از کار حداقل ۱۲ ساعت آرامش باید باشد. زمان هنرستان شغلی جزو زمان کار حساب می‌شود. بنگاه نمی‌تواند سقف را با جمله «امروز شلوغ است» بردارد.", "example": "یک شیفت از ۹ تا ۱۸ بدون ۶۰ دقیقه استراحت خیلی بلند است. نه ساعت کار به‌اضافه مدرسه در همان روز را با هم حساب می‌کنی، نه جدا.", "remember": ["۸ ساعت در روز، ۴۰ در هفته، به‌عنوان قاعده.", "کار شب قاعدتاً ممنوع است.", "مدرسه جزو زمان کار است."], "summary": ""}}, "en": {"motive": {"title": "Why training exists", "goal": "", "definition": "Training secures skilled people for the firm and a recognised occupation for the learner. Work is more than being busy.", "explanation": "The firm needs people who can do the work according to a regulated plan. The learner needs a qualification that counts outside this one firm. Work brings income, skill and a part in the firm. It is not a favour and not unpaid tagging along. The motives from class are these three sides here. The worksheets were scans and are not given out as word-for-word answers.", "example": "A firm trains IT specialists because it will need systems integration later. The qualification also counts in another firm.", "remember": ["The firm needs skill.", "The qualification counts beyond the one firm.", "Work is income and participation, not only presence."], "summary": ""}, "vertrag": {"title": "Training contract", "goal": "", "definition": "The training contract is in writing and states the conditions of the training before it begins.", "explanation": "The Vocational Training Act requires at least: the type, structure and aim of the training, start and duration, measures outside the training site, the daily training time, the probation period, the amount and payment of the allowance, the leave and the conditions for termination. A reference to applicable collective agreements belongs in it. Probation lasts at least one and at most four months. The trainer and the learner sign. If the learner is a minor, the legal guardian also signs. The contract is reported to the competent chamber. This is the statutory minimum list, not a copy of a scanned form.", "example": "An oral sentence “you start on Monday” does not replace the written contract. Allowance and leave must be on the paper.", "remember": ["In writing and before the start.", "Probation: one to four months.", "The chamber receives the contract."], "summary": ""}, "dual": {"title": "Dual system", "goal": "", "definition": "Training runs in two places: in the firm and at vocational school. Both are compulsory, neither replaces the other.", "explanation": "The firm teaches the practice according to the training regulation. Vocational school teaches the theory according to the state curriculum. The training contract is with the firm, not with the school. Even so you may not skip school because the firm is busy. Release for class is part of the training. Firm and school should mean the same occupation, not two different ones.", "example": "On Monday you learn VLANs in the firm. On Tuesday you explain at school why a router separates networks. Both belong to the same training.", "remember": ["Firm: practice. School: theory.", "The contract is with the firm.", "Skipping school is not overtime."], "summary": ""}, "jugend": {"title": "Protection of young workers", "goal": "", "definition": "The Youth Employment Protection Act limits the time and strain of employees under 18. Exceptions are in the statute, not in a memory sentence.", "explanation": "Young people in the sense of this protection are 15 and not yet 18. As a rule the maximum is 8 hours a day and 40 hours a week. Between 8 p.m. and 6 a.m. they generally may not work. For more than 4.5 up to 6 hours there is at least a 30-minute break, for more than 6 hours at least 60 minutes. After work there must be at least 12 hours of rest. Vocational-school time counts toward working time. The firm may not lift the limit with the sentence “it is busy today”.", "example": "A shift from 9 to 18 without a 60-minute break is too long. Nine hours of work plus school on the same day are counted together, not apart.", "remember": ["8 hours a day, 40 a week, as the rule.", "Night work is generally off limits.", "School counts as working time."], "summary": ""}}}, {"id": "it-systeme", "grade": "11", "subject": {"de": "IT-Systeme", "en": "IT systems", "fa": "سیستم‌های IT"}, "order": ["osi", "ip", "subnet", "vlan", "dhcp", "dns", "routing", "nat", "ipv6", "topo", "troubleshoot", "security"], "de": {"osi": {"title": "OSI-Modell", "goal": "", "definition": "Das OSI-Modell ist ein Denkmodell mit Schichten. Es sagt, wo du bei einer Störung suchst, nicht welches Kabel du kaufen sollst.", "explanation": "Unten liegt die Physik, oben das Programm. Für die Praxis reichen vier Gruppen. Schicht 1 ist Kabel, Stecker und Link-LED. Schicht 2 ist die MAC-Adresse, der Switch und das VLAN. Schicht 3 ist die IP-Adresse und der Router. Schicht 4 bis 7 tragen TCP oder UDP, Ports und Programme wie den Browser. Du suchst immer von unten nach oben, weil eine tote Leitung jede höhere Prüfung sinnlos macht.", "example": "Ping an das Gateway 192.168.10.1 klappt, die Website nicht. Schicht 3 ist dann oft in Ordnung. Verdächtig sind der Name (DNS) oder eine Sperre weiter oben, zum Beispiel eine Firewall.", "remember": ["VLAN gehört zu Schicht 2. Es ist keine Kabelart.", "Ein dunkles Link-LED prüfst du zuerst auf Schicht 1.", "Port 443 ist die Tür eines Programms, nicht die Buchse am Switch."], "summary": ""}, "ip": {"title": "IP, Maske und Gateway", "goal": "", "definition": "Die IPv4-Adresse nennt den Rechner. Die Subnetzmaske sagt, welcher Teil das Netz ist. Das Gateway ist die Tür aus diesem Netz, meist der Router.", "explanation": "Gleiche Netz-ID bedeutet: der Partner ist direkt erreichbar, ein Switch reicht. Eine andere Netz-ID bedeutet: das Paket muss zum Gateway. Ohne Gateway bleibt der Rechner in seinem eigenen Netz, auch wenn das Kabel steckt. Die Maske /24 ist 255.255.255.0. Dann sind die ersten drei Zahlen das Netz.", "example": "Der PC 192.168.10.50/24 erreicht 192.168.10.10 direkt. 192.168.20.10 erreicht er nur über das Gateway 192.168.10.1.", "remember": ["Gleiche Netz-ID: direkt. Andere Netz-ID: Gateway.", "Das Gateway muss im eigenen Netz liegen, sonst findet der PC die Tür nicht.", "Ohne Gateway erreichst du 8.8.8.8 nicht."], "summary": ""}, "subnet": {"title": "Subnetting", "goal": "", "definition": "Subnetting schneidet ein großes Netz in kleinere Blöcke. Die Präfixlänge sagt, wie viele Bits zum Netz gehören.", "explanation": "Die Blockgröße ist 2 hoch (32 minus Präfix). Nutzbare Hosts sind Blockgröße minus 2, weil die erste Adresse das Netz und die letzte der Broadcast ist. /24 hat 256 Adressen und 254 Hosts. /25 hat 128 Adressen und 126 Hosts. /26 hat 64 Adressen und 62 Hosts. Ein höheres Präfix macht den Block kleiner.", "example": "192.168.50.0/24 wird zu 192.168.50.0/25 (0 bis 127) und 192.168.50.128/25 (128 bis 255).", "remember": ["/26 hat 62 nutzbare Hosts, nicht 64.", "/25 ist eine Hälfte eines /24, nicht dasselbe wie /24.", "Netzadresse und Broadcast darfst du keinem Host geben."], "summary": ""}, "vlan": {"title": "VLAN", "goal": "", "definition": "Ein VLAN ist ein logisches Netz auf einem physischen Switch. Geräte in verschiedenen VLANs sprechen nicht miteinander, bis ein Router vermittelt.", "explanation": "Ein Access-Port trägt genau ein VLAN und gehört an einen PC. Ein Trunk-Port trägt mehrere VLANs mit Tags und gehört zwischen Switch und Router. Typisch: VLAN 10 Büro, VLAN 20 Technik, VLAN 30 Gäste. Der Gast sieht den Dateiserver nicht, solange keine Route und keine Freigabe existieren.", "example": "Der Uplink zum Router-on-a-Stick muss ein Trunk sein. Als Access käme nur ein VLAN am Router an.", "remember": ["Access für Endgeräte, Trunk für mehrere VLANs.", "Ein VLAN trennt logisch. Es ersetzt keinen Router.", "Gäste und Dateiserver gehören nicht ins selbe VLAN."], "summary": ""}, "dhcp": {"title": "DHCP", "goal": "", "definition": "DHCP vergibt IP-Adresse, Maske, Gateway und oft den DNS-Server automatisch. Die vergebene Adresse ist eine Miete auf Zeit, ein Lease.", "explanation": "Der Ablauf heißt DORA. Discover: der Client sucht einen Server, weil er ihn noch nicht kennt. Offer: der Server bietet eine Adresse aus dem Pool an. Request: der Client will genau dieses Angebot. Acknowledge: der Server bestätigt die Miete. Feste Geräte wie der Router liegen außerhalb des Pools, sonst gibt es zwei Besitzer derselben Adresse.", "example": "Pool 192.168.10.100 bis 192.168.10.200. Der Router 192.168.10.1 darf nicht im Pool liegen.", "remember": ["Reihenfolge: Discover, Offer, Request, Acknowledge.", "Discover ist die Suche. Request ist die Annahme.", "DHCP verteilt Adressen. Es übersetzt keine Namen."], "summary": ""}, "dns": {"title": "DNS", "goal": "", "definition": "DNS übersetzt einen Namen in eine IP-Adresse. Menschen merken sich den Namen, Pakete brauchen die Zahl.", "explanation": "Ein A-Record zeigt von einem Namen auf eine IPv4-Adresse. Der Resolver ist der Dienst, den der PC fragt. Prüfe zuerst die nackte IP. Wenn die IP antwortet und der Name nicht, ist die Leitung in Ordnung und die Namensauflösung kaputt. DNS und DHCP sind verschiedene Dienste: DHCP gibt die Adresse, DNS übersetzt den Namen.", "example": "fileserver.firma.local soll 192.168.10.10 sein. Ping auf die Zahl klappt, Ping auf den Namen nicht: Eintrag oder DNS-Server prüfen.", "remember": ["IP geht, Name nicht: DNS.", "DHCP ist nicht DNS.", "Zuerst die IP pingen, danach den Namen."], "summary": ""}, "routing": {"title": "Routing", "goal": "", "definition": "Routing ist die Entscheidung, in welches Netz ein Paket als Nächstes geschickt wird.", "explanation": "Liegt das Ziel im eigenen Netz, reicht der Switch. Liegt es in einem anderen Netz oder VLAN, brauchst du einen Router mit passender Route. Eine statische Route trägt der Admin von Hand ein. Die Default-Route ist der Weg für alles, was nicht genauer passt. Ein normaler Layer-2-Switch routet nicht zwischen VLANs. Ohne passende Route verwirft der Router das Paket.", "example": "Ein PC in VLAN 10 erreicht VLAN 20 nicht, solange der Router keine Route zwischen den beiden Netzen hat.", "remember": ["Gleich es Netz: Switch. Anderes Netz: Router.", "Inter-VLAN-Routing ist die Verbindung zwischen VLANs.", "Ein L2-Switch trennt VLANs. Er verbindet sie nicht."], "summary": ""}, "nat": {"title": "NAT", "goal": "", "definition": "NAT übersetzt viele private Adressen in wenige öffentliche, damit das Firmennetz ins Internet kann.", "explanation": "Bereiche wie 192.168.0.0/16 sind privat. Dieselbe Zahl darf in vielen Firmen vorkommen und wird im Internet nicht geroutet. Der PC sendet mit seiner privaten Adresse. Der Router merkt sich die Übersetzung und zeigt nach außen seine öffentliche Adresse. Antworten übersetzt er zurück. Ein Server im Internet kann deshalb nicht von sich aus 192.168.10.50 anrufen.", "example": "192.168.10.50 wird am Router zu 203.0.113.5. Das Internet sieht nur 203.0.113.5.", "remember": ["Privat innen, NAT an der Grenze, öffentlich außen.", "192.168.10.50 ist nicht weltweit eindeutig.", "NAT ist keine Namensauflösung."], "summary": ""}, "ipv6": {"title": "IPv6", "goal": "", "definition": "IPv6 ist die neuere Adresse mit 128 Bit. IPv4 hat nur 32 Bit, der Vorrat ist knapp.", "explanation": "Die Schreibweise ist hexadezimal, Doppelpunkte trennen die Gruppen. :: darf eine zusammenhängende Nullfolge genau einmal kürzen. Zweimal :: in derselben Adresse ist ungültig, weil die Länge sonst unklar ist. 2001:db8::/32 ist für Beispiele reserviert und kein echtes Firmennetz.", "example": "2001:0db8:85a3::8a2e:0370:7334 ist eine gekürzte IPv6-Adresse, kein IPv4-Wert.", "remember": ["IPv6 hat 128 Bit, IPv4 hat 32.", ":: nur einmal pro Adresse.", "Dokumentationspräfix: 2001:db8::/32."], "summary": ""}, "topo": {"title": "Topologie", "goal": "", "definition": "Die Topologie beschreibt, wer mit wem verbunden ist.", "explanation": "Im Stern hängt jedes Gerät an einem zentralen Switch. Fällt ein Kabel aus, arbeitet der Rest weiter. Fällt der Switch aus, steht alles. Der Bus ist ein gemeinsames Kabel und heute selten. Die Masche hat mehrere Wege und ist teurer, aber ausfallsicherer. Büros nutzen meist den Stern. Zwei Core-Switches mit Querverbindung nähern sich einer kleinen Masche.", "example": "Zwanzig PCs an einem Etagen-Switch sind ein Stern. Ein defektes PC-Kabel legt nur diesen PC lahm.", "remember": ["Der zentrale Switch ist der einzelne Ausfallpunkt im Stern.", "Ein Stern hat keinen Schutz, wenn der Mittelpunkt ausfällt.", "Mehrere Wege sind eine Masche, kein Stern."], "summary": ""}, "troubleshoot": {"title": "Fehlersuche", "goal": "", "definition": "Eine Netzstörung prüfst du in fester Reihenfolge, nicht bei der Firewall, wenn das Kabel lose ist.", "explanation": "Erst Link und Kabel. Dann ipconfig unter Windows oder ip addr unter Linux: Hast du IP, Maske und Gateway? Dann Ping an das eigene Gateway. Dann Ping an 8.8.8.8, das braucht keinen Namen. Erst danach den Namen prüfen. Wenn das Gateway antwortet und 8.8.8.8 nicht, liegt es eher an der Route nach außen, an NAT oder an einer Firewall. Wenn schon das Gateway schweigt, suchst du im eigenen Netz.", "example": "Ping an 8.8.8.8 klappt, www.example.com nicht. Die Verbindung nach außen steht, DNS nicht.", "remember": ["Reihenfolge: Link, IP, Gateway, außen, Name.", "8.8.8.8 prüft die IP-Verbindung, nicht DNS.", "Nicht mit dem Namen anfangen."], "summary": ""}, "security": {"title": "Sicherheit im kleinen Netz", "goal": "", "definition": "Sicherheit heißt hier Begrenzung: nur nötige Ports, nur nötige Rechte, getrennte Gäste, aktuelle Systeme und eine Kopie der Daten.", "explanation": "Schließe Ports, die kein Dienst braucht. Least Privilege bedeutet: jedes Konto darf nur seine eigene Aufgabe. Gäste kommen in ein eigenes VLAN und dürfen nicht blind ins Datennetz. Updates und Backups planst du, du hoffst sie nicht. Zwischen VLANs steht eine Firewall. Offen lassen, weil dann alles funktioniert, macht auch den Angriff leichter.", "example": "Das Gast-WLAN darf ins Internet, aber nicht auf den Dateiserver. Das ist VLAN plus eine Firewall-Regel, nicht ein offenes Routing.", "remember": ["Weniger Fläche: Ports, Rechte, Netze.", "Backup ist die Kopie, bevor etwas verloren geht.", "Gäste nicht ins interne Netz routen."], "summary": ""}}, "fa": {"osi": {"title": "مدل OSI", "goal": "", "definition": "مدل OSI یک مدل فکری با لایه‌هاست. می‌گوید خرابی را کجا بگردی، نه اینکه کدام کابل را بخری.", "explanation": "پایین مسیر فیزیکی است و بالا برنامه. در کلاس همین چهار گروه کافی است. لایه ۱ کابل، فیش و چراغ لینک است. لایه ۲ آدرس MAC، سوئیچ و VLAN است. لایه ۳ آدرس IP و روتر است. لایه‌های ۴ تا ۷ شامل TCP یا UDP، پورت و برنامه‌هایی مثل مرورگرند. همیشه از پایین به بالا بگرد، چون اگر لینک مرده باشد آزمون بالاتر بی‌معنی است.", "example": "پینگ به گیت‌وی 192.168.10.1 جواب می‌دهد، ولی وب‌سایت باز نمی‌شود. لایه ۳ اغلب سالم است. احتمال بیشتر با نام (DNS) یا یک سد بالاتر مثل فایروال است.", "remember": ["VLAN لایه ۲ است، نه نوعی کابل.", "چراغ لینک خاموش را اول در لایه ۱ بررسی کن.", "پورت ۴۴۳ درِ یک برنامه است، نه سوکت روی سوئیچ."], "summary": ""}, "ip": {"title": "IP، ماسک و گیت‌وی", "goal": "", "definition": "آدرس IPv4 رایانه را مشخص می‌کند. ماسک زیرشبکه می‌گوید کدام بخش، شبکه است. گیت‌وی درِ خروج از همین شبکه است و معمولاً روتر است.", "explanation": "اگر شناسه شبکه یکی باشد، طرف مقابل مستقیم در دسترس است و سوئیچ کافی است. اگر شناسه فرق کند، بسته باید به گیت‌وی برود. بدون گیت‌وی رایانه در شبکه خودش می‌ماند، حتی اگر کابل وصل باشد. ماسک /24 همان 255.255.255.0 است. در این حالت سه عدد اول، شبکه است.", "example": "رایانه 192.168.10.50/24 به 192.168.10.10 مستقیم می‌رسد. به 192.168.20.10 فقط از راه گیت‌وی 192.168.10.1 می‌رسد.", "remember": ["شناسه یکسان: مستقیم. شناسه متفاوت: گیت‌وی.", "گیت‌وی باید در شبکه خودت باشد، وگرنه رایانه در را پیدا نمی‌کند.", "بدون گیت‌وی به 8.8.8.8 نمی‌رسی."], "summary": ""}, "subnet": {"title": "زیرشبکه‌سازی", "goal": "", "definition": "زیرشبکه‌سازی یک شبکه بزرگ را به بلوک‌های کوچک‌تر می‌بُرد. طول پیشوند می‌گوید چند بیت مال شبکه است.", "explanation": "اندازه بلوک برابر است با ۲ به توان (۳۲ منهای پیشوند). میزبان‌های قابل استفاده برابرند با اندازه بلوک منهای ۲، چون آدرس اول شبکه است و آدرس آخر برودکست. /24 دارای ۲۵۶ آدرس و ۲۵۴ میزبان است. /25 دارای ۱۲۸ آدرس و ۱۲۶ میزبان است. /26 دارای ۶۴ آدرس و ۶۲ میزبان است. پیشوند بزرگ‌تر، بلوک را کوچک‌تر می‌کند.", "example": "192.168.50.0/24 می‌شود 192.168.50.0/25 (۰ تا ۱۲۷) و 192.168.50.128/25 (۱۲۸ تا ۲۵۵).", "remember": ["/26 شصت‌ودو میزبان قابل استفاده دارد، نه ۶۴.", "/25 نصف یک /24 است، نه خود /24.", "آدرس شبکه و برودکست را به هیچ میزبانی نده."], "summary": ""}, "vlan": {"title": "VLAN", "goal": "", "definition": "VLAN یک شبکه منطقی روی یک سوئیچ فیزیکی است. دستگاه‌های VLANهای مختلف با هم حرف نمی‌زنند، تا وقتی یک روتر وصلشان کند.", "explanation": "پورت Access دقیقاً یک VLAN دارد و به رایانه وصل می‌شود. پورت Trunk چند VLAN را با برچسب حمل می‌کند و بین سوئیچ و روتر است. نمونه: VLAN 10 دفتر، VLAN 20 فنی، VLAN 30 مهمان. مهمان فایل‌سرور را نمی‌بیند، تا وقتی مسیر و اجازه وجود نداشته باشد.", "example": "اتصال بالاسو به روتر روی یک لینک باید Trunk باشد. اگر Access باشد فقط یک VLAN به روتر می‌رسد.", "remember": ["Access برای دستگاه نهایی، Trunk برای چند VLAN.", "VLAN منطقی جدا می‌کند. جای روتر را نمی‌گیرد.", "مهمان و فایل‌سرور نباید در یک VLAN باشند."], "summary": ""}, "dhcp": {"title": "DHCP", "goal": "", "definition": "DHCP آدرس IP، ماسک، گیت‌وی و اغلب سرور DNS را خودکار می‌دهد. این آدرس یک اجاره زمان‌دار است.", "explanation": "ترتیب را DORA می‌نامند. Discover: کلاینت سرور را می‌جوید چون هنوز او را نمی‌شناسد. Offer: سرور یک آدرس از استخر پیشنهاد می‌کند. Request: کلاینت همان پیشنهاد را می‌خواهد. Acknowledge: سرور اجاره را تأیید می‌کند. دستگاه‌های ثابت مثل روتر بیرون استخر می‌مانند، وگرنه دو صاحب برای یک آدرس پیدا می‌شود.", "example": "استخر از 192.168.10.100 تا 192.168.10.200. روتر 192.168.10.1 نباید داخل استخر باشد.", "remember": ["ترتیب: Discover، Offer، Request، Acknowledge.", "Discover جستجو است. Request پذیرش است.", "DHCP آدرس می‌دهد. نام را ترجمه نمی‌کند."], "summary": ""}, "dns": {"title": "DNS", "goal": "", "definition": "DNS یک نام را به آدرس IP ترجمه می‌کند. انسان نام را به خاطر می‌سپارد، بسته‌ها به عدد نیاز دارند.", "explanation": "یک رکورد A نام را به یک آدرس IPv4 وصل می‌کند. Resolver همان خدمتی است که رایانه از آن می‌پرسد. اول خود IP را امتحان کن. اگر IP جواب بدهد و نام نه، مسیر سالم است و ترجمه نام خراب است. DNS و DHCP دو خدمت جدا هستند: DHCP آدرس می‌دهد، DNS نام را ترجمه می‌کند.", "example": "fileserver.firma.local باید 192.168.10.10 باشد. پینگ به عدد جواب می‌دهد و پینگ به نام نه: رکورد یا سرور DNS را بررسی کن.", "remember": ["IP کار می‌کند، نام نه: DNS.", "DHCP همان DNS نیست.", "اول IP را پینگ کن، بعد نام را."], "summary": ""}, "routing": {"title": "مسیریابی", "goal": "", "definition": "مسیریابی تصمیم این است که بسته بعد به کدام شبکه فرستاده شود.", "explanation": "اگر مقصد در شبکه خودت باشد، سوئیچ کافی است. اگر در شبکه یا VLAN دیگری باشد، به روتری با مسیر مناسب نیاز داری. مسیر ایستا را مدیر با دست وارد می‌کند. مسیر پیش‌فرض راه همه‌چیزهایی است که دقیق‌تر جور نمی‌شوند. یک سوئیچ معمولی لایه ۲ بین VLANها مسیریابی نمی‌کند. بدون مسیر مناسب، روتر بسته را دور می‌ریزد.", "example": "یک رایانه در VLAN 10 به VLAN 20 نمی‌رسد، تا وقتی روتر مسیری بین این دو شبکه نداشته باشد.", "remember": ["شبکه یکسان: سوئیچ. شبکه دیگر: روتر.", "مسیریابی بین‌VLAN اتصال بین VLANهاست.", "سوئیچ لایه ۲ VLANها را جدا می‌کند. آن‌ها را به هم وصل نمی‌کند."], "summary": ""}, "nat": {"title": "NAT", "goal": "", "definition": "NAT آدرس‌های خصوصی زیاد را به چند آدرس عمومی ترجمه می‌کند تا شبکه شرکت به اینترنت برسد.", "explanation": "بازههایی مثل 192.168.0.0/16 خصوصی‌اند. همان عدد می‌تواند در شرکت‌های زیادی باشد و در اینترنت مسیریابی نمی‌شود. رایانه با آدرس خصوصی می‌فرستد. روتر ترجمه را به خاطر می‌سپارد و بیرون، آدرس عمومی خودش را نشان می‌دهد. پاسخ‌ها را دوباره برمی‌گرداند. برای همین یک سرور اینترنتی نمی‌تواند خودش 192.168.10.50 را صدا بزند.", "example": "192.168.10.50 کنار روتر می‌شود 203.0.113.5. اینترنت فقط 203.0.113.5 را می‌بیند.", "remember": ["داخل خصوصی، NAT در مرز، بیرون عمومی.", "192.168.10.50 در سراسر جهان یکتا نیست.", "NAT ترجمه نام نیست."], "summary": ""}, "ipv6": {"title": "IPv6", "goal": "", "definition": "IPv6 آدرس جدیدتر با ۱۲۸ بیت است. IPv4 فقط ۳۲ بیت دارد و موجودی آن کم است.", "explanation": "نوشتن شانزدهی است و دونقطه‌ها گروه‌ها را جدا می‌کنند. :: فقط یک بار می‌تواند یک رشته پیوسته از صفر را کوتاه کند. دو بار :: در یک آدرس نامعتبر است، چون طول نامعلوم می‌شود. 2001:db8::/32 برای مثال رزرو شده و شبکه واقعی یک شرکت نیست.", "example": "2001:0db8:85a3::8a2e:0370:7334 یک آدرس کوتاه‌شده IPv6 است، نه یک مقدار IPv4.", "remember": ["IPv6 صدوبیست‌وهشت بیت دارد، IPv4 سی‌ودو.", ":: فقط یک بار در هر آدرس.", "پیشوند مستندات: 2001:db8::/32."], "summary": ""}, "topo": {"title": "توپولوژی", "goal": "", "definition": "توپولوژی می‌گوید چه کسی به چه کسی وصل است.", "explanation": "در ستاره هر دستگاه به یک سوئیچ مرکزی وصل است. اگر یک کابل خراب شود، بقیه کار می‌کنند. اگر سوئیچ خراب شود، همه‌چیز می‌ایستد. باس یک کابل مشترک است و امروز کم دیده می‌شود. مش چند راه دارد، گران‌تر است، ولی در برابر خرابی مقاوم‌تر است. دفترها معمولاً ستاره دارند. دو سوئیچ هسته با یک اتصال ضربدری به یک مش کوچک نزدیک می‌شوند.", "example": "بیست رایانه روی یک سوئیچ طبقه یک ستاره‌اند. یک کابل خراب فقط همان رایانه را از کار می‌اندازد.", "remember": ["سوئیچ مرکزی نقطه خرابی تنها در ستاره است.", "ستاره اگر مرکز خراب شود حفاظتی ندارد.", "چند مسیر یعنی مش، نه ستاره."], "summary": ""}, "troubleshoot": {"title": "عیب‌یابی", "goal": "", "definition": "خرابی شبکه را با ترتیب ثابت بررسی می‌کنی، نه از فایروال، وقتی کابل شل است.", "explanation": "اول لینک و کابل. بعد در ویندوز ipconfig و در لینوکس ip addr: IP، ماسک و گیت‌وی داری؟ بعد پینگ به گیت‌وی خودت. بعد پینگ به 8.8.8.8 که به نام نیاز ندارد. تازه بعد از آن نام را امتحان کن. اگر گیت‌وی جواب بدهد و 8.8.8.8 نه، بیشتر مسیر خروج، NAT یا فایروال است. اگر خود گیت‌وی ساکت باشد، داخل شبکه خودت بگرد.", "example": "پینگ به 8.8.8.8 کار می‌کند، www.example.com نه. مسیر بیرون برقرار است، DNS نه.", "remember": ["ترتیب: لینک، IP، گیت‌وی، بیرون، نام.", "8.8.8.8 مسیر IP را می‌سنجد، نه DNS را.", "با نام شروع نکن."], "summary": ""}, "security": {"title": "امنیت در شبکه کوچک", "goal": "", "definition": "امنیت اینجا یعنی محدودیت: فقط پورت‌های لازم، فقط حق‌های لازم، مهمان جدا، سیستم به‌روز، و یک نسخه از داده‌ها.", "explanation": "پورت‌هایی را ببند که هیچ خدمتی لازم ندارد. کمترین امتیاز یعنی هر حساب فقط کار خودش را بکند. مهمان‌ها در VLAN خودشان می‌روند و نباید کورکورانه به شبکه داده راه داده شوند. به‌روزرسانی و پشتیبان را برنامه‌ریزی می‌کنی، به امید نمی‌سپاری. بین VLANها فایروال است. همه‌چیز را باز گذاشتن چون کار می‌کند، حمله را هم آسان‌تر می‌کند.", "example": "وای‌فای مهمان می‌تواند به اینترنت برود، ولی نه به فایل‌سرور. این VLAN به‌اضافه یک قاعده فایروال است، نه مسیریابی باز.", "remember": ["سطح کمتر: پورت، حق، شبکه.", "پشتیبان نسخه‌ای است پیش از آنکه چیزی گم شود.", "مهمان را به شبکه داخلی راه نده."], "summary": ""}}, "en": {"osi": {"title": "OSI model", "goal": "", "definition": "The OSI model is a layered way of thinking. It tells you where to look for a fault, not which cable to buy.", "explanation": "The bottom is the physical path, the top is the program. Four groups are enough in class. Layer 1 is cable, plug and link light. Layer 2 is the MAC address, the switch and the VLAN. Layer 3 is the IP address and the router. Layers 4 to 7 carry TCP or UDP, ports and programs such as the browser. Always search from the bottom up, because a dead link makes every higher test meaningless.", "example": "A ping to the gateway 192.168.10.1 works, but the website does not. Layer 3 is often fine. The name (DNS) or a higher block, such as a firewall, is the likely cause.", "remember": ["A VLAN is layer 2. It is not a kind of cable.", "A dark link light is checked on layer 1 first.", "Port 443 is a program door, not the socket on the switch."], "summary": ""}, "ip": {"title": "IP, mask and gateway", "goal": "", "definition": "The IPv4 address names the computer. The subnet mask says which part is the network. The gateway is the door out of that network, usually the router.", "explanation": "The same network ID means the partner is reachable directly and a switch is enough. A different network ID means the packet must go to the gateway. Without a gateway the computer stays in its own network even if the cable is plugged in. The mask /24 is 255.255.255.0. Then the first three numbers are the network.", "example": "The PC 192.168.10.50/24 reaches 192.168.10.10 directly. It reaches 192.168.20.10 only through the gateway 192.168.10.1.", "remember": ["Same network ID: direct. Different network ID: gateway.", "The gateway must sit in your own network, or the PC cannot find the door.", "Without a gateway you cannot reach 8.8.8.8."], "summary": ""}, "subnet": {"title": "Subnetting", "goal": "", "definition": "Subnetting cuts a large network into smaller blocks. The prefix length says how many bits belong to the network.", "explanation": "The block size is 2 to the power of (32 minus the prefix). Usable hosts are the block size minus 2, because the first address is the network and the last is the broadcast. /24 has 256 addresses and 254 hosts. /25 has 128 addresses and 126 hosts. /26 has 64 addresses and 62 hosts. A higher prefix makes the block smaller.", "example": "192.168.50.0/24 becomes 192.168.50.0/25 (0 to 127) and 192.168.50.128/25 (128 to 255).", "remember": ["/26 has 62 usable hosts, not 64.", "/25 is one half of a /24, not the same as /24.", "You must not give the network address or the broadcast to a host."], "summary": ""}, "vlan": {"title": "VLAN", "goal": "", "definition": "A VLAN is a logical network on one physical switch. Devices in different VLANs do not talk to each other until a router connects them.", "explanation": "An access port carries exactly one VLAN and belongs on a PC. A trunk port carries several VLANs with tags and belongs between switch and router. Typical: VLAN 10 office, VLAN 20 technical, VLAN 30 guests. The guest cannot see the file server until a route and a permission exist.", "example": "The uplink to a router-on-a-stick must be a trunk. As an access port only one VLAN would reach the router.", "remember": ["Access for end devices, trunk for several VLANs.", "A VLAN separates logically. It does not replace a router.", "Guests and the file server do not belong in the same VLAN."], "summary": ""}, "dhcp": {"title": "DHCP", "goal": "", "definition": "DHCP assigns the IP address, mask, gateway and often the DNS server automatically. The address is a lease for a limited time.", "explanation": "The sequence is called DORA. Discover: the client looks for a server because it does not know one yet. Offer: the server offers an address from the pool. Request: the client wants exactly that offer. Acknowledge: the server confirms the lease. Fixed devices such as the router stay outside the pool, or two owners share one address.", "example": "Pool 192.168.10.100 to 192.168.10.200. The router 192.168.10.1 must not be inside the pool.", "remember": ["Order: Discover, Offer, Request, Acknowledge.", "Discover is the search. Request is the acceptance.", "DHCP hands out addresses. It does not translate names."], "summary": ""}, "dns": {"title": "DNS", "goal": "", "definition": "DNS translates a name into an IP address. People remember the name, packets need the number.", "explanation": "An A record points a name to an IPv4 address. The resolver is the service the PC asks. Test the bare IP first. If the IP answers and the name does not, the path is fine and name resolution is broken. DNS and DHCP are different services: DHCP gives the address, DNS translates the name.", "example": "fileserver.firma.local should be 192.168.10.10. A ping to the number works, a ping to the name does not: check the record or the DNS server.", "remember": ["IP works, name does not: DNS.", "DHCP is not DNS.", "Ping the IP first, then the name."], "summary": ""}, "routing": {"title": "Routing", "goal": "", "definition": "Routing is the decision about which network a packet is sent to next.", "explanation": "If the destination is in your own network, a switch is enough. If it is in another network or VLAN, you need a router with a matching route. An administrator enters a static route by hand. The default route is the path for everything that does not match more closely. A normal layer-2 switch does not route between VLANs. Without a matching route the router drops the packet.", "example": "A PC in VLAN 10 does not reach VLAN 20 until the router has a route between the two networks.", "remember": ["Same network: switch. Other network: router.", "Inter-VLAN routing is the connection between VLANs.", "A layer-2 switch separates VLANs. It does not join them."], "summary": ""}, "nat": {"title": "NAT", "goal": "", "definition": "NAT translates many private addresses into a few public ones so the company network can reach the Internet.", "explanation": "Ranges such as 192.168.0.0/16 are private. The same number may exist in many companies and is not routed on the Internet. The PC sends with its private address. The router remembers the translation and shows its public address to the outside. It translates replies back. A server on the Internet therefore cannot call 192.168.10.50 on its own.", "example": "192.168.10.50 becomes 203.0.113.5 at the router. The Internet only sees 203.0.113.5.", "remember": ["Private inside, NAT at the border, public outside.", "192.168.10.50 is not unique worldwide.", "NAT is not name resolution."], "summary": ""}, "ipv6": {"title": "IPv6", "goal": "", "definition": "IPv6 is the newer address with 128 bits. IPv4 has only 32 bits, and the supply is tight.", "explanation": "The writing is hexadecimal, and colons separate the groups. :: may shorten one continuous run of zeros exactly once. Two :: in the same address are invalid, because the length would be unclear. 2001:db8::/32 is reserved for examples and is not a real company network.", "example": "2001:0db8:85a3::8a2e:0370:7334 is a shortened IPv6 address, not an IPv4 value.", "remember": ["IPv6 has 128 bits, IPv4 has 32.", ":: only once per address.", "Documentation prefix: 2001:db8::/32."], "summary": ""}, "topo": {"title": "Topology", "goal": "", "definition": "The topology describes who is connected to whom.", "explanation": "In a star, every device hangs on a central switch. If one cable fails, the rest keeps working. If the switch fails, everything stops. A bus is one shared cable and is rare today. A mesh has several paths and costs more, but survives failures better. Offices usually use a star. Two core switches with a cross link approach a small mesh.", "example": "Twenty PCs on one floor switch are a star. One broken PC cable takes down only that PC.", "remember": ["The central switch is the single point of failure in a star.", "A star has no protection if the centre fails.", "Several paths are a mesh, not a star."], "summary": ""}, "troubleshoot": {"title": "Troubleshooting", "goal": "", "definition": "You check a network fault in a fixed order, not at the firewall when the cable is loose.", "explanation": "First the link and the cable. Then ipconfig on Windows or ip addr on Linux: do you have an IP, a mask and a gateway? Then ping your own gateway. Then ping 8.8.8.8, which needs no name. Only then test the name. If the gateway answers and 8.8.8.8 does not, look at the route out, NAT or a firewall. If the gateway is already silent, look inside your own network.", "example": "Ping to 8.8.8.8 works, www.example.com does not. The path outside is up, DNS is not.", "remember": ["Order: link, IP, gateway, outside, name.", "8.8.8.8 tests the IP path, not DNS.", "Do not start with the name."], "summary": ""}, "security": {"title": "Security in a small network", "goal": "", "definition": "Security here means limits: only needed ports, only needed rights, separated guests, current systems and a copy of the data.", "explanation": "Close ports that no service needs. Least privilege means each account may do only its own job. Guests go into their own VLAN and must not be routed blindly into the data network. You schedule updates and backups, you do not hope for them. A firewall stands between VLANs. Leaving everything open because it works also makes an attack easier.", "example": "The guest Wi-Fi may reach the Internet, but not the file server. That is a VLAN plus a firewall rule, not open routing.", "remember": ["Less surface: ports, rights, networks.", "A backup is the copy before something is lost.", "Do not route guests into the internal network."], "summary": ""}}}, {"id": "it-technik", "grade": "11", "subject": {"de": "IT-Technik", "en": "IT technology", "fa": "فناوری IT"}, "order": ["iotcps", "sensor", "esp32", "pull", "prellen", "baud", "wlan", "mqtt"], "de": {"iotcps": {"title": "IoT und CPS", "goal": "", "definition": "IoT bedeutet: Dinge senden Daten über ein Netz. Ein cyber-physisches System koppelt Software und Physik in einem Kreis aus Messen, Entscheiden und Handeln.", "explanation": "Der Sensor misst die Welt. Die Software entscheidet. Der Aktor verändert die Welt. Danach wird wieder gemessen. Eine Lampe, die nur ihren Status in eine Cloud schreibt, ist vor allem IoT. Schaltet sie bei Bewegung selbst, ist der Kreis geschlossen und es ist ein CPS. Lernfeld 7 ergänzt ein bestehendes System im Kundenauftrag, es baut nicht zwingend eine neue Fabrik.", "example": "Ein Thermostat misst die Temperatur, schaltet die Heizung und misst wieder. Das ist ein CPS, nicht nur eine Netzverbindung.", "remember": ["Ohne Wirkung auf die Physik fehlt der Kreis.", "WLAN allein macht kein CPS.", "Messen, handeln, wieder messen."], "summary": ""}, "sensor": {"title": "Sensor und Aktor", "goal": "", "definition": "Ein Sensor wandelt eine physikalische Größe in ein Signal für die Software. Ein Aktor wandelt ein Signal in eine physikalische Wirkung.", "explanation": "Die Frage ist die Richtung. Kommt Information aus der Welt, ist es ein Sensor: Temperatur, Bewegung, Taster. Geht Wirkung in die Welt, ist es ein Aktor: Relais, Lampe, Motor, Ventil. Eine LED zeigt etwas, sie wirkt nach außen und ist deshalb ein Aktor, kein Sensor. Im Regelkreis brauchst du beide.", "example": "Ein Temperatursensor am Lager misst. Der Lüfter daneben ist der Aktor.", "remember": ["Sensor: Welt nach Signal. Aktor: Signal nach Welt.", "Ein Taster am ESP32 ist ein Sensor.", "Eine LED ist ein Aktor."], "summary": ""}, "esp32": {"title": "ESP32", "goal": "", "definition": "Der ESP32 ist ein Mikrocontroller mit WLAN. Im Arduino-Rahmen läuft setup einmal und loop immer wieder. Die Logik verträgt 3,3 Volt, nicht bedenkenlos 5 Volt.", "explanation": "In setup bereitest du Pins und WLAN einmal vor. In loop misst und sendest du immer wieder. pinMode steht in setup, weil sich der Modus nicht ständig ändert. EN an GND zieht einen harten Reset. USB kann 5 Volt liefern, die Eingänge innen sind 3,3 Volt. 5 Volt direkt auf einen GPIO kann den Eingang zerstören.", "example": "Temperatur lesen und per WLAN schicken steht in loop. Die Verbindung baust du in setup auf.", "remember": ["setup einmal, loop immer.", "Logikpegel 3,3 Volt.", "5 Volt nicht direkt auf GPIO legen."], "summary": ""}, "pull": {"title": "Pull-up und Pull-down", "goal": "", "definition": "Ein unbeschalteter Eingang schwebt. Er liest zufällig HIGH oder LOW. Ein Widerstand zieht ihn auf einen festen Pegel, solange der Taster offen ist.", "explanation": "Pull-down: Ruhe ist LOW, gedrückt gegen Plus ist HIGH. Pull-up: Ruhe ist HIGH, gedrückt gegen Masse ist LOW. Das nennt man Active Low. Viele Controller haben einen internen Pull-up. Ohne Zugwiderstand wunderst du dich über zufällige Werte, obwohl der Taster in Ordnung ist.", "example": "Interner Pull-up, Taster nach GND: losgelassen HIGH, gedrückt LOW.", "remember": ["Float bedeutet: kein definierter Pegel.", "Pull-up kehrt die Logik um: gedrückt ist LOW.", "Ohne Widerstand schwebt der Pin."], "summary": ""}, "prellen": {"title": "Prellen", "goal": "", "definition": "Metallkontakte federn. Ein Tastendruck ist elektrisch mehrere schnelle Wechsel. Der Controller zählt sonst jeden Wechsel als eigenen Druck.", "explanation": "Entprellen in Software: den ersten Wechsel erkennen, 10 bis 50 Millisekunden warten, den Pegel noch einmal lesen und nur den stabilen Wert zählen. Eine ganze Sekunde Wartezeit ist zu lang, der Taster wirkt dann tot. Ohne Filter kann ein Druck den Zähler von 0 auf 4 springen lassen.", "example": "Mit 20 Millisekunden Pause bleibt von drei elektrischen Wechseln ein Druck übrig.", "remember": ["Prellen ist mechanisch, kein WLAN-Fehler.", "Kurz warten, dann noch einmal lesen.", "Eine Sekunde ist kein gutes Entprellen."], "summary": ""}, "baud": {"title": "Baudrate", "goal": "", "definition": "Die Baudrate ist die Schrittgeschwindigkeit der seriellen Leitung. Sender und Empfänger müssen dieselbe Zahl verwenden.", "explanation": "Im Sketch steht Serial.begin(115200). Im Serial Monitor muss dieselbe Zahl stehen. 115200 ist am ESP32 üblich. Steht der Monitor auf 9600, siehst du Buchstabensalat, obwohl das Kabel stimmt. Es reicht nicht, nur eine Seite umzustellen.", "example": "Sketch 115200, Monitor 9600: Müll auf dem Schirm, kein Kabeldefekt.", "remember": ["Beide Seiten dieselbe Zahl.", "Wirre Zeichen bei gutem Kabel: Baudrate vergleichen.", "115200 ist ein üblicher ESP32-Wert, keine Pflicht für jedes Gerät."], "summary": ""}, "wlan": {"title": "WLAN am ESP32", "goal": "", "definition": "Der ESP32 tritt einem Funknetz mit SSID und Passwort bei. Erfolg siehst du an einer IP-Adresse im Serial Monitor, nicht nur an einer Lampe.", "explanation": "SSID und Passwort müssen exakt stimmen, einschließlich Großbuchstaben. Danach wartest du auf WL_CONNECTED und gibst IP und MAC aus. Ohne IP war der Beitritt nicht fertig. Viele Boards funken nur auf 2,4 Gigahertz. Ein Name wie google.de klappt danach nur, wenn auch DNS und das Gateway stimmen.", "example": "Der Monitor zeigt 192.168.4.12. Der Router hat den ESP32 aufgenommen.", "remember": ["IP im Monitor ist der Beleg, nicht die LED allein.", "Zuerst SSID, Passwort und 2,4 GHz prüfen.", "MAC ist die feste Adresse des Funkmoduls."], "summary": ""}, "mqtt": {"title": "MQTT", "goal": "", "definition": "MQTT ist ein leichtes Nachrichtenprotokoll für Geräte. Ein Broker nimmt Nachrichten an und gibt sie an Abonnenten weiter.", "explanation": "Ein Gerät veröffentlicht auf einem Topic, zum Beispiel lager/temp. Wer dieses Topic abonniert hat, bekommt die Zahl. Das Topic ist der Kanalname, kein OSI-Thema. QoS 0 heißt höchstens einmal: die Nachricht darf verloren gehen. QoS 1 heißt mindestens einmal: sie kann doppelt ankommen, geht aber nicht still verloren. MQTT transportiert keine 4K-Videos. Es trägt kurze Werte.", "example": "Der ESP32 veröffentlicht 21.5 auf lager/temp. Ein Rechner, der lager/temp abonniert hat, zeigt 21.5, ohne den ESP32 direkt zu kennen.", "remember": ["Broker in der Mitte, Topic als Kanal.", "QoS 0: höchstens einmal. QoS 1: mindestens einmal.", "MQTT ist kein DNS und kein DHCP."], "summary": ""}}, "fa": {"iotcps": {"title": "اینترنت اشیا و CPS", "goal": "", "definition": "اینترنت اشیا یعنی چیزها داده را از شبکه می‌فرستند. یک سیستم سایبر-فیزیکی نرم‌افزار و فیزیک را در حلقه سنجش، تصمیم و عمل به هم وصل می‌کند.", "explanation": "سنسور جهان را می‌سنجد. نرم‌افزار تصمیم می‌گیرد. عملگر جهان را عوض می‌کند. بعد دوباره سنجش می‌شود. چراغی که فقط وضعیتش را در ابر می‌نویسد بیشتر اینترنت اشیا است. اگر با حرکت خودش روشن شود، حلقه بسته است و CPS است. حوزه یادگیری ۷ یک سیستم موجود را برای سفارش مشتری کامل می‌کند و لزوماً یک کارخانه نو نمی‌سازد.", "example": "یک ترموستات دما را می‌سنجد، گرمایش را روشن می‌کند و دوباره می‌سنجد. این CPS است، نه فقط یک اتصال شبکه.", "remember": ["بدون اثر روی فیزیک، حلقه وجود ندارد.", "وای‌فای به‌تنهایی CPS نمی‌سازد.", "بسنج، عمل کن، دوباره بسنج."], "summary": ""}, "sensor": {"title": "سنسور و عملگر", "goal": "", "definition": "سنسور یک مقدار فیزیکی را به سیگنال برای نرم‌افزار تبدیل می‌کند. عملگر یک سیگنال را به اثر فیزیکی تبدیل می‌کند.", "explanation": "پرسش جهت است. اگر اطلاعات از جهان بیاید، سنسور است: دما، حرکت، کلید. اگر اثر به جهان برود، عملگر است: رله، چراغ، موتور، شیر. LED چیزی را نشان می‌دهد. به بیرون اثر می‌گذارد و برای همین عملگر است، نه سنسور. حلقه کنترل به هر دو نیاز دارد.", "example": "سنسور دما در انبار می‌سنجد. فن کنار آن عملگر است.", "remember": ["سنسور: جهان به سیگنال. عملگر: سیگنال به جهان.", "یک کلید روی ESP32 سنسور است.", "LED یک عملگر است."], "summary": ""}, "esp32": {"title": "ESP32", "goal": "", "definition": "ESP32 یک میکروکنترلر با وای‌فای است. در چارچوب آردوینو، setup یک بار اجرا می‌شود و loop همیشه. منطق ۳٫۳ ولت را تحمل می‌کند، نه بی‌احتیاط ۵ ولت را.", "explanation": "در setup پین‌ها و وای‌فای را یک بار آماده می‌کنی. در loop بارها می‌سنجی و می‌فرستی. pinMode در setup است چون حالت دائم عوض نمی‌شود. EN به GND یک بازنشانی سخت می‌کشد. USB می‌تواند ۵ ولت بدهد، ورودی‌های داخل ۳٫۳ ولت‌اند. ۵ ولت مستقیم روی GPIO می‌تواند ورودی را خراب کند.", "example": "خواندن دما و فرستادن آن با وای‌فای در loop است. اتصال را در setup می‌سازی.", "remember": ["setup یک بار، loop همیشه.", "سطح منطق ۳٫۳ ولت.", "۵ ولت را مستقیم روی GPIO نگذار."], "summary": ""}, "pull": {"title": "پول‌آپ و پول‌داون", "goal": "", "definition": "یک ورودی بی‌اتصال شناور است. تصادفی HIGH یا LOW می‌خواند. یک مقاومت تا وقتی کلید باز است آن را به یک سطح ثابت می‌کشد.", "explanation": "پول‌داون: حالت آزاد LOW است، فشردن به مثبت HIGH می‌شود. پول‌آپ: حالت آزاد HIGH است، فشردن به زمین LOW می‌شود. این را Active Low می‌نامند. بسیاری از کنترلرها پول‌آپ داخلی دارند. بدون مقاومت کششی مقدارهای تصادفی می‌بینی، هرچند کلید سالم باشد.", "example": "پول‌آپ داخلی، کلید به زمین: رها HIGH، فشرده LOW.", "remember": ["شناور یعنی سطح تعریف‌شده‌ای نیست.", "پول‌آپ منطق را برعکس می‌کند: فشرده یعنی LOW.", "بدون مقاومت پین شناور است."], "summary": ""}, "prellen": {"title": "پریدن کنتاکت", "goal": "", "definition": "کنتاکت فلزی می‌پرد. از نظر الکتریکی یک فشار چند تغییر سریع است. وگرنه کنترلر هر تغییر را یک فشار جدا می‌شمارد.", "explanation": "حذف پرش در نرم‌افزار: اولین تغییر را ببین، ۱۰ تا ۵۰ میلی‌ثانیه صبر کن، سطح را دوباره بخوان و فقط مقدار پایدار را بشمار. صبر یک ثانیه کامل زیاد است و کلید مرده به نظر می‌رسد. بدون فیلتر یک فشار می‌تواند شمارنده را از ۰ به ۴ ببرد.", "example": "با ۲۰ میلی‌ثانیه توقف، سه تغییر الکتریکی یک فشار می‌شود.", "remember": ["پرش مکانیکی است، نه خطای وای‌فای.", "کمی صبر کن، بعد دوباره بخوان.", "یک ثانیه حذف پرش خوبی نیست."], "summary": ""}, "baud": {"title": "نرخ باد", "goal": "", "definition": "نرخ باد سرعت گام خط سریال است. فرستنده و گیرنده باید همان عدد را به کار ببرند.", "explanation": "در اسکچ نوشته شده Serial.begin(115200). در نمایشگر سریال باید همان عدد باشد. ۱۱۵۲۰۰ روی ESP32 رایج است. اگر نمایشگر روی ۹۶۰۰ باشد حروف درهم می‌بینی، هرچند کابل سالم باشد. عوض کردن فقط یک طرف کافی نیست.", "example": "اسکچ ۱۱۵۲۰۰، نمایشگر ۹۶۰۰: آشغال روی صفحه، نه کابل خراب.", "remember": ["هر دو طرف یک عدد.", "حروف درهم با کابل سالم: نرخ باد را مقایسه کن.", "۱۱۵۲۰۰ مقدار رایج ESP32 است، نه قانون هر دستگاه."], "summary": ""}, "wlan": {"title": "وای‌فای روی ESP32", "goal": "", "definition": "ESP32 با SSID و گذرواژه به یک شبکه بی‌سیم می‌پیوندد. موفقیت را با یک آدرس IP در نمایشگر سریال می‌بینی، نه فقط با یک چراغ.", "explanation": "SSID و گذرواژه باید دقیق یکی باشند، از جمله حروف بزرگ. بعد منتظر WL_CONNECTED می‌مانی و IP و MAC را چاپ می‌کنی. بدون IP پیوستن تمام نشده است. بسیاری از بردها فقط روی ۲٫۴ گیگاهرتز کار می‌کنند. نامی مثل google.de بعد از آن فقط وقتی کار می‌کند که DNS و گیت‌وی هم درست باشند.", "example": "نمایشگر 192.168.4.12 را نشان می‌دهد. روتر ESP32 را پذیرفته است.", "remember": ["IP در نمایشگر دلیل است، نه LED به‌تنهایی.", "اول SSID، گذرواژه و ۲٫۴ گیگاهرتز را بررسی کن.", "MAC آدرس ثابت بخش رادیو است."], "summary": ""}, "mqtt": {"title": "MQTT", "goal": "", "definition": "MQTT یک پروتکل پیام سبک برای دستگاه‌هاست. یک کارگزار پیام را می‌گیرد و به مشترک‌ها می‌دهد.", "explanation": "یک دستگاه روی یک تاپیک منتشر می‌کند، مثلاً lager/temp. هر کس آن تاپیک را مشترک شده باشد عدد را می‌گیرد. تاپیک نام کانال است، نه موضوع OSI. QoS 0 یعنی حداکثر یک بار: پیام ممکن است گم شود. QoS 1 یعنی حداقل یک بار: ممکن است دو بار برسد، ولی بی‌صدا گم نمی‌شود. MQTT ویدیوی 4K حمل نمی‌کند. مقدارهای کوتاه را می‌برد.", "example": "ESP32 مقدار ۲۱٫۵ را روی lager/temp منتشر می‌کند. رایانه‌ای که lager/temp را مشترک شده ۲۱٫۵ را نشان می‌دهد، بدون اینکه ESP32 را مستقیم بشناسد.", "remember": ["کارگزار در وسط، تاپیک به‌عنوان کانال.", "QoS 0: حداکثر یک بار. QoS 1: حداقل یک بار.", "MQTT نه DNS است و نه DHCP."], "summary": ""}}, "en": {"iotcps": {"title": "IoT and CPS", "goal": "", "definition": "IoT means things send data over a network. A cyber-physical system couples software and physics in a loop of measure, decide and act.", "explanation": "The sensor measures the world. The software decides. The actuator changes the world. Then you measure again. A lamp that only writes its status to a cloud is mainly IoT. If it switches itself when there is motion, the loop is closed and it is a CPS. Learning field 7 adds to an existing system for a customer order. It does not necessarily build a new factory.", "example": "A thermostat measures temperature, switches the heating and measures again. That is a CPS, not only a network connection.", "remember": ["Without an effect on the physics, the loop is missing.", "Wi-Fi alone does not make a CPS.", "Measure, act, measure again."], "summary": ""}, "sensor": {"title": "Sensor and actuator", "goal": "", "definition": "A sensor turns a physical quantity into a signal for the software. An actuator turns a signal into a physical effect.", "explanation": "The question is the direction. If information comes from the world, it is a sensor: temperature, motion, a button. If an effect goes into the world, it is an actuator: relay, lamp, motor, valve. An LED shows something. It acts outward and is therefore an actuator, not a sensor. A control loop needs both.", "example": "A temperature sensor in the warehouse measures. The fan next to it is the actuator.", "remember": ["Sensor: world to signal. Actuator: signal to world.", "A button on the ESP32 is a sensor.", "An LED is an actuator."], "summary": ""}, "esp32": {"title": "ESP32", "goal": "", "definition": "The ESP32 is a microcontroller with Wi-Fi. In the Arduino frame, setup runs once and loop runs forever. The logic accepts 3.3 volts, not carelessly 5 volts.", "explanation": "In setup you prepare pins and Wi-Fi once. In loop you measure and send again and again. pinMode belongs in setup because the mode does not change all the time. EN to GND forces a hard reset. USB can supply 5 volts, the inputs inside are 3.3 volts. 5 volts directly on a GPIO can destroy the input.", "example": "Reading the temperature and sending it over Wi-Fi belongs in loop. You build the connection in setup.", "remember": ["setup once, loop forever.", "Logic level 3.3 volts.", "Do not put 5 volts directly on a GPIO."], "summary": ""}, "pull": {"title": "Pull-up and pull-down", "goal": "", "definition": "An unconnected input floats. It reads HIGH or LOW at random. A resistor pulls it to a fixed level while the button is open.", "explanation": "Pull-down: idle is LOW, pressed toward plus is HIGH. Pull-up: idle is HIGH, pressed toward ground is LOW. That is called active low. Many controllers have an internal pull-up. Without a pull resistor you see random values even though the button is fine.", "example": "Internal pull-up, button to ground: released HIGH, pressed LOW.", "remember": ["Float means no defined level.", "Pull-up reverses the logic: pressed is LOW.", "Without a resistor the pin floats."], "summary": ""}, "prellen": {"title": "Contact bounce", "goal": "", "definition": "Metal contacts bounce. Electrically, one press is several fast changes. Otherwise the controller counts each change as its own press.", "explanation": "Debounce in software: notice the first change, wait 10 to 50 milliseconds, read the level again and count only the stable value. Waiting a whole second is too long, the button then feels dead. Without a filter one press can jump the counter from 0 to 4.", "example": "With a 20 millisecond pause, three electrical changes become one press.", "remember": ["Bounce is mechanical, not a Wi-Fi fault.", "Wait briefly, then read again.", "One second is not a good debounce."], "summary": ""}, "baud": {"title": "Baud rate", "goal": "", "definition": "The baud rate is the step speed of the serial line. Sender and receiver must use the same number.", "explanation": "The sketch says Serial.begin(115200). The serial monitor must use the same number. 115200 is common on the ESP32. If the monitor is at 9600 you see garbage even though the cable is fine. Changing only one side is not enough.", "example": "Sketch 115200, monitor 9600: garbage on the screen, not a bad cable.", "remember": ["The same number on both sides.", "Garbage with a good cable: compare the baud rate.", "115200 is a common ESP32 value, not a rule for every device."], "summary": ""}, "wlan": {"title": "Wi-Fi on the ESP32", "goal": "", "definition": "The ESP32 joins a wireless network with an SSID and a password. You see success as an IP address in the serial monitor, not only as a lamp.", "explanation": "SSID and password must match exactly, including capital letters. Then you wait for WL_CONNECTED and print IP and MAC. Without an IP the join was not finished. Many boards radio only on 2.4 gigahertz. A name such as google.de works afterwards only if DNS and the gateway are also correct.", "example": "The monitor shows 192.168.4.12. The router has accepted the ESP32.", "remember": ["The IP in the monitor is the proof, not the LED alone.", "First check SSID, password and 2.4 GHz.", "The MAC is the fixed address of the radio module."], "summary": ""}, "mqtt": {"title": "MQTT", "goal": "", "definition": "MQTT is a lightweight messaging protocol for devices. A broker accepts messages and forwards them to subscribers.", "explanation": "A device publishes on a topic, for example lager/temp. Whoever subscribed to that topic receives the number. The topic is the channel name, not an OSI subject. QoS 0 means at most once: the message may be lost. QoS 1 means at least once: it can arrive twice, but it does not vanish quietly. MQTT does not carry 4K video. It carries short values.", "example": "The ESP32 publishes 21.5 on lager/temp. A computer that subscribed to lager/temp shows 21.5 without knowing the ESP32 directly.", "remember": ["Broker in the middle, topic as the channel.", "QoS 0: at most once. QoS 1: at least once.", "MQTT is not DNS and not DHCP."], "summary": ""}}}, {"id": "pug", "grade": "11", "subject": {"de": "Politik und Gesellschaft", "en": "Politics and society", "fa": "سیاست و جامعه"}, "order": ["struktur", "demo", "direkt", "gewalt", "bericht"], "de": {"struktur": {"title": "Artikel 20 Grundgesetz", "goal": "", "definition": "Artikel 20 sagt: Die Bundesrepublik ist ein demokratischer und sozialer Bundesstaat. Alle Staatsgewalt geht vom Volk aus.", "explanation": "Absatz 1 nennt die Grundsätze Republik, Demokratie, Sozialstaat und Bundesstaat. Absatz 2 erklärt die Ausübung: durch Wahlen und Abstimmungen und durch Gesetzgebung, Verwaltung und Rechtsprechung. Absatz 3 bindet die Gesetzgebung an die Verfassung, Verwaltung und Gerichte an Gesetz und Recht. Eine Mehrheit darf diese Bindung nicht einfach wegstimmen.", "example": "Ein Gesetz, das die Verfassung bricht, wird nicht dadurch gültig, dass viele Leute dafür waren. Darüber kann das Bundesverfassungsgericht entscheiden.", "remember": ["Demokratie ist an die Verfassung gebunden.", "Der Staat ist bundesstaatlich gegliedert.", "Verwaltung und Gerichte sind an Recht gebunden."], "summary": ""}, "demo": {"title": "Demokratie", "goal": "", "definition": "Demokratie heißt, dass Herrschaft vom Volk ausgeht und an Regeln gebunden bleibt, auch für die Mehrheit.", "explanation": "Dazu gehören regelmäßige, gleiche und geheime Wahlen, die Freiheit der Meinung und die Möglichkeit, eine Regierung abzulösen. Mehrere Parteien gehören dazu, weil eine einzige Liste keine echte Wahl ist. Ohne Rechtsstaat schützt der Stimmzettel die Minderheit nicht. Im Unterricht geht es um diese Prinzipien, nicht um das Programm einer Partei.", "example": "Du darfst eine Entscheidung der Schule sachlich kritisieren. Das ist Meinungsfreiheit, solange du keine Rechte anderer verletzt.", "remember": ["Wahlen müssen Machtwechsel möglich machen.", "Minderheiten behalten Rechte.", "Eine Stimme ist nicht die ganze Demokratie."], "summary": ""}, "direkt": {"title": "Direkt und repräsentativ", "goal": "", "definition": "Direkt heißt: die Bürger entscheiden selbst über eine Sache. Repräsentativ heißt: sie wählen Personen, die für sie entscheiden.", "explanation": "Der Bund ist im Kern repräsentativ. Der Bundestag und die Landtage beschließen die Gesetze. Direkte Elemente gibt es zusätzlich, etwa Bürgerbegehren in Gemeinden oder Volksentscheide nach Landesrecht. Sie ersetzen den Bundestag nicht. Wer gewählt ist, entscheidet im Auftrag und auf Zeit, nicht als Eigentümer der Macht.", "example": "Die Klasse wählt eine Sprecherin für den Klassenrat: repräsentativ. Alle stimmen selbst über das Ziel des Wandertags ab: direkt.", "remember": ["Deutschland ist vor allem repräsentativ.", "Direkte Abstimmung kann dazukommen.", "Ein Mandat ist befristet."], "summary": ""}, "gewalt": {"title": "Gewaltenteilung", "goal": "", "definition": "Gesetzgebung, ausführende Gewalt und Rechtsprechung sind getrennt, damit niemand alles allein entscheiden kann.", "explanation": "Das Parlament beschließt Gesetze. Regierung und Verwaltung führen sie aus. Gerichte entscheiden Streit unabhängig. Jede Gewalt kann die andere begrenzen. Artikel 20 nennt genau diese drei. Die Polizei gehört zur ausführenden Gewalt. Sie ermittelt, sie spricht aber nicht das Urteil.", "example": "Die Polizei nimmt einen Verdacht auf. Die Strafe setzt ein Gericht fest, nicht die Dienststelle.", "remember": ["Drei Gewalten, drei Aufgaben.", "Gerichte sind nicht die Behörde der Regierung.", "Kontrolle ist der Zweck der Trennung."], "summary": ""}, "bericht": {"title": "Ausbildungsnachweis", "goal": "", "definition": "Der Ausbildungsnachweis, oft Berichtsheft genannt, hält fest, welche Tätigkeiten du in der Ausbildung wirklich gemacht hast.", "explanation": "Das Berufsbildungsgesetz verlangt diesen schriftlichen Nachweis. Du schreibst ihn selbst. Der Ausbilder sieht ihn durch und unterschreibt. Er ist kein Stimmungstext und keine Kopie der Hausaufgabe. Ein brauchbarer Eintrag nennt Tätigkeit, Umfang und den Bezug zur Ausbildung. Dafür gibt es Zeit während der Ausbildung. Die Kammer kann den Nachweis zur Prüfung verlangen. Leere Wochen am Ende nachzuschreiben fällt auf.", "example": "„3 Stunden: Ports am Patchpanel beschriftet und mit dem Switch-Plan abgeglichen.“ Das ist ein Eintrag. „War anstrengend“ ist keiner.", "remember": ["Tätigkeit nennen, nicht die Stimmung.", "Regelmäßig schreiben.", "Unterschrift der ausbildenden Person gehört dazu."], "summary": ""}}, "fa": {"struktur": {"title": "اصل ۲۰ قانون اساسی", "goal": "", "definition": "اصل ۲۰ می‌گوید: جمهوری فدرال دولتی دموکراتیک، اجتماعی و فدرال است. همه قدرت دولت از مردم می‌آید.", "explanation": "بند ۱ اصول جمهوری، دموکراسی، دولت اجتماعی و دولت فدرال را نام می‌برد. بند ۲ شیوه اجرا را می‌گوید: با انتخابات و رأی و با قانون‌گذاری، اداره و دادگاه. بند ۳ قانون‌گذاری را به قانون اساسی و اداره و دادگاه را به قانون و حق مقید می‌کند. یک اکثریت نمی‌تواند این قید را کنار بزند.", "example": "قانونی که قانون اساسی را بشکند، با موافقت عده زیاد معتبر نمی‌شود. دادگاه قانون اساسی فدرال می‌تواند درباره آن تصمیم بگیرد.", "remember": ["دموکراسی به قانون اساسی مقید است.", "دولت به شکل فدرال سازمان یافته است.", "اداره و دادگاه‌ها به حق مقیدند."], "summary": ""}, "demo": {"title": "دموکراسی", "goal": "", "definition": "دموکراسی یعنی قدرت از مردم می‌آید و به قاعده مقید می‌ماند، حتی برای اکثریت.", "explanation": "انتخابات منظم، برابر و مخفی، آزادی نظر و امکان عوض کردن دولت جزو آن است. چند حزب لازم است، چون یک فهرست واحد انتخاب واقعی نیست. بدون دولت قانون، برگه رأی از اقلیت محافظت نمی‌کند. درس درباره این اصول است، نه برنامه یک حزب.", "example": "می‌توانی یک تصمیم مدرسه را واقع‌بینانه نقد کنی. این آزادی نظر است، تا وقتی حق دیگران را نقض نکنی.", "remember": ["انتخابات باید عوض شدن قدرت را ممکن کند.", "اقلیت‌ها حق خود را نگه می‌دارند.", "یک رأی تمام دموکراسی نیست."], "summary": ""}, "direkt": {"title": "مستقیم و نمایندگی", "goal": "", "definition": "مستقیم یعنی شهروندان خودشان درباره یک موضوع تصمیم می‌گیرند. نمایندگی یعنی کسانی را انتخاب می‌کنند که برایشان تصمیم بگیرند.", "explanation": "فدراسیون در هسته نمایندگی است. بوندستاگ و مجلس‌های ایالتی قانون را تصویب می‌کنند. عنصر مستقیم هم هست، مثل درخواست محلی یا همه‌پرسی طبق قانون ایالت. آن‌ها جای بوندستاگ را نمی‌گیرند. فرد انتخاب‌شده به نمایندگی و برای یک دوره تصمیم می‌گیرد، نه به‌عنوان مالک قدرت.", "example": "کلاس یک سخنگو برای شورای کلاس انتخاب می‌کند: نمایندگی. همه خودشان درباره مقصد گردش رأی می‌دهند: مستقیم.", "remember": ["آلمان عمدتاً نمایندگی است.", "رأی مستقیم می‌تواند اضافه شود.", "یک نمایندگی زمان‌دار است."], "summary": ""}, "gewalt": {"title": "تفکیک قوا", "goal": "", "definition": "قانون‌گذاری، قوه مجریه و قضاوت جدا هستند تا هیچ‌کس نتواند همه‌چیز را تنها تصمیم بگیرد.", "explanation": "مجلس قانون را تصویب می‌کند. دولت و اداره آن را اجرا می‌کنند. دادگاه اختلاف را مستقل حل می‌کند. هر قوه می‌تواند دیگری را محدود کند. اصل ۲۰ دقیقاً همین سه تا را نام می‌برد. پلیس جزو قوه مجریه است. تحقیق می‌کند، ولی حکم صادر نمی‌کند.", "example": "پلیس یک ظن را پیگیری می‌کند. مجازات را دادگاه تعیین می‌کند، نه اداره پلیس.", "remember": ["سه قوه، سه کار.", "دادگاه اداره دولت نیست.", "هدف جدایی کنترل است."], "summary": ""}, "bericht": {"title": "گزارش آموزش", "goal": "", "definition": "گزارش آموزش، که اغلب دفتر گزارش نامیده می‌شود، ثبت می‌کند کدام کارها را واقعاً در آموزش انجام داده‌ای.", "explanation": "قانون آموزش شغلی این مدرک نوشتاری را می‌خواهد. خودت می‌نویسی. مربی آن را می‌بیند و امضا می‌کند. متن حال‌وهوا نیست و کپی تکلیف هم نیست. یک نوشته مفید کار، مدت و ربط آن به آموزش را نام می‌برد. برای نوشتنش در زمان آموزش وقت هست. اتاق می‌تواند این مدرک را برای آزمون بخواهد. پر کردن هفته‌های خالی در آخر معلوم می‌شود.", "example": "«۳ ساعت: درگاه‌های پچ‌پنل را برچسب زدم و با طرح سوئیچ تطبیق دادم.» این یک نوشته است. «خسته‌کننده بود» نیست.", "remember": ["کار را نام ببر، نه حال را.", "منظم بنویس.", "امضای مربی جزو آن است."], "summary": ""}}, "en": {"struktur": {"title": "Article 20 of the Basic Law", "goal": "", "definition": "Article 20 says: the Federal Republic is a democratic and social federal state. All state authority comes from the people.", "explanation": "Paragraph 1 names the principles of a republic, a democracy, a social state and a federal state. Paragraph 2 explains how power is used: through elections and votes and through legislation, administration and courts. Paragraph 3 binds legislation to the constitution, and administration and courts to law and justice. A majority may not simply vote that bond away.", "example": "A law that breaks the constitution does not become valid because many people were in favour. The Federal Constitutional Court can decide that.", "remember": ["Democracy is bound by the constitution.", "The state is organised as a federation.", "Administration and courts are bound by law."], "summary": ""}, "demo": {"title": "Democracy", "goal": "", "definition": "Democracy means that authority comes from the people and stays bound by rules, including for the majority.", "explanation": "That includes regular, equal and secret elections, freedom of opinion and the chance to replace a government. Several parties belong to it, because a single list is not a real election. Without the rule of law the ballot does not protect the minority. Class is about these principles, not about one party’s programme.", "example": "You may criticise a school decision in a factual way. That is freedom of opinion, as long as you do not violate other people’s rights.", "remember": ["Elections must make a change of power possible.", "Minorities keep their rights.", "A vote is not the whole of democracy."], "summary": ""}, "direkt": {"title": "Direct and representative", "goal": "", "definition": "Direct means the citizens decide a matter themselves. Representative means they elect people who decide for them.", "explanation": "The federation is representative at its core. The Bundestag and the state parliaments pass the laws. Direct elements exist as well, such as local petitions or referendums under state law. They do not replace the Bundestag. An elected person decides on behalf of others and for a term, not as the owner of power.", "example": "The class elects a spokesperson for the class council: representative. Everyone votes on the trip destination themselves: direct.", "remember": ["Germany is mainly representative.", "A direct vote can be added.", "A mandate is limited in time."], "summary": ""}, "gewalt": {"title": "Separation of powers", "goal": "", "definition": "Legislation, executive power and the courts are separated so that nobody can decide everything alone.", "explanation": "Parliament passes laws. Government and administration carry them out. Courts decide disputes independently. Each power can limit the others. Article 20 names exactly these three. The police belong to the executive. They investigate, but they do not pass judgment.", "example": "The police take up a suspicion. A court sets the penalty, not the police station.", "remember": ["Three powers, three jobs.", "Courts are not a government office.", "Control is the point of the split."], "summary": ""}, "bericht": {"title": "Training record", "goal": "", "definition": "The training record, often called a report book, states which tasks you actually did in training.", "explanation": "The Vocational Training Act requires this written record. You write it yourself. The trainer reviews it and signs it. It is not a mood text and not a copy of homework. A useful entry names the task, the amount of time and the link to the training. There is time for it during training. The chamber can require the record for the exam. Filling empty weeks at the end is obvious.", "example": "“3 hours: labelled ports on the patch panel and checked them against the switch plan.” That is an entry. “It was tiring” is not.", "remember": ["Name the task, not the mood.", "Write it regularly.", "The trainer’s signature belongs on it."], "summary": ""}}}];